window.__D("text/torat-menachem/c050",{"p":[[1400260004,"<h3>בס\"ד. מוצש\"ק פ' בשלח, יו\"ד שבט, ה'תשי\"ז<sup data-n=\"1\">*</sup></h3>\n(הנחה בלתי מוגה)\n<b>באתי</b><sup data-n=\"2\">1</sup> לגני אחותי כלה<sup data-n=\"3\">2</sup>. ואיתא במד\"ר במקומו<sup data-n=\"4\">3</sup> לגני לגנוני, דעיקר שכינה בתחתונים היתה, אלא שעל ידי חטא עה\"ד והחטאים שלאחריו סילקו את השכינה מן הארץ עד לרקיע הז' (כפי שמפרש במדרש), ואח\"כ ע\"י עבודת הצדיקים הורידו והמשיכו את השכינה מלמעלה למטה, עד שבא משה שהוא השביעי, וכל השביעין חביבין<sup data-n=\"5\">4</sup>, והורידה מרקיע הא' למטה בארץ, שזוהי תכלית כל ההמשכות. ועיקר גילוי השכינה הי' במשכן ומקדש, כמ\"ש<sup data-n=\"6\">5</sup> ועשו לי מקדש ושכנתי בתוכם, היינו, שע\"י המקדש נעשה ושכנתי גם בתוך כל אחד ואחד<sup data-n=\"7\">6</sup> – ע\"י עבודת הצדיקים, כפי שמבאר בעל ההילולא בארוכה בהמאמר של יום ההילולא<sup data-n=\"8\">7</sup> מאמר הזהר<sup data-n=\"9\">8</sup> כד אתכפיא סט\"א (ואתהפכא סט\"א) אסתלק יקרא דקוב\"ה בכולהו עלמין, שע\"י העבודה דאתכפיא ואתהפכא נמשך יקרא דקוב\"ה (גילוי אור) שהוא בכולהו עלמין בשוה, היינו, אור שלמעלה מעולמות, למעלה גם מאור הסובב כל עלמין (כפי ששייך לעולמות בבחינת סובב עכ\"פ<sup data-n=\"10\">9</sup>), שזוהי המשכת עיקר שכינה, ועד באופן נעלה יותר מכמו שהיתה ההמשכה בתחלת הבריאה. וזהו<sup data-n=\"11\">10</sup> ג\"כ ענין עבודת הקרבנות שהי' במשכן ומקדש, שזוהי ההעלאה מלמטה למעלה שפועלת ההמשכה דריח ניחוח מלמעלה למטה.<b>וממשיך</b> ומבאר בהמאמר<sup data-n=\"12\">11</sup> שזהו מש\"נ במשכן (שעליו נאמר&lt;5&gt; ועשו לי מקדש) ועשית את הקרשים למשכן עצי שטים עומדים<sup data-n=\"13\">12</sup>, דשטה פי' נטי'<sup data-n=\"14\">13</sup>, כמ\"ש<sup data-n=\"15\">14</sup> שטו העם, והיינו הנטי' מדרך המלך מלכו של עולם, שהוא מצד הרוח שטות שנכנסה בהם, כמאמר<sup data-n=\"16\">15</sup> אין אדם עובר עבירה אא\"כ נכנס בו רוח שטות, והעבודה היא להפוך את השטות דלעו\"ז ע\"י שטות (שטים) דקדושה, שזוהי העבודה שעל ידה נעשה המשכת עיקר שכינה בתחתונים.\n<b>ומוסיף</b> לבאר<sup data-n=\"17\">16</sup>, שבזה מדוייק גם שמעצי שטים עומדים עשו קרשים דוקא. דהנה, תיבת קרש מורכבת מג' אותיות ק' ר' ש', ואיתא בזהר<sup data-n=\"18\">17</sup> דאות ש' היא מסטרא דקשוט, משא\"כ אותיות ק' ור' הן מסטרא דלעו\"ז. ומבאר בהמאמר, שלנגד אות ר' שהיא מסטרא דלעו\"ז, ישנה אות ד' שהיא מסטרא דקדושה, דאף שלכאורה התוכן והפירוש דדלי\"ת ורי\"ש הוא מלשון דלות ורישות, היינו, ששניהם מורים על עוני, מ\"מ, הרי הם שונים זה מזה לגמרי<sup data-n=\"19\">18</sup>, עד כדי כך שכאשר יחליף דל\"ת ברי\"ש הרי זה מחריב עולמות<sup data-n=\"20\">19</sup>. ומוסיף לבאר גם ההפרש בין תמונת אות ד' לתמונת אות ר', שבאות ד' שמסטרא דקדושה, ניתוסף יו\"ד מאחוריו שאינו באות ר'. דאות י' הוא נקודה שענינה אזעירת גרמה<sup data-n=\"21\">20</sup>, שאין לו תפיסת מקום בעיני עצמו, ענין הביטול, שעי\"ז נעשה כלי לקבלה, וכמשל התלמיד שדוקא ע\"י ביטולו כדבעי נעשה כלי לקבל השפעת הרב, וכן הוא בכללות סטרא דקדושה, שדוקא ע\"י הביטול, נקודת היו\"ד, נעשה כלי לקבל כל הענינים מלמעלה, כמבואר בארוכה בהמאמר דיום ההילולא<sup data-n=\"22\">21</sup> והמשכו<sup data-n=\"23\">22</sup> בסעיפים הקודמים (א-ו)<sup data-n=\"24\">23</sup>.\nב) <b>וממשיך</b> בהמאמר בסעיף החדש<sup data-n=\"25\">24</sup>, שהיו\"ד שבאות ד' שהוא מאחוריו, עם שהוא אות זעירא מכל האותיות (שהו\"עהביטול, אזעירת גרמה, כנ\"ל), הנה הוא ראש לכל האותיות, דכל אות הרי תחלתו אות יו\"ד, והוא מה שביו\"ד נברא העולם הבא<sup data-n=\"26\">25</sup>.\n<b>וכללות</b> הביאור בזה, דהנה, לעיל בהמאמר נתבאר ענין היו\"ד, אזעירת גרמה, שהוא הביטול של המקבל והתלמיד, שעל ידו נעשה כלי לקבל כל ההשפעות וההמשכות מלמעלה. וכאן מוסיף לבאר ענין נעלה יותר בהיו\"ד – כמו שהוא מצד המשפיע, היינו, שגם אופן המשכת ההשפעה מהרב שיוכל להשפיע למטה אל המקבל, מרומז באות היו\"ד, שזהו מה שהיו\"ד הוא ראש לכל האותיות, היינו, שכל ההמשכות וההשפעות למטה שהם ע\"י אותיות, שהרי אותיות הם מלשון אתא בוקר<sup data-n=\"27\">26</sup>, שמורה על כללות ההמשכה וההשפעה למטה, הנה ההתחלה בזה היא מנקודת היו\"ד (שהיא ראש לכל האותיות). ומוסיף לבאר בנוגע לעניננו, שזהו\"ע שביו\"ד נברא העוה\"ב.\n<b>והענין</b> בזה, שכללות ענין היו\"ד, אזעירת גרמה, שהו\"ע הביטול בתכלית – ענינו אצל המשפיע הוא הצמצום ועד לסילוק לגמרי, שעי\"ז דוקא אפשר להיות ההשפעה וההמשכה למטה. וכפירוש הבעש\"ט&lt;א&gt; עה\"פ<sup data-n=\"28\">27</sup> ויאמר אלקים יהי אור (דלכאורה אינו מובן מהי השייכות דשם אלקים לאור, שענינו אור וגילוי, המשכה והשפעה), \"ויאמר הש\"י מכח מדת אלקים שהוא מדת גבורה המצמצם האור, מחמת זה יהי אור המתקיים שיוכל העולם לסובלו\". והרב המגיד&lt;ב&gt; מוסיף ביאור בסיום הפסוק ויהי אור, ד\"אמרו רז\"ל<sup data-n=\"29\">28</sup> כל מקום שנאמר ויהי הוא לשון צער, וז\"ש ויהי אור, ר\"ל מכח הצמצום שהוא נראה כמו צער לעולם כו', אדרבה ממנו נעשה האור האמיתי וקיום העולם\", וכ\"אומרו ויהי ערב ויהי בוקר כו', כי מן הערב שהוא הצמצום נעשה ונתהוה הבוקר\", היינו, שאין זה האור שהי' מקודם, שהי' אוא\"ס ממלא את מקום החלל ולא הי' מקום למציאות כלל<sup data-n=\"30\">29</sup>, אלא אור שבא ע\"י צמצום, שזהו\"ע ויהי אור, ויהי לשון\n<b>&lt;א&gt;</b>) כש\"ט ח\"ב בסופו (בהוצאת קה\"ת – סי' רמז).\n<b>&lt;ב&gt;</b>) או\"ת עה\"פ (בהוצאת קה\"ת – בראשית ב, א-ב).צער, שזהו הצמצום שעל ידו נעשה מציאות האור שלמטה. ובמק\"א<sup data-n=\"31\">30</sup> מוסיף לבאר שזהו \"כמשל אב (ש)מצמצם את שכלו ומדבר דברי קטנות בשביל בנו הקטן, וגם כל מדות מעשה נערות נולדים בהאב, שאוהב את מעשה נערות כדי שיהי' להבן תענוג כו'\", ודוגמתו בנמשל, שהצמצום שהקב\"ה מצמצם את עצמו הוא בשביל ישראל, כמארז\"ל<sup data-n=\"32\">31</sup> בראשית (ברא אלקים, שהו\"ע הצמצום) בשביל ישראל שנקראו ראשית, שישראל הם בניו של הקב\"ה, כמ\"ש<sup data-n=\"33\">32</sup> בנים אתם להוי' אלקיכם, ובשבילם מצמצם הקב\"ה את עצמו. ומסיים הרב המגיד ש\"צמצום נקרא חכמה, כי החכמה הוא האי\"ן ע\"ד והחכמה<sup data-n=\"34\">33</sup> מאין תמצא\". וזהו ענין נקודת היו\"ד אצל המשפיע (בדוגמת נקודת היו\"ד שאצל המקבל, הביטול דאזעירת גרמה שעי\"ז נעשה כלי מוכן ומוכשר לקבל את כל הענינים של הרב והמשפיע), שכדי שיהי' אור המתקיים, היינו, שיהי' מקום למציאות, והמציאות תוכל לקבל האור, ה\"ז רק ע\"י ויהי לשון צער, ענין הצמצום, שנקרא חכמה, שזהו נקודת היו\"ד.\nג) <b>וביאור</b> הענין&lt;ג&gt;, וגם להבין אומרו ביו\"ד נברא עוה\"ב דוקא, הנה ידוע שעוה\"ב בכללותו ענינו קבלת שכר על התורה ועבודה במשך שית אלפי שנין דהוה עלמא שנקרא בשם עוה\"ז, ואח\"כ בא העוה\"ב שנעשה ע\"י תורתם ועבודתם, ובשביל שכר זה דעוה\"ב ירדה הנשמה ירידה גדולה מאיגרא רמה לבירא עמיקתא<sup data-n=\"36\">35</sup>. דהנה, אף שקודם הירידה למטה היתה הנשמה בעילוי גדול ביותר, ששייכת רק לעניני אלקות, וכמ\"ש<sup data-n=\"37\">36</sup> חי הוי' אשר עמדתי לפניו, אין עמידה אלא תפלה<sup data-n=\"38\">37</sup>, וא\"כ הירידה למטה לבירא עמיקתא היא ירידה גדולה ביותר, הנה ירידה זו היא צורך עלי', שעי\"ז עולה למעלה יותר מכמו שהיתה קודם ירידתה. וכללות ענין העלי' הוא כמ\"ש<sup data-n=\"39\">38</sup> אחת שאלתי מאת הוי' גו' לחזות בנועם הוי', דנועם\n<b>&lt;ג&gt;</b>) בהבא לקמן (ס\"ג-ד) – ראה ד\"ה וביאור הענין תרס\"ח (סה\"מ תרס\"ח ע' קסב ואילך)<sup data-n=\"35\">34</sup>.הוי' הוא הנועם שנמשך משם הוי' (כמ\"ש בזהר<sup data-n=\"40\">39</sup>), שעיקרו הוא אות יו\"ד (התחלת שם הוי'), שזהו ביו\"ד נברא העוה\"ב<sup data-n=\"41\">40</sup>, ובשביל לחזות בנועם הוי' כדאי כל הירידה.\n<b>והענין</b> בזה, דהנה נועם הוא ענין התענוג, וכמו ויהי נועם<sup data-n=\"42\">41</sup> שענינו תענוג. ויובן מכח התענוג למטה בנפש האדם, שהוא חלוק ונעלה משאר כחות הנפש, למעלה גם מגילוי התרחבות והתפשטות הנפש שמצד התנועה דשמחה שפורצת גדר<sup data-n=\"43\">42</sup> ומבטלת כל המדידות וההגבלות, כי, פעולת השמחה היא שהנפש וכל כחותי' הם בתנועה של התפשטות, ועד שנמשך ופועל גם באברי הגוף עד לרגלים, שזהו\"ע הריקודים. אבל, כל זה אינו התגלות פנימיות הכחות, כי אם שהכחות <b>כמו שהם</b> באים בהתרחבות והתפשטות ועד שנמשך ומתגלה גם בחיצוניות, בהריקוד ברגלים. משא\"כ תענוג, הנה אף שגם הוא פועל התרחבות והתפשטות, כמ\"ש<sup data-n=\"44\">43</sup> שמועה טובה תדשן עצם, הרי אין זה באופן של התרחבות והתפשטות בחיצוניות, וכמו שרואים במוחש שכאשר האדם מתענג באיזה דבר תענוג אינו בבחי' תנועה בגופו כמו בריקוד וכה\"ג, אלא אדרבה, מצד התענוג ה\"ה במנוחה, וא\"כ, פעולת ההתרחבות (תדשן עצם) אינה באופן שהכחות <b>כמו שהם</b> באים בהתרחבות והתפשטות יותר, כי אם שממשיכים <b>מפנימיות ועצמיות</b> הכחות, והמשכה זו (מפנימיות ועצמיות הכחות) מתגלה ובאה גם בהכחות כמו שהם. ונמצא, שהעונג מגלה הפנימיות והעצמיות שיבוא בפועל. ודוגמתו למעלה, שנועם הוי', העונג הנמשך משם הוי', שעיקרו אות יו\"ד, ביו\"ד נברא העוה\"ב, הוא גילוי הפנימיות והעצמיות דלמעלה. אמנם, כדי שיוכל להיות הגילוי דנועם הוי', גילוי הפנימיות והעצמיות דלמעלה, צ\"ל תחלה ענין הצמצום, המרומז באות יו\"ד דשם הוי', ועי\"ז יוכל להיות אח\"כ גילוי הפנימיות והעצמיות, שהו\"ע נועם הוי' שמתגלה בעוה\"ב, שעז\"נ ביו\"ד נברא העוה\"ב.\nד) <b>והענין</b> הוא, דהנה, בתחלה הי' אוא\"ס ממלא את מקום החלל ולא הי' מקום למציאות כלל&lt;29&gt;, ואף שבו הי' כלול ג\"כ האור המוגבל שאח\"כ נתהווה ממנו המציאות, מ\"מ, להיותו כלול באור א\"ס,לא הי' ניכר לעצמו כלל, ולכן הוצרך להיות הצמצום והסילוק שעי\"ז יהי' מקום למציאות. וכידוע המשל על זה מרב ותלמיד, דכאשר הרב רוצה להשפיע שכל לתלמיד שאינו בערכו כלל, הנה אף שבודאי יש בהמשפיע גם אותו השכל שלפי ערך התלמיד, הרי שכל זה כלול ובטל באור שכלו של הרב שמשכיל לעצמו, והשכל שלפי ערך התלמיד אינו ניכר כלל, ולכן צריך שיסלק את אור שכלו לגמרי, ואז דוקא יכול להיות המשכת אור השכל שבערך התלמיד המקבל. ולא עוד אלא שגם לאחרי שנמשך אור השכל שלפ\"ע התלמיד, הרי זה עדיין כפי <b>שהרב</b> ממשיך את השכל, ולכן, גם לאחרי שנמשך אור השכל שלפ\"ע התלמיד, צריך הרב לשער תחילה כלי שכלו של התלמיד, ורק לאחרי שמשער כלי המקבל, אזי ממשיך מנקודת השכל שלפ\"ע התלמיד כפי שהוא אצל הרב, שיומשך למטה לשטח המקבל. ודוגמתו למעלה בהתהוות כל המציאות וכל סדר ההשתלשלות, שכללות ההתהוות היא ע\"י שם הוי', ע\"ש הי' הוה ויהי'<sup data-n=\"45\">44</sup>, יש בזה הסדר דד' אותיות שם הוי', מהצמצום הנרמז באות יו\"ד, עד לשטח המקבל הנרמז באות ה\"א אחרונה. דהנה, תחלה צ\"ל הצמצום והסילוק שעל ידו יהי' ניכר חיצוניות האור, היינו, האור המוגבל, שנותן מקום למציאות, שאור מוגבל זה לא הי' ניכר תחילה כשהי' אור א\"ס ממלא את מקום החלל, כי, אף שגם הוא אינו אלא <b>אור</b> א\"ס, אור בלבד ולא עצם, מ\"מ, להיותו כמו שהוא בלי צמצומים, ה\"ה לפי ערך העצם, היינו בלי גבול, אלא שלהיותו שלימותא דכולא, הרי כשם שיש לו כח בבלי גבול כך יש לו כח בגבול<sup data-n=\"46\">45</sup>, אבל אעפ\"כ, הכח בגבול אינו ניכר, כיון שבגלוי ישנו כח הבלי גבול, אור הבלי גבול. ולזה הוצרך להיות צמצום הראשון שנקרא בשם סילוק, שעל ידו נבדל וניכר חיצוניות האור, וגם חיצוניות האור נתצמצם באופן שיוכל להיות ממנו התהוות מציאות העולמות. והיינו, שפעולת הצמצום היא בב' ענינים. ענין הא', שאור הגבול נבדל מאור הבלי גבול וניכר בפ\"ע, ויתירה מזה, ענין הב', שבאור הגבול גופא (לאחרי שניכר בפ\"ע) לא יהי' ריבוי אור כמו שהי' קודם הצמצום, שאז הי' גם אור הגבול לפי ערך העצם, ולכן הי' בו ריבוי אור, ופעולת הצמצום היא שלא יהי' בו ריבוי אור. וכל זה שייך רק ב<b>אור</b> א\"ס, שלהיותו אור בלבד ולא עצם, שייך בו ב' ענינים הנ\"ל. ההתחלקות דפנימיות האור וחיצוניות האור (אור הבלי גבול ואור הגבול), וענין הצמצום, ששייך רק באור ולא במאור.<b>ועד\"ז</b> בנוגע לבריאת העולמות, שבאוא\"ס שלפני הצמצום הי' תחלת עליית הרצון על העולמות, ורצון זה יש בו גם ענין העונג, כמארז\"ל<sup data-n=\"47\">46</sup> על הפסוק<sup data-n=\"48\">47</sup> שוקיו עמודי שש, שוקיו זה העולם שנשתוקק הקב\"ה לבראותו, שזהו\"ע התענוג, הנה קודם הצמצום יש בהתענוג ריבוי ותוקף ביותר, ואי אפשר להיות מזה התהוות המציאות, ולכן הוצרך להיות ענין הצמצום שסילק אורו הגדול, שעי\"ז נפעל גם בהאור שבו הוא הרצון והתענוג על עולמות, שתבוא (עס זאָל זיך אויסשטעלן) נקודה בלבד מעצם הרצון והתענוג על בריאת העולמות, וללא הריבוי והתוקף כמו שהוא לפני הצמצום, ונקרא בכללות נקודת הרושם<sup data-n=\"49\">48</sup>, שהוא היו\"ד דשם הוי', נקודה בלבד. ומנקודה זו נמשך גילוי הקו, שנרמז באות וא\"ו דשם הוי' שמורה על ההמשכה למטה. אלא שלפנ\"ז צ\"ל הקדמת ה\"א ראשונה, שענינה השערת כלי המקבל כמו שהוא בהמשפיע עצמו עדיין (שלכן נקרא לפעמים בשם שטח דא\"ק<sup data-n=\"49\">48</sup>). ולאחרי כל זה באה הה\"א אחרונה, שמורה על שטח המקבל, שהוא עולם האצילות, אורות בכלים.\n<b>אמנם</b> כל זה הוא מצד סדר השתלשלות, שהרצון והתענוג שבעולמות הוא בבחי' יו\"ד, נקודה בלבד, נקודת הרושם. אבל לאח\"ז נעשה הענין שביו\"ד נברא העוה\"ב, שע\"י עבודת בנ\"י בקיום התומ\"צ (שזוהי תכלית הבריאה כולה, בראשית בשביל ישראל שנקראו ראשית ובשביל התורה שנקראת ראשית), פועלים שמהיו\"ד יהי' נברא העוה\"ב (שכר תורתם ועבודתם), היינו, שעצם הרצון ותענוג שבעולמות, שזהו\"ע נועם הוי', לא יהי' באופן של נקודה בלבד, אלא יומשך ויתגלה בהתרחבות והתפשטות ביותר. וזהו שבשביל עוה\"ב היתה הירידה למטה, כי הגילוי דנועם הוי' הוא נעלה ביותר, למעלה ממדריגת הנשמה כמו שהיתה קודם הירידה, שהרי התענוג הוא גילוי <b>הפנימיות והעצמיות</b> כפי שבא בהתרחבות והתפשטות ביותר (כנ\"ל בנפש האדם, ועד\"ז למעלה).\n<b>וזהו</b> ענין היו\"ד כמו שהוא במשפיע, שגם למעלה ישנו הענין דאזעירת גרמה כביכול, שהו\"ע הצמצום והסילוק, עד שבא בנקודת הרושם, ובה נכללים כל הענינים שרוצים ליתן למטה להמקבל, כפי שבאים בהתרחבות והתפשטות ביותר, שזהו\"ע עוה\"ב, נועם הוי'.ה) <b>וממשיך</b> בעל ההילולא בהמאמר, שהענין דביו\"ד נברא העוה\"ב נמשך ומתגלה ע\"י היו\"ד דספירת היסוד&lt;ד&gt; (שצורתה כצורת אות יו\"ד<sup data-n=\"50\">49</sup>), דעל זה אומר כי כל בשמים ובארץ<sup data-n=\"51\">50</sup>, ותרגם דאחיד בשמיא וארעא, שהיא ספירת יסוד<sup data-n=\"52\">51</sup> שבחינת המלכות מקבל ממנה, ומה דאחיד בשמיא ובארעא, הנה שמים וארץ, שמים אש ומים (כדאיתא במדרש<sup data-n=\"53\">52</sup>), בחינת חו\"ג (בחי' המדות), וארץ הוא בחי' מלכות, והוא שע\"י ספירת היסוד הוא יחוד חו\"ג ומלכות.\n<b>ויובן</b> ע\"פ משנת\"ל (ס\"ב) שבפרק הקודם בהמאמר מבאר ענין היו\"ד ואזעירת גרמה דהמקבל, שעי\"ז נעשה כלי מוכשר לקבל, ובפרק זה מבאר ענין היו\"ד ואזעירת גרמה למעלה בהמשפיע, שהו\"ע הצמצום, שעל ידו נעשים מוכנים כל הענינים שרוצים להשפיע למטה. אמנם, כדי שתהי' ההשפעה בפועל, הנה גם לאחרי שהכלי (דמקבל) כבר מוכשר וההשפעה (מצד המשפיע) כבר מוכנת, צ\"ל החיבור (דאחיד) דמשפיע ומקבל שניהם יחדיו, שענין זה נעשה ע\"י ספירת היסוד, שיש בה ב' ענינים. ענין הא', שספירת המלכות מקבלת ממנה (שמורה על הכשר כלי המקבל והכנת אור המשפיע), וענין הב', דאחיד בשמיא וארעא, החיבור דמשפיע ומקבל.\n<b>ויובן</b> זה ע\"פ ביאור אדמו\"ר הזקן&lt;ה&gt; בפירוש הפסוק<sup data-n=\"54\">53</sup> בן פורת יוסף בן פורת עלי עין, מהו הכפל דבן פורת גו' בן פורת (ב\"פ), וגם מהו\"ע עלי עין. ומבאר בזה<sup data-n=\"55\">54</sup>, שענינו של יוסף, צדיק יסוד עולם<sup data-n=\"56\">55</sup>, הוא ספירת היסוד, שעז\"נ \"יסוד סיומא דגופא\"<sup data-n=\"57\">56</sup>, וגם \"גופא וברית חשוב חד\"<sup data-n=\"58\">57</sup>. דלכאורה, הם ב' ענינים הפכיים, שהרי תחילה נאמר שיסוד אינו אלא <b>סיומא</b> דגופא, ואח\"כ מוסיף שגופא וברית <b>חשוב חד</b>. ומבאר אדמו\"ר הזקן,\n<b>&lt;ד&gt;</b>) כ\"ה בד\"ה באתי לגני תרנ\"ח (סה\"מ תרנ\"ח ע' ריב).\n<b>&lt;ה&gt;</b>) הוספות לתו\"א ר\"פ ויחי (קה, א ואילך).שספירת היסוד מגעת למעלה ביותר עד לתכלית העלי', וכמו שרואים באדם למטה שאין קישוי אלא לדעת<sup data-n=\"59\">58</sup>, שזה מורה על החיבור וההתקשרות דהאבר עם המוח שבראש יותר מכל שאר אברי הגוף, שהרי בשאר האברים גם אם יחשוב בתאוה לא יתפעל ידו או רגלו, ומזה מובן שהיסוד מגיע למעלה מעלה כו'. וכן הוא גם בדרך ההמשכה מלמעלה למטה, כמו בהמשכת הטיפה, שנמשכת מהמובחר שבמוח<sup data-n=\"60\">59</sup> ובאה למטה מטה עד סיומא דגופא. וב' ענינים אלו (ההעלאה וההמשכה שבספירת היסוד) ישנם גם בעבודה דצדיק יסוד עולם. דהנה, בעבודת הצדיקים יש חילוקי מדריגות. יש צדיקים שהדביקות שלהם הוא בתכלית התפשטות הגשמיות במס\"נ האמיתית מכל וכל כו', ויש צדיקים שאין להם מס\"נ אמיתי כמו אלו, ועכ\"ז הם גבוהים מאוד נעלים מאלו כו', וכענין ריב\"ז עם רחב\"ד שזה כעבד לפני המלך וזה כשר לפני המלך<sup data-n=\"61\">60</sup>, דאע\"פ שמס\"נ של זה אמיתי יותר, אבל שורש נשמתו והשגתו אינה מגעת במקום גבוה כ\"כ, שזה מבחי' חסד וזה מבחי' חכמה. אמנם, כאשר גם המס\"נ של (הצדיקים שמדרגתם היא) מדרגת החכמה אמיתי יותר למעלה ממס\"נ של (הצדיקים שמדרגתם היא) מדרגת החסד, אז אין לשער גודל המעלה שבזה, שיהי' ההתעוררות למעלה בב' המעלות, הא', במקום הנעלה ביותר, והב' בתוספת ההארה (בהמשכה למטה). וזוהי מעלת יוסף הצדיק, צדיק יסוד עולם, שהיו בו ב' ענינים הנ\"ל, ששרש נשמתו היתה למעלה ביותר, וגם המס\"נ שלו למטה היתה בתכלית העילוי, ולכך הגיע למעלה ברוממות המדרגות, ומשם נמשך למטה תוספת ההארה ביותר. וזהו בן פורת יוסף בן פורת עלי עין, שכפל הענין בא לרמז ב' מיני התקשרות הנ\"ל (מלמעלה למטה ומלמטה למעלה). כי הנה פורת הוא לשון פרי' ורבי', שהוא ענין ההתקשרות מלמעלה למטה (המשכה), להוליד נשמות ומלאכים. ומפרש הטעם למה יוסף הוא בן פורת, לפי שהוא בן פורת עלי עין, שמרבה עומק ההתקשרות מלמטה למעלה מעלה, שזהו עלי עין, למעלה מע' רבתי כו' (כמבואר שם בארוכה).\n<b>וזהו</b> גם מ\"ש הרב המגיד במק\"א<sup data-n=\"62\">61</sup> ש\"יסוד יש בו כח לעלות עד הדעת ולהשפיע מן המוחין כו' והוא המחבר את הכל, כמ\"ש כי כלבשמים ובארץ כו' דאחיד בשמיא וארעא כו' על ידו הם מתחברים כי הוא צדיק כו' צדיק יסוד עולם. ובזה יביא השפע לעולם העשי' כו' כי לא בא לעולם העשי' אלא ע\"י צדיק שבעולם העשי' כו' והָבֵן\". ויש לקשר זה עם תורת המגיד&lt;30&gt; הנ\"ל (ס\"ב) ממשל האב שמצמצם את שכלו בשביל בנו הקטן, ודוגמתו בנמשל, שהצמצום הוא בשביל ישראל, בשביל שיהיו ישראל צדיקים, שענין זה קשור עם צדיק יסוד עולם הנ\"ל, שעל ידו נעשית המשכת כל הענינים מלמעלה.\n<b>ובזה</b> מסיים ענין הג' שביו\"ד, שמורה על ספירת היסוד, סיומא דגופא, דאחיד בשמיא וארעא, שמאחד את המשפיע והמקבל, היינו, שלאחרי שישנו הביטול שמצד המקבל (ענין הא' שבהיו\"ד), והביטול שמצד המשפיע (ענין הב' שבהיו\"ד), ישנו גם ענין הג' שביו\"ד, שמחבר המשפיע והמקבל, היינו, שכל האותיות, כל ההמשכות מלמעלה, יומשכו ויבואו באופן של קליטה למטה בהמקבל.\nו) <b>וממשיך</b> בהמאמר, שכל הנ\"ל הוא באות ד' שמסטרא דקדושה, משא\"כ בסטרא דלעו\"ז, אות רי\"ש, עז\"נ<sup data-n=\"63\">62</sup> ולרש אין כל, שאין להם בחי' כל, כי כל בשמים ובארץ, דאחיד בשמיא ובארעא, היינו, שאין להם ספירת היסוד המחבר, ומשום זה אין לו כל כפשוטו (ביי אים איז קיין זאַך ניטאָ). והוא היפך מ\"ש ביעקב (שהוא כללות ענין הקדושה) יש לי כל<sup data-n=\"64\">63</sup>. ומוסיף עוד ענין בזה, שאות ד' הוא גם מלשון דיבור, וזהו שאות ד' הוא מסטרא דקדושה, שמורה על הגילוי דדבר הוי', שעי\"ז נעשה התהוות וקיום כל המציאות (בדבר הוי' שמים נעשו גו'<sup data-n=\"65\">64</sup>). משא\"כ מצד הלעו\"ז, ובפרט מצד התגברות הלעו\"ז, ה\"ז פועל גם בקדושה שיהי' הדיבור בתכלית ההעלם וההסתר, וכמ\"ש<sup data-n=\"66\">65</sup> נאלמתי דומי' החשיתי גו'.\n<b>ויובן</b> בהרחב הביאור הקשר והשייכות (דהעלם והסתר הדיבור להענין דלרש אין כל) מההיפך ומקצה הב' שיהי' לעתיד לבוא בתיקון הצמצום. דהנה, לעתיד לבוא כתיב<sup data-n=\"67\">66</sup> ונגלה כבוד הוי' וראו כל בשר יחדיו כי פי הוי' דיבר. וידוע הדיוק בזה<sup data-n=\"68\">67</sup>, הרי התהוות העולם בדיבורו ית', בעשרה מאמרות, היא משם <b>אלקים</b> דוקא (ויאמר אלקים<sup data-n=\"69\">68</sup>), ומהו אומרווראו גו' כי פי <b>הוי'</b> דיבר. אך הענין הוא כמו שמבאר אדמו\"ר האמצעי&lt;ו&gt; ע\"פ<sup data-n=\"70\">69</sup> הללו את הוי' מן השמים הללוהו במרומים גו' הללו את הוי' מן הארץ גו' החי' וכל בהמה וגו', שכל פרטי הנבראים בשמים וארץ עד למטה מטה מהללים לשם הוי', דלכאורה אינו מובן, איך שייך שהנבראים שהתהוותם משם אלקים, יהללו את שם הוי'. בשלמא אמירת קדוש קדוש קדוש הוי'<sup data-n=\"71\">70</sup> (שפירושו מובדל<sup data-n=\"72\">71</sup>), שייכת גם בנבראים שנתהוו ע\"י עשרה מאמרות דשם אלקים, כיון שגם משם אלקים יכולים לבוא להכרה דקדוש הוי', שהוי' הוא קדוש ומובדל. אבל מש\"נ בכל פרטי הנבראים <b>הללו</b> את הוי' (ועד שאפילו באוה\"ע כתיב<sup data-n=\"73\">72</sup> הללו את הוי' כל גוים), אינו מובן, איך שייך ההילול דשם הוי' אצל נבראים שהתהוות מציאותם היא משם אלקים. ומבאר בארוכה, ע\"פ מ\"ש<sup data-n=\"74\">73</sup> וידעת היום והשבות אל לבבך כי הוי' הוא האלקים, ואיתא בזהר<sup data-n=\"75\">74</sup> דהוי' ואלקים כולא חד שהוא עיקרא דכולא, ולכן, גם התהוות הנבראים משם אלקים היא באופן שהוי' ואלקים כולא חד, אלא ששם אלקים הוא ע\"ד מגן ונרתק לשם הוי', כמ\"ש<sup data-n=\"76\">75</sup> כי שמש ומגן הוי' אלקים, אבל, להיותו מגן ונרתק דקדושה, הנה גם על ידו יכול להיות אצל כל הנבראים הענין דהללו את הוי', ועד שהללו את הוי' (גם) כל גוים. אמנם, כל זה הוא בזמן הזה, שרק ע\"י העשרה מאמרות דשם אלקים מגיעים לשם הוי', ובמילא ה\"ז רק שמש הוי' כמו שהיא בתוך המגן והנרתק דשם אלקים, אבל לעתיד לבוא יהי' החידוש דונגלה כבוד הוי' וראו כל בשר יחדיו כי פי הוי' דיבר, שהקב\"ה מוציא חמה מנרתקה<sup data-n=\"77\">76</sup>, ששמש הוי' יצא מהמגן ונרתק דשם אלקים, ואז יראו את הגילוי דשם הוי' כמו שהוא מצד עצמו, כי פי הוי' דיבר. וגילוי זה יהי' בכל הנבראים, כמ\"ש וראו כל בשר, היינו, לא רק נשמות ומלאכים, אלא כל בשר, ועד לחיות ובהמות למטה, יכירו כי פי הוי' דיבר. וע\"ד מ\"ש (בהפרות שנשאו את הארון) וישרנה הפרות<sup data-n=\"78\">77</sup>, שאמרו שירה, ומאי שירה אמרו כו' שירו<sup data-n=\"79\">78</sup>\n<b>&lt;ו&gt;</b>) תורת חיים ח\"ב ע' 964 (תפא, א ואילך (בהוצאה החדשה – תצוה ח\"ב שכח, ד ואילך)).להוי' שיר חדש<sup data-n=\"80\">79</sup>, שזוהי השירה דלעתיד לבוא, כדאיתא במדרש<sup data-n=\"81\">80</sup> שהשיר דלעתיד לבוא, שאז תהי' גאולה שאין אחרי' גלות, הוא לשון זכר, שירו להוי' שיר חדש, והרי הגילוי דלעתיד לבוא יהי' באופן דוראו כל בשר, גם בהמות וחיות, כי פי הוי' דיבר, שדיבורו ית' יהי' בתכלית הגילוי.\n<b>משא\"כ</b> עתה בזמן הגלות הוא ההיפך מזה לגמרי, שדיבורו ית' הוא בתכלית ההעלם וההסתר, וכמ\"ש נאלמתי דומי' החשיתי גו', נאלמתי לשון אלם, שזהו היפך ענין הדיבור. וכפי שמפרש הצמח צדק&lt;ז&gt; שזהו גם שבזמן הגלות כתיב<sup data-n=\"82\">81</sup> כרחל לפני גוזזי' נאלמה, שהוא היפך ענין הדיבור. ומבאר מ\"ש כרחל לפני <b>גוזזי'</b> דוקא נאלמה, דרחל הוא כנסת ישראל<sup data-n=\"83\">82</sup>, ספירת המלכות, ובזמן הגלות שאז ישנם גוזזי', הגוזזים בחי' שערות שלה, ה\"ה נאלמה, שבחי' הדיבור שבעשרה מאמרות הוא בבחי' שתיקה ודומי', והמשכת החיות ע\"י לבושים ושערות המסתירים על בחי' הדיבור&lt;ח&gt;. וכמו שמבאר בעל ההילולא בהמשך הפרק, שהאור והחיות המחי' את הסט\"א הוא הארה דהארה, חיצוני' דחיצוני', ובא בתכלית ההעלם – הנה המשל לזה הוא בדוגמת השערות, שהחיות שבהם אינו בגילוי, שלכן כאשר גוזזים השערות אין מרגישים כאב, לפי שהחיות שבהם הוא בצמצום היותר גדול, ואינו אלא חיצוניות דחיצוניות, להיותו נמשך ע\"י הפסק וצמצום עצם הגולגולת. ולכן נקרא בשם נאלמה, שהוא היפך ענין הדיבור. ומבאר הצ\"צ שזהו גם מ\"ש נאלמתי דומי' החשיתי, כמ\"ש בראשית חכמה<sup data-n=\"84\">83</sup> ש<b>נ</b>אלמתי <b>ד</b>ומי' <b>ה</b>חשיתי ר\"ת נדה [שנדה קאי על כללות זמן הגלות, שאז ירושלים גו' לנדה היתה<sup data-n=\"85\">84</sup>, ומחורבנה של ירושלים נתמלאה צור<sup data-n=\"86\">85</sup>], דנדה אותיות נד ה'<sup data-n=\"87\">86</sup>, פי' שנתרחק הה\"א אחרונה דשם מאות וא\"ו, היינו, שהה\"א אחרונה דשם הוי', ספירת המלכות, בחי' הדיבור, נודד ומתרחק מאות וא\"ו שמורה על ההמשכה מלמעלה, ועי\"ז\n<b>&lt;ז&gt;</b>) ראה רשימות לאיכה ע' 19 (אוה\"ת נ\"ך ח\"ב ע' א'מח). אוה\"ת בראשית נא, א. רשימות לתהלים (יהל אור) עה\"פ לט, ג (ע' קמו ואילך).\n<b>&lt;ח&gt;</b>) לקו\"ת מסעי פח, ג.מתעלם ומסתתר הדיבור, כדאיתא בזהר<sup data-n=\"88\">87</sup> בגין דאתפרשו (ה\"א מן וא\"ו) כו' נאלמתי דומי', בגין דאסתלק וא\"ו מן ה\"א כו' דבור אתאלם&lt;ט&gt;.\n<b>ומזה</b> מובן, שהענין דנאלמתי דומי' החשתי, ר\"ת נדה, נד ה\"א מן וא\"ו, הוא היפך הענין דכל, ספירת היסוד, דאחיד בשמיא ובארעא, שמחבר הוא\"ו (שמים, ז\"א) עם הה\"א (ארץ, מלכות). וזהו גם הענין שלרש אין כל, שמצד זה שאין הבחי' דכל, דאחיד בשמיא ובארעא, היינו, שאין המשכת המדות, אות וא\"ו, במלכות, אות ה\"א, שזהו מה שנד הה\"א מן הוא\"ו, אזי נעשה ענין של רישות (רי\"ש) ועוני.\nז) <b>וממשיך</b> בהמאמר, שזהו שיעקב אמר יש לי כל, ועשו אמר יש לי רב<sup data-n=\"92\">91</sup>. כי הבחי' דכל, דאחיד בשמיא ובארעא, הוא בקדושה דוקא, אבל בעשו שהוא קליפה וסט\"א אין בחי' כל המחבר, כי אם (יש לי) רב. והענין בזה, שרב מורה על ענין הריבוי וההתחלקות, היפך ענין האחדות (דאחיד) שבקדושה, וכדאיתא במדרש<sup data-n=\"93\">92</sup> בעשו כתיב בי' שש נפשות וכתיב בו נפשות הרבה (ע\"ד יש לי רב), דכתיב<sup data-n=\"94\">93</sup> ויקח עשו גו' את נפשות ביתו, וביעקב שבעים נפש וכתיב בי' נפש א' דכתיב<sup data-n=\"95\">94</sup> ויהי כל נפש יוצאי ירך יעקב וגו'. וממשיך לבאר דמ\"ש עשו יש לי רב אין זה סתירה להאמור שלרש אין כל, ע\"פ מאמר רב מתיבתא (בזהר<sup data-n=\"96\">95</sup>) מאן דאיהו זעיר איהו רב ומאן דאיהו רב איהו זעיר. דבקדושה דאיהו זעיר, דאזעירת גרמה, וכמ\"ש<sup data-n=\"97\">96</sup> מי יקום יעקב כי קטן הוא, הנה עי\"ז איהו רב, כי ע\"י הביטול ה\"ה מקבל כל ההשפעות מלמעלה, ועד להגילוי דביו\"ד נברא העוה\"ב שהוא הבחי' דלחזות בנועם הוי' (כנ\"ל ס\"ג). משא\"כ בלעו\"ז, מאן דאיהו רב, שהוא בהתרברבות (היפך הביטול), ההשפעה שמקבל אינה אלא מחיצוניות דחיצוניות, ולכן איהו זעיר, שהו\"ע של מיעוט, כיון שאין\n<b>&lt;ט&gt;</b>) ולכן, לעתיד לבוא יהי' דוקא \"קול גדול\", ו\"קול כלה\"<sup data-n=\"89\">88</sup>. ובמדרש תהלים עה\"פ<sup data-n=\"90\">89</sup> ה' מתיר אסורים איתא שלעת\"ל הקב\"ה מתיר איסורים דנדה<sup data-n=\"91\">90</sup>.לו אלא השפעה גשמית בלבד, והרי גשמיות מצד עצמו, גם כשהוא בריבוי, יש לי רב, אינו מציאות כלל, איהו זעיר.\n<b>ויתירה</b> מזה, שריבוי הגשמיות (יש לי רב) גופא פועל בו זעירות וקטנות. ומובן זה גם בעבודה, כפי שמבאר אדמו\"ר מהר\"ש&lt;י&gt; בארוכה בפירוש הפסוק<sup data-n=\"98\">97</sup> אולת אדם תסלף דרכו ועל ה' יזעף לבו, שרואים אנו בטבע הבריאה שדבר המוכרח להאדם יותר ה\"ה מצוי יותר וללא טירחא. וכמו האויר שמוכרח תמיד להאדם הרי הוא נמצא בכל מקום ואין צריך שום יגיעה כלל להשיגו, ואכילה ושתי' שאינם מוכרחים בתמידות כ\"כ כמו האויר, אינם בנמצא כ\"כ כמו האויר, ובזה גופא השתי' שהיא מוכרחת יותר היא מצוי' יותר ובזול יותר, והאכילה שאינה מוכרחת כ\"כ היא ביוקר יותר, והלבושים שאינם נחוצים כ\"כ (שהרי גם בלעדם יוכל לחיות) הם ביוקר יותר, עד אשר הבנין שהוא עוד יותר מבלי צורך כו' ה\"ז עולה ביוקר יותר ובא בטרחא ויגיעה כו'. ומכ\"ש ענינים שהם מותרות לגמרי. אמנם ישנם כאלה שבשביל עניני מותרות מקריבים ומסכנים את עצמם, שזהו גם היפך שכל האנושי. ועז\"נ אולת אדם תסלף דרכו, שהנהגה זו שמתנהג באולת ושטות לרדוף אחרי מותרות, תסלף דרכו, שלא זו בלבד שאינו משיג המטרה שלו, אלא אדרבה, שעי\"ז מתמעט, כיון שנעשה מבולבל, וחסרה לו מנוחת הנפש, ועי\"ז נחסר אצלו גם בענינים הגשמיים הדרושים לו. וזהו מאן דאיהו רב איהו זעיר, שריבוי הגשמיות גופא פועל שנעשה זעיר.\n<b>וממשיך</b> שם, שזהו שאמרו מרובים צרכי עמך ודעתם קצרה<sup data-n=\"99\">98</sup>, שכל הסיבה מה שמרובים צרכי עמך לרדוף אחרי המותרות, הוא, לפי שדעתם קצרה (שזהו\"ע דאולת אדם) מלהבין שע\"י הרדיפה אחרי המותרות ה\"ה מאבד גם את הענינים המוכרחים. ומוסיף לפרש בפנימיות יותר, שעיקר פירוש ודעתם קצרה הוא בנוגע להעמקת הדעת באופן של התקשרות<sup data-n=\"100\">99</sup> [ע\"ד המבואר לעיל (ס\"ה) בענין יסוד סיומא דגופא, דגופא וברית חשוב חד], שאילו הי' מעמיק דעתו באלקות, לידע שה' אלקיך הוא\n<b>&lt;י&gt;</b>) המשך מים רבים תרל\"ו בתחלתו.הנותן לך כח לעשות חיל<sup data-n=\"101\">100</sup>, לא הי' מחפש תחבולות לנדוד בקצוי תבל, בה בשעה שמאמין ויודע (ידיעה אמיתית באופן של התקשרות, שחודרת בכל כחות נפשו) מ\"ש<sup data-n=\"102\">101</sup> וברכך ה' אלקיך בכל אשר תעשה, שיכול לברכו בכל אשר יעשה במקומו הוא, מבלי לילך למקום סכנה, ומבלי תחבולות וערמומיות כו'. וזהו שהטעם לכך שמרובים צרכי עמך הוא מפני שדעתם קצרה, היינו, העדר הדעת וההתקשרות להענין דוברכך ה' אלקיך בכל אשר תעשה, שמזה בא המצב דאולת אדם תסלף דרכו לחפש תחבולות וכו', ובמילא באה גם ההשפעה באופן של עקמומיות (דאָס גייט מיט אַ קרומקייט), שתמורת רב (ריבוי גשמיות) נעשה זעיר, כנ\"ל&lt;יא&gt;.\nח) <b>וממשיך</b> בעל ההילולא בהמאמר, שההשפעה לקליפה וסט\"א היא באופן שזה גופא עושה אותם בבחי' ישות יותר, וכמו פרעה שאמר לי יאורי ואני עשיתיני<sup data-n=\"103\">102</sup>, שזהו היפך האמת ממש, דהאמת הוא שנתברך בברכתו של יעקב, כמ\"ש<sup data-n=\"104\">103</sup> ויברך יעקב את פרעה, ברכו שיעלה נילוס לרגליו, אמנם, פרעה הוא אותיות הערף<sup data-n=\"105\">104</sup> הנה עוד כיחש והי' כפוי טובה לומר לי יאורי ואני עשיתיני, והיינו, שע\"י ההשפעה ה\"ה נעשה בבחינת יש יותר.\n<b>והענין</b> בזה, שלמרות שישנו ריבוי ההשפעה (יש לי רב), הרי השפעה זו אינה אלא חיצוניות דחיצוניות, ולכן שייך בזה הענין דגוזזי' (שערות בלבד) שעי\"ז נאלמה. וכך הי' אצל פרעה, אותיות הערף, שהי' כפוי טובה וכיחש לגמרי לומר לי יאורי ואני עשיתיני. וכתוצאה מזה נעשה הענין דלרש אין כל, שאין לו השפעה רוחנית כלל, ואפילו השפעת הגשמיות, כיון שאינה אלא מחיצוניות דחיצונית, אין לה קיום לאורך זמן, להיותה היפך האמת<sup data-n=\"106\">105</sup>.\n<b>&lt;יא&gt;</b>) להעיר מהענין ד\"חצי תאוותו בידו\" שנתבאר בסה\"מ קיץ ש\"ת ע' 153.<b>ולהבין</b> זה, דהן אמת שהקליפות מקבלים רק השפעה חיצוניות דחיצוניות, אבל הרי גם השפעה זו היא מהקדושה, ואיך אפשר שעי\"ז יהי' בבחינת יש יותר, לומר לי יאורי ואני עשיתיני. ויובן ע\"פ ביאור אדמו\"ר (מהורש\"ב) נ\"ע&lt;יב&gt; שהטעם לכך שהסט\"א מגביהה עצמה לומר לי יאורי ואני עשיתיני, הוא, לפי שאור הקדושה אינו מאיר בהם בגילוי, אלא נמצא בתוכם בבחינת גלות. דהנה, כאשר ההשפעה וההמשכה מלמעלה באה בסטרא דקדושה, כפי שנמשך לבנ\"י, הרי כיון שהם בעצם כלים לאלקות, כלי מוכשר ומוכן לקבל ההמשכות מלמעלה – ע\"י הביטול, כמבואר בתניא<sup data-n=\"107\">106</sup> שאין קדושה עליונה שורה אלא על מה שבטל אצלו ית', לכן, מתגלה בהם האור האלקי ומתאחד עמהם. משא\"כ בסטרא דלעו\"ז, כיון שבעצם אינם כלים לאלקות כלל – להיותם בפירוד, וכמ\"ש<sup data-n=\"108\">107</sup> אשר חלק ה' אלקיך אותם לכל העמים, שהפרידן מאחדותו<sup data-n=\"109\">108</sup>, היפך הביטול, לכן אין אור הקדושה מתלבש בהם ומתאחד עמהם, אלא נמצא בתוכם בבחינת גלות. וע\"ד החילוק בין התלבשות נשמת האדם בגופו לענין הגלגולים, שהתלבשות הנשמה בגוף היא בדוגמת התלבשות אור בכלי (שהאור פועל בהכלי והכלי בהאור), לפי שהגוף הוא כלי מוכשר ומוכן לקבל הנפש, היינו, שחומר הגוף הוא לפי ערך צורת הנפש, ולכן פועל הגוף על הנשמה והנשמה פועלת על הגוף, ועד שמתאחדים לגמרי, משא\"כ בענין הגלגולים, שנפש האדם מתגלגל בגוף הבהמה, אין זה פועל שינוי ועד שלא ניכר כלל בבהמה, כיון שאינה מוכנה ומוכשרת לקבל את הנשמה המגולגלת בתוכה. וכמשל אדם הקשור בשק, שאינו פועל מאומה בהשק. ודוגמתו בהשפעה לקליפה וסט\"א, שגם ההשפעה המצומצמת, חיצוניות דחיצוניות, שבאה בפנימיות, אינה באופן של התלבשות אור בכלי (כיון שבעצם אין הקליפה וסט\"א כלי מוכשר), אלא נמצאת שם באופן של גלות. ולכן, לא זו בלבד שהשפעת הקדושה אינה פועלת ענין של ביטול, אלא אדרבה, שעי\"ז ניתוסף כח בקליפה לפי שעה, שנעשה בבחינת יש יותר, לומר לי יאורי ואני עשיתיני.\nט) <b>וכללות</b> הענין בזה, דסטרא דלעו\"ז חסר אצלם הענין התיכוני שהוא הביטול דאזעירת גרמה. כי, בהעדר הביטול דאזעירת גרמה\n<b>&lt;יב&gt;</b>) קונטרס ומעין מאמר ג (ע' 68).שמצד המקבל, חסר גם אצל המשפיע הצמצום שבשביל ההמשכה, וכתוצאה מזה נעשה המצב שלרש אין כל. ולזה צ\"ל כללות העבודה של בנ\"י [צדיק יסוד עולם, שהוא הבן שבשבילו הוא הצמצום מלמעלה באופן שעל ידו יומשכו כל הענינים למטה (כידוע<sup data-n=\"110\">109</sup> בפירוש גולל אור מפני חושך וחושך מפני אור<sup data-n=\"111\">110</sup>), וכנ\"ל (ס\"ה) בענין בן פורת יוסף בן פורת עלי עין] שנרמזת במשכן ומקדש, החל מקרשי המשכן – שגם בהרי\"ש יתוסף יו\"ד מאחוריו, היינו הביטול דאזעירת גרמה, שעי\"ז נעשה כלי מוכשר לקבל מהיו\"ד, ביו\"ד נברא העוה\"ב, הגילוי דנועם הוי', ע\"י בחי' יסוד דאחיד בשמיא וארעא. וכל זה נעשה ע\"י עבודתם של ישראל בקיום התומ\"צ במשך שית אלפי שנין דהוה עלמא, ובפרט בעקבתא דמשיחא, שאז העבודה היא באופן דמן המיצר ביותר, הנה ע\"י מן המיצר קראתי י-ה<sup data-n=\"112\">111</sup> נעשית גם ההמשכה באופן נעלה יותר, שעי\"ז פועלים הגילוי דלעתיד לבוא, ונגלה כבוד הוי' וגו', ונגלה דייקא, היינו, שהענין עצמו ישנו כבר (דער ענין איז שוין דאָ), אלא שהוא בהעלם, והחידוש דלעתיד לבוא אינו אלא בכך שהענין יהי' בגילוי, ועד שראו כל בשר, אפילו בהמות וחיות (כנ\"ל). וזה יהי' בעגלא דידן במהרה ממש, כאמור, ונגלה כבוד הוי' וראו כל בשר יחדיו כי פי הוי' דיבר.\n**********",[["1","*","בהמאמר ניתוספו כמה הערות ומראה- מקומות (הערות א-יב) – ע\"פ רשימת כ\"ק אדמו\"ר שליט\"א בכתי\"ק ברשימה דלעיל ע' 4."],["2","1","מאמר זה מיוסד <b>בעיקרו</b> על הפרק השביעי מהמשך באתי לגני ה'שי\"ת."],["3","2","שה\"ש ה, א."],["4","3","שהש\"ר עה\"פ."],["5","4","ויק\"ר פכ\"ט, יא."],["6","5","תרומה כה, ח."],["7","6","ראה ראשית חכמה שער האהבה פ\"ו קרוב לתחלתו (ד\"ה ושני פסוקים). אלשיך עה\"פ תרומה שם (\"שמעתי לומדים\"). של\"ה סט, א. רא, א. חלק תושב\"כ תרומה שכה, ב. שכו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380389\" data-slug=\"likkutei-torah\" data-id=\"4001380389\">לקו\"ת נשא כ, סע\"ב</a>. ובכ\"מ."],["8","7","ד\"ה באתי לגני ה'שי\"ת פרק א (סה\"מ ה'שי\"ת ע' 111)."],["9","8","ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310032\" data-slug=\"tanya\" data-id=\"3401310032\">תניא פכ\"ז (לד, א</a>) ובלקו\"ת ר\"פ פקודי מציין לזהר ח\"ב קכח, ב (ובלקו\"ת שם מציין גם לזהר שם סז, ב. וראה גם שם קפד, א). וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370403\" data-slug=\"torah-or\" data-id=\"3901370403\">תו\"א ויקהל פט, ד</a>. לקו\"ת חוקת סה, ג."],["10","9","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370439\" data-slug=\"torah-or\" data-id=\"3901370439\">תו\"א מגילת אסתר צח, ב</a>. סה\"מ עטר\"ת ע' שעא. תרפ\"ט ע' 40. תרצ\"ז ע' 192. ובכ\"מ."],["11","10","ד\"ה באתי לגני ה'שי\"ת פרק ב (סה\"מ ה'שי\"ת ע' 112 ואילך)."],["12","11","פרק ג (סה\"מ ה'שי\"ת ע' 114)."],["13","12","תרומה כו, טו."],["14","13","ראה המשך וככה תרל\"ז פרק לט ואילך. קונטרס ומעין מאמר א פרק א."],["15","14","בהעלותך יא, ח."],["16","15","סוטה ג, א."],["17","16","בהמאמר – פרק ו (סה\"מ ה'שי\"ת ע' 119)."],["18","17","חלק א בהקדמה ב, ב."],["19","18","ראה פרדס שער האותיות (שער כז) פרק כג. הובא ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370527\" data-slug=\"torah-or\" data-id=\"3901370527\">תו\"א מגילת אסתר קיח, א</a>. אוה\"ת לך פח, א."],["20","19","ויק\"ר פי\"ט, ב."],["21","20","זח\"א כ, א."],["22","21","ד\"ה באתי לגני (סה\"מ ה'שי\"ת ע' 111 ואילך)."],["23","22","ד\"ה היושבת בגנים (שם ע' 119 ואילך)."],["24","23","בכל הנאמר עד כאן – ראה גם ד\"ה באתי לגני תשי\"א-תשט\"ז."],["25","24","סעיף ז – סה\"מ ה'שי\"ת ס\"ע 120 ואילך."],["26","25","מנחות כט, ב."],["27","26","לשון הכתוב – ישעי' כא, יב. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380354\" data-slug=\"likkutei-torah\" data-id=\"4001380354\">לקו\"ת במדבר יא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381263\" data-slug=\"likkutei-torah\" data-id=\"4001381263\">שה\"ש לג, ג</a>. ובכ\"מ."],["28","27","בראשית א, ג."],["29","28","מגילה יו\"ד, ב."],["30","29","ראה עץ חיים שער א (דרוש עיגולים ויושר) ענף ב."],["31","30","אור תורה ולקוטי אמרים בתחילתם."],["32","31","הובא ברש\"י ורמב\"ן עה\"פ בראשית א, א."],["33","32","פ' ראה יד, א."],["34","33","איוב כח, יב."],["35","34","ראה מכתב ט\"ז שבט שנה זו (אג\"ק חי\"ד ע' שנז) בהערה – שמציין לד\"ה מרגלא בפומי' תש\"ט (סה\"מ תש\"ט ע' 132 ואילך).\nוראה גם סה\"מ תרפ\"ד ס\"ע שג ואילך."],["36","35","לשון חז\"ל – חגיגה ה, ב."],["37","36","מלכים-ב ה, טז."],["38","37","ברכות ו, ב."],["39","38","תהלים כז, ד."],["40","39","ראה הנסמן ברשימות הצ\"צ לתהלים (יהל אור) עה\"פ (ס\"ע ק ואילך). – וראה גם המקומות בזהר שהובאו בסה\"מ תרס\"ח הנ\"ל, ובלקו\"ת שבהערה הבאה."],["41","40","ראה גם לקו\"ת פרשתנו (בשלח) בתחלתו."],["42","41","תהלים צ, יז."],["43","42","סה\"מ תרנ\"ז ע' רכג ואילך. ובכ\"מ."],["44","43","משלי טו, ל. וראה גיטין נו, ב."],["45","44","<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">זח\"ג רנז, ב</a> (ברע\"מ). פרדס שער א (שער עשר ולא תשע) פ\"ט. תניא שעהיוה\"א פ\"ז (פב, א)."],["46","45","עבודת הקודש ח\"א פ\"ח."],["47","46","במדב\"ר רפ\"י."],["48","47","שה\"ש ה, טו."],["49","48","ראה גם סה\"מ תרנ\"ט ע' עז ובהערות שם. וש\"נ."],["50","49","ראה זהר ח\"א נו, א. ח\"ג עד, סע\"ב. ועוד."],["51","50","דברי-הימים-א כט, יא. וראה זהר ח\"א לא, סע\"א. ח\"ב קטז, א. ח\"ג רנז, סע\"א. זהר חדש קג, ב. ועוד."],["52","51","זח\"א שם. ובכ\"מ."],["53","52","ב\"ר פ\"ד, ז."],["54","53","ויחי מט, כב."],["55","54","תו\"א שם, ג ואילך."],["56","55","משלי יו\"ד, כה. ראה זח\"א נט, ב."],["57","56","תקוני זהר בהקדמה – \"פתח אליהו\" (יז, א)."],["58","57","זח\"ג רכג, ב. רלו, א. רעט, א. רפג, א. ועוד."],["59","58","יבמות נג, ב."],["60","59","ראה תניא קונטרס אחרון קנז, א. מאמרי אדמו\"ר הזקן תקס\"ח ח\"א ס\"ע רפג. ביאורי הזהר לאדמו\"ר האמצעי בלק קו, א.\nביאורי הזהר להצ\"צ ח\"ב ע' תריג ואילך. אוה\"ת בהעלותך ע' תכו. ועוד."],["61","60","ברכות לד, ב."],["62","61","אור תורה לג, ד ואילך. וראה גם שם ה, ג."],["63","62","שמואל-ב יב, ג."],["64","63","וישלח לג, יא."],["65","64","תהלים לג, ו."],["66","65","שם לט, ג."],["67","66","ישעי' מ, ה."],["68","67","ראה תו\"ח תצוה תעה, ב ואילך."],["69","68","בראשית א, ג. ועוד. וראה זח\"ג רטז, סע\"ב. ועוד."],["70","69","תהלים קמח, א ואילך."],["71","70","ישעי' ו, ג."],["72","71","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380210\" data-slug=\"likkutei-torah\" data-id=\"4001380210\">לקו\"ת אמור לא, א</a>. ובכ\"מ."],["73","72","תהלים קיז, א."],["74","73","ואתחנן ד, לט."],["75","74","ח\"א יב, סע\"א. ח\"ב כו, ב. קסא, א. ח\"ג קמג, א. רסד, א. ועוד."],["76","75","תהלים פד, יב. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא שעהיוה\"א פ\"ד</a>. ובכ\"מ."],["77","76","נדרים ח, ב."],["78","77","שמואל-א ו, יב."],["79","78","תהלים צח, א."],["80","79","ע\"ז כד, ב. זח\"ב קלז, סע\"ב ואילך."],["81","80","תנחומא בשלח יו\"ד. ועוד."],["82","81","ישעי' נג, ז."],["83","82","זח\"ב כט, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310050\" data-slug=\"tanya\" data-id=\"3401310050\">תניא פרק מה (סד, ב</a>). ובכ\"מ."],["84","83","שער הקדושה פי\"ז (ד\"ה גם צריך ליזהר)."],["85","84","איכה א, ח."],["86","85","רש\"י תולדות כה, כג."],["87","86","רמ\"ז (הובא בנצוצי אורות) לזח\"ב ג, ב."],["88","87","ח\"א קטז, ב. ועוד."],["89","88","ראה תו\"א ס\"פ ויגש (מה, רע\"ב). נתבאר בלקו\"ש חל\"ה ע' 197."],["90","89","תהלים קמו, ז."],["91","90","ראה אוה\"ת בראשית שבהערה ז."],["92","91","וישלח לג, ט."],["93","92","ויק\"ר פ\"ד, ו. הובא בפרש\"י עה\"ת ויגש מו, כו."],["94","93","וישלח לו, ו."],["95","94","שמות א, ה."],["96","95","ח\"א קכב, ב. ח\"ג קסח, א."],["97","96","עמוס ז, ב. ה."],["98","97","משלי יט, ג."],["99","98","פיוט בתפילת נעילה. ועייג\"כ ברכות כט, ב."],["100","99","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא</a> ספ\"ג. פמ\"ב (נט, ב). ועוד."],["101","100","עקב ח, יח."],["102","101","פ' ראה טו, יח."],["103","102","בהמאמר (סה\"מ ה'שי\"ת שם) נדפס \"לי יאור (בלי יו\"ד) ואני עשיתיני\". ולכאורה צ\"ל כמו כאן (וכן הוא בסיום הסעיף), וכלשון הפסוק יחזקאל כט, ג. וראה הלשון\nשנעתק ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310027\" data-slug=\"tanya\" data-id=\"3401310027\">תניא פכ\"ב (כח, רע\"א</a>) ובהערות ותיקונים שם (וראה אג\"ק ח\"ג ע' רצ)."],["104","103","ויגש מז, יו\"ד ובפרש\"י שם."],["105","104","לקו\"ת להאריז\"ל וישב מ, א. שם ר\"פ שמות. ובכ\"מ."],["106","105","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380127\" data-slug=\"likkutei-torah\" data-id=\"4001380127\">לקו\"ת צו יב, סע\"ד</a>. קונטרס ומעין מאמר יד פרק ד (ע' 80)."],["107","106","פ\"ו."],["108","107","ואתחנן ד, יט."],["109","108","ראה מאמרי אדמו\"ר הזקן תקע\"ג קעג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670578\" data-slug=\"torat-chaim\" data-id=\"2300670578\">תורת חיים נח עה, ג</a>."],["110","109","ראה מאמרי אדמו\"ר הזקן ענינים ע' שיז. תו\"ח תצוה תסד, ב. שערי אורה ד\"ה בכ\"ה בכסלו פנ\"ז. סה\"מ תרנ\"ט ע' עח. המשך תער\"ב ח\"א ע' תקנד. סה\"מ תרע\"ח ע' שעח. ד\"ה ויקח ה\"א תרצ\"ה פרק כט. ספר השיחות תרפ\"ח-תרצ\"א ע' 260. וש\"נ."],["111","110","בתפלת ערבית."],["112","111","תהלים קיח, ה. וראה סה\"מ אעת\"ר ע' א."]]],[1400260005,"<h3>בס\"ד. שיחת מוצש\"ק פ' בשלח, יו\"ד שבט ה'תשי\"ז<sup data-n=\"113\">*</sup><b>.</b></h3>\nבלתי מוגה\n<b>א</b>. בנוגע להילולא של צדיק – ענין השייך להתוועדות זו הקשורה עם ההילולא של כ\"ק מו\"ח אדמו\"ר – אמרו חז\"ל<sup data-n=\"114\">1</sup> \"אין עושין נפשות לצדיקים שמעשיהם הטובים הם זכרונם\".\nוהענין בזה – שאצל צדיקים אין צורך בענין של זכרון, כי, המשך הקיום של \"מעשיהם הטובים\" מהוה ראי' על המשך קיומם של הצדיקים, היינו, שכל זמן ש\"מעשיהם הטובים\" חיים, ה\"ז ראי' <b>שהם</b> (הצדיקים) <b>עצמם חיים</b>.\nוע\"ד דברי הגמרא במסכת תענית<sup data-n=\"115\">2</sup> בנוגע ליעקב אבינו \"מה זרעו בחיים <b>אף הוא בחיים</b>\".\n<b>ב</b>. ויש להוסיף, שענין זה הוא בנוגע לכל נשמה:\nאמרו חז\"ל<sup data-n=\"116\">3</sup> \"שופרי' דיעקב אבינו מעין שופרי' דאדם הראשון\", היינו, כשם שאדה\"ר כולל כל הנשמות שבעולם, הנה מעין זה כולל גם יעקב את כל הנשמות<sup data-n=\"117\">4</sup>, וכמו שהוא בפשטות שכל בנ\"י יצאו מיעקב ש\"מטתו שלימה\"<sup data-n=\"118\">5</sup> – שבזה נכלל גם שיעקב פועל שלימות בכל נשמות ישראל (נוסף לכך שכולל את כולם).\nומזה מובן שמדברי הגמרא בנוגע ליעקב למדים \"כלל\" בנוגע לכל הנשמות – ש\"מה זרעו בחיים אף הוא בחיים\":\nכל זמן שבנ\"י קשורים עם ענינים של תורה ומצוות – שזהו \"<b>זרעו</b> בחיים\", כמארז\"ל<sup data-n=\"119\">6</sup> \"תולדותיהם (\"זרעו\") של צדיקים <b>מעשים טובים</b>\", ו\"מאי פירי <b>מצוות</b>\"<sup data-n=\"120\">7</sup> – אזי \"<b>אף הוא</b> בחיים\",\nולא רק למעלה מעשרה טפחים, אלא <b>באותו מקום</b> שבו נמצאים\"זרעו\" (התומ\"צ) – שמקומם בעוה\"ז הגשמי דוקא, כמארז\"ל<sup data-n=\"121\">8</sup> אודות המענה לטענת המלאכים \"תנה הודך על השמים\"<sup data-n=\"122\">9</sup>, שהתורה ניתנה דוקא במקום ש\"למצרים ירדתם\", \"יצר הרע יש ביניכם וכו'\",\nולכן, כאשר במקום זה (בעוה\"ז הגשמי) ישנו הענין ד\"זרעו בחיים\", \"תולדותיהם של צדיקים\", ה\"ז הוכחה ש\"יעקב (שכולל את כאו\"א מישראל) <b>לא מת</b>\"<sup data-n=\"123\">10</sup>, אפילו במצב כזה שמצד המציאות, לכאורה, יש מקום להקשות \"וכי בכדי ספדו ספדנייא וחנטו חנטייא כו'\"<sup data-n=\"124\">11</sup>, ואעפ\"כ, לא מתפעלים מזה, כיון שיודעים ש\"מציאות\" זו (שמעוררת הקושיא הנ\"ל) אינה אלא מה שנראה לעין בשר הגשמי, ואילו <b>האמת</b> כמו שהוא – ש\"אף <b>הוא בחיים</b>\", כיון ש\"זרעו בחיים\".\n<b>ג</b>. ואם הדברים אמורים בנוגע לכל נשמה, עאכו\"כ שכן הוא בנוגע לנשמה <b>כללית</b>:\nבנוגע לציבור ישנו כלל ש\"צבור לא מת\" – כפי שמצינו בגמרא<sup data-n=\"125\">12</sup> נפק\"מ בנגלה דתורה בין חטאת יחיד לחטאת צבור: \"חטאת שמתו בעלי', הני מילי ביחיד, אבל לא בצבור, לפי שאין מיתה בצבור\".\nודוגמתו בנשמות גופא – שיש נשמה של יחיד, ויש נשמה של צבור – נשמה כללית.\nובפרטיות יותר:\nאיתא בספרים<sup data-n=\"126\">13</sup> ש\"צבור\" ר\"ת <b>צ</b>דיקים <b>ב</b>ינונים <b>ור</b>שעים (רשעים בתוספת וא\"ו המחבר), ונמצא, שנשמה של צבור היא נשמה שכוללת כל הסוגים דצדיקים בינונים ורשעים.\nוהענין בזה – שנשמה של צבור היא נשמת \"רועה ישראל\" שכולל את כל בנ\"י, היינו, שאינו בוחר לעצמו צדיקים בלבד, או עכ\"פ גם בינונים, אלא נוגע לו גם התיקון של זה שנקרא בשם \"<b>רשע</b>\" לפי שעה (עד שיעשה תשובה), ולא עוד אלא שבידעו ש\"<b>בודאי</b> סופו לעשות תשובה . . כי לא<sup data-n=\"127\">14</sup> ידח ממנו נדח\"<sup data-n=\"128\">15</sup>, רואה הוא אותו כמו שהוא <b>באמת</b>– לאחרי שיעשה תשובה, שזוהי מציאותו <b>האמיתית</b><sup data-n=\"129\">16</sup>, <b>ומחבר</b> גם אותו עם הבי\"ת (בינונים) והצדי\"ק (צדיקים).\nוענין זה מהוה <b>סימן וראי'</b> על היותו \"רועה ישראל\" – כמ\"ש במדרש<sup data-n=\"130\">17</sup> בנוגע לרועה ישראל <b>הראשון</b> (משה רבינו, ש\"נקרא רעיא מהימנא\"<sup data-n=\"131\">18</sup>) וכן דוד המלך (ש\"דוד מלך ישראל חי וקיים\"<sup data-n=\"132\">19</sup>), ש\"בדק לדוד בצאן ומצאו רועה יפה . . ואף משה לא בחנו הקב\"ה אלא בצאן כו'\", כיון שהנהגתו היתה באופן ש\"הי' מוציא הקטנים לרעות כדי שירעו עשב הרך, ואחר מוציא הזקנים כדי שירעו עשב הבינונית, ואחר מוציא הבחורים שהיו אוכלין עשב הקשה\", ועל זה \"אמר הקב\"ה, מי שהוא יודע לרעות הצאן איש לפי כחו, יבוא וירעה בעמי, הה\"ד<sup data-n=\"133\">20</sup> מאחר עלות הביאו לרעות ביעקב עמו\", היינו, שתכונה זו מהוה <b>הוכחה</b> על היותו ראוי להיות רועה ישראל – \"לרעות\" את כל הסוגים שבבנ\"י, צדיקים בינונים ורשעים שנכללים בר\"ת ד\"צבור\".\nוכיון ש\"צבור לא מת\", נמצא, שבנשמה כללית (נשמתו של רועה ישראל שכולל את כל הסוגים דצדיקים בינונים ורשעים) ענין החיים הוא <b>בשליטה מוחלטת</b>, כך שלא שייך ענין של העדר (מיתה) כלל.\nוכל זה – נוסף על הכ\"ש וק\"ו משאר הנשמות, שגם אצלם ישנו הכלל ד\"מה <b>זרעו</b> בחיים <b>אף הוא</b> בחיים\" (כנ\"ל ס\"ב), ועאכו\"כ בנשמה כללית, ש\"זרעו בחיים\" מהוה <b>הוכחה נוספת</b> ש\"אף הוא בחיים\"<sup data-n=\"134\">21</sup>.\n<b>ד</b>. ענין זה מודגש במיוחד בעמדנו במוצאי שבת קודש:\nאיתא בבית-יוסף<sup data-n=\"135\">22</sup>: \"בסדורים<sup data-n=\"136\">23</sup> מפרש אבר יש באדם . . ואינו נהנה באכילה אלא במוצאי שבת\" – שזהו ה\"עצם לוז\"<sup data-n=\"137\">24</sup> שלא נהנה מעץ הדעת, ועליו אמרו חז\"ל<sup data-n=\"138\">25</sup> שאין מיתה שולטת עליו ונשאר קיים גם לאחרי מיתה (ואי אפשר לשחקו ולאבדו כו'), ולא עוד אלא שממנו יהי'בנין כל הגוף (כמ\"ש<sup data-n=\"139\">26</sup> \"ותקרבו עצמות עצם אל עצמו גו' גידים ובשר עלה ויקרם עליהם עור וגו'\") כשיקומו המתים לתחי' ויחיו חיים נצחיים (\"וחי לעולם\"<sup data-n=\"140\">27</sup>).\n[המשך הביאור בהשייכות <b>למוצאי</b> שבת דוקא – הוגה ע\"י כ\"ק אדמו\"ר שליט\"א, ונדפס בלקו\"ש חל\"ו ע' 75 ואילך<sup data-n=\"141\">28</sup>].\nונמצא, שבאכילה דמוצאי שבת שממנה נהנה העצם לוז – מודגש תיקון חטא עץ הדעת ושלילת ענין המיתה לעתיד לבוא, כפי שיראו <b>בעיני בשר</b> כשיקויים היעוד<sup data-n=\"142\">29</sup> \"הקיצו ורננו שוכני עפר\".\nוזוהי ההוספה היתירה שבמוצאי שבת קודש לגבי כל האמור לעיל:\nהענין ד\"מה זרעו בחיים אף הוא בחיים\" (ועד\"ז הענין ד\"צבור לא מת\") – מובן אמנם בשכל, ויתירה מזה, שיכול לחדור (\"דערנעמען\") גם בהרגש הלב, אבל אעפ\"כ, <b>אין זה נראה</b> למטה מעשרה טפחים;\nואילו החידוש – שנפעל ע\"י הסעודה דמוצאי שבת שממנה נהנה העצם לוז שממנו נבנה הגוף בתחיית המתים – הוא, שרואים זאת <b>בבשר הגשמי</b>!\nויה\"ר שע\"י ההליכה בדרכיו ובאורחותיו של בעל ההילולא – שזהו\"ע ד\"זרעו בחיים\" – נזכה במהרה בימינו לקיום היעוד \"הקיצו ורננו שוכני עפר\", והוא בראשם, ויוציאנו מגלות המר, במהרה בימינו ממש.\n***\n<b>ה</b>. מבואר בתורת החסידות<sup data-n=\"143\">30</sup> שביום הסתלקות-הילולא עולה למעלה \"כל עמל האדם שעמלה נפשו בחייו\", \"כל מעשיו ותורתו ועבודתו אשר עבד כל ימי חייו\" – למקום ודרגא נעלית יותר מאשר במשך כל עבודתו במשך כל ימי חייו.\nוכיון שבעבודת האדם (ועד\"ז בנוגע לנשיא ישראל) במשך כל ימי חייו גופא יש חילוקי דרגות (כדלקמן), הרי, עיקר ההדגשה אודות העלי' שביום ההסתלקות-הילולא היא ביחס לדרגת העבודה <b>היותר נעלית</b> שבמשך ימי חייו גופא, כדלקמן.<b>ו</b>. ובהקדם חילוקי הדרגות שבכללות עבודת האדם – שיש בזה תקופות תקופות:\nעבודת האדם – ישנה גם <b>לפני בר-מצוה</b>, שכן, אע\"פ שע\"פ דין אין הקטן מחוייב במצוות, מ\"מ, מצינו בשו\"ע הלכות שבת<sup data-n=\"144\">31</sup> (והביאו גם אדה\"ז בשולחנו) לענין חינוך דקטן: \"קטן . . (ש)עבר שאר עבירות בקטנותו . . טוב לו שיקבל על עצמו איזה דבר לתשובה ולכפרה\" [ומההוכחות לזה<sup data-n=\"145\">32</sup> – פס\"ד הרמב\"ם<sup data-n=\"146\">33</sup> לענין קטן ש\"אינו מביא (קרבן) עד שיגדיל ויהי' בן דעת\", שאז מביא קרבן על דבר שעשה בקטנותו], אבל אעפ\"כ, מובן ופשוט, שאינה דומה העבודה עד י\"ג שנה, לפני בר-מצוה, להעבודה לאחרי י\"ג שנה.\nוגם לאחרי בר-מצוה ישנם חילוקים:\nלכל לראש – החילוק בין י\"ג שנה לעשרים שנה, ע\"פ נגלה, שאין ב\"ד של מעלה עונשין עד שיהא בן עשרים<sup data-n=\"147\">34</sup>. וכפי שמבאר רבינו הזקן בלקו\"ת פרשת במדבר<sup data-n=\"148\">35</sup> – ע\"פ קבלה<sup data-n=\"149\">36</sup> – \"פי' מארז\"ל פ\"ט דב\"ב<sup data-n=\"150\">37</sup> ולמכור בנכסי אביו עד שיהי' בן עשרים שנה\", שאז נעשית אצלו שלימות המוחין ושלימות הדעת (שלכן, גם האחריות המוטלת עליו היא גדולה יותר), שמזה מובן, שמי\"ג עד כ' שנה היא תקופה אחת בעבודת האדם, ומכ' שנה ולמעלה מתחילה תקופה נעלית יותר בעבודתו.\nוגם לאחרי עשרים שנה ישנם חילוקים בכל תקופה של עשר שנים – כדברי המשנה<sup data-n=\"151\">38</sup> \"בן עשרים כו', בן שלשים כו' בן שבעים כו' בן מאה\".\nוכל זה – נוסף על כללות העלי' מידי זמן בזמן מצד זה ש\"תלמידי חכמים אין להם מנוחה . . שנאמר<sup data-n=\"152\">39</sup> ילכו מחיל אל חיל\"<sup data-n=\"153\">40</sup>.\nונוסף על החילוקים שמצד שינויי <b>הזמנים</b> ע\"פ <b>הלוח</b> (בן י\"ג, בן כ' וכו'), ישנם גם חילוקים מצד השינויים בתקופות האדם <b>בחייו הוא</b> – לפני החתונה ולאחרי החתונה; קודם כניסתו להתעסקות בעניני העולם, ולאחרי שריחיים על צווארו.ובנדו\"ד, בנוגע לרועה ישראל ונשיא ישראל, בעל ההילולא – ניתוסף גם חילוק התקופה שלפני הנשיאות ושלאחרי הנשיאות,\n– שכן, לפני שנעשה נשיא בפועל, הרי, מצד זה ש\"אין מלכות נוגעת בחברתה\"<sup data-n=\"154\">41</sup>, הי' <b>אביו</b> (אדמו\"ר מהורש\"ב נ\"ע) הנשיא, ולאחרי זה עברה הנשיאות לבנו ממלא מקומו, ואז התחילה נשיאותו ומלכותו בפועל –\nהרי מובן ופשוט שכאשר נעשה נשיא בפועל, מתחילה <b>תקופה חדשה</b> אפילו בהעבודה <b>שלו</b>, שגם קודם לזה היתה בעילוי לגבי שאר אנשים.\n<b>ז</b>. והנה, בנוגע לאופן ההכנה וההתחלה של קבלת הנשיאות שלו – סיפר כ\"ק מו\"ח אדמו\"ר<sup data-n=\"155\">42</sup>, שבשנת ההסתלקות אמר לו אביו כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע: \"<b>אויף רוסלאַנד גייען שווערע וואָלקענס</b>\" (עננים שחורים באים על רוסיא), והוסיף לאמר: \"<b>אויף הרבצת התורה ביראת שמים און החזקת היהדות זאָלסטו האָבען מסירת נפש בפועל, ניט נאָר בכח</b>\" (עבור הרבצת התורה ביראת שמים והחזקת היהדות – שתהי' לך מסירת נפש בפועל, לא רק בכח).\nאלו הם דברי החינוך של נשיא בישראל, קודם הסתלקותו, שבהם העביר את הנשיאות לבנו ממלא מקומו: <b>עבודה באופן של מסירת נפש בפועל</b>. וכדי לכפול הענין ולהוסיף תוקף בהחלטה [ע\"ד שמצינו בגמרא<sup data-n=\"156\">43</sup> \"והוא דאמר הן הן תרי זימני\", \"אמן אמן\"] – הוסיף והדגיש: \"<b>מסירת נפש בפועל, לא רק בכח</b>\"!\nבאופן כזה (מסירת נפש בפועל, לא רק בכח) היתה <b>קבלת</b> הנשיאות: עוד לפני שהי' <b>צורך</b> בענין של מסירת נפש, אפילו בכח – הרי <b>קבלת הנשיאות כשלעצמה</b> היתה כבר ענין של <b>מס\"נ בפועל</b>, כי, <b>מלכתחילה ידוע ידע</b> ע\"ד הצורך במס\"נ בפועל, ועל מנת כן קיבל את הנשיאות, עם כל האחריות הכרוכה בכך עד למס\"נ בפועל;\nבאופן כזה (מסירת נפש בפועל, לא רק בכח) היתה עבודתו <b>בהתחלת</b> הנשיאות בפועל – באותה תקופה שאכן באו העננים השחורים [כפי שיודעים אלה שהיו אז באותה מדינה, שהם בעצמם \"חיו\" זאת (\"זיי האָבן דאָס אַליין איבערגעלעבט\"), ואלה שהיו בריחוק מקום, יודעים זאת עכ\"פמפי השמועה] – שאז התחיל תוקף הרדיפות על הדת, וביחוד על דת ישראל, מ\"מהרסייך ומחריבייך\"<sup data-n=\"157\">44</sup>;\nובאופן כזה (מסירת נפש בפועל, לא רק בכח) היתה עבודתו <b>במשך כל שנות נשיאותו</b> עד יום הסתלקותו<sup data-n=\"158\">45</sup> – שה\"חוט השני\" בעבודתו הי' ענין המסירת נפש, וכאמור, לא רק מסירת נפש בכח, אלא גם מסירת נפש בפועל – שלא להתחשב עם עניני הגוף, כי אם להביא לידי פועל (\"דורכצופירן\") את כל הענינים שצריכים לבוא לפועל מצד המצב הכללי ומצד הענינים שמתרחשים בעולם.\n<b>ח</b>. ומזה מובן, שאופן עבודתו של בעל ההילולא במשך תקופת נשיאותו – עבודה באופן של מסירת נפש – מודגש ביותר ביום ההסתלקות-הילולא, שכל עבודתו אשר עמל בה כל ימי חייו עולה ומגיע להמקור היותר נעלה, ועד למעלה ממקור כו'.\nוכמו בכל עניני קדושה – \"חוזר וניעור\" ענין זה ביום ההילולא בכל שנה ושנה, שבו נעשית העלי' מעולם עליון לעולם עליון יותר.\nאלא, שיש צורך גם בעבודתם של <b>בני ישראל</b>, שלהם ניתן הכח <b>לפעול</b> שיהיו \"הימים האלה <b>נזכרים</b>\" – זכרון שיביא לידי התעוררות טובה, ועי\"ז – \"<b>ונעשים</b>\", שיחזרו וייעשו כל הענינים, כל ההמשכות וההשפעות, כמו שהיו בפעם הראשונה (כמובא מכתבי האריז\"ל<sup data-n=\"159\">46</sup> עה\"פ<sup data-n=\"160\">47</sup> \"והימים האלה נזכרים ונעשים\"), כולל גם ההמשכה <b>בעשי'</b> (\"ונעשים\") דוקא, היינו, בעולם העשי' ובכח המעשה, בחינת \"סוכת דוד הנופלת\" (\"שנפלה . . עד . . בחי' עשי'\"<sup data-n=\"161\">48</sup>).\nובנדו\"ד – שע\"י הזכירה (\"נזכרים\"), בד בבד עם התעוררות טובה על מנת להביאה בפועל [זכירה והתעוררות שהולכים ומתחזקים בתוספת כח ואומץ ביום ההילולא מידי שנה בשנה], פועלים את ה\"נעשים\", שיומשך בפועל הכח שניתן ע\"י הנשיא לכל השייכים אליו, וגם להזמן שלאחריו – ששום דבר, אפילו דבר הדורש מס\"נ בפועל, לא יבלבל אותם ממילוי השליחות שהוטלה עליהם ע\"י ההשגחה העליונה!\nזאת ועוד:ע\"י זכירה והתעוררות זו (ששום דבר לא יבלבל כו'), שתוכנה, עמידה בתנועה של <b>מס\"נ בכח</b> – מתבטל בדרך ממילא ההעלם וההסתר, כך <b>שאין צורך</b> במסירת נפש (כפי שגם אצל כ\"ק מו\"ח אדמו\"ר היו כו\"כ ענינים באופן כזה).\nויקויים הפסק-דין דב\"ד של מעלה – כדברי אדמו\"ר האמצעי בשם אדמו\"ר הזקן<sup data-n=\"162\">49</sup> – שבזכות מסירת נפשו של אדמו\"ר הזקן, הנה, בכל עניני תומ\"צ תהי' יד מקושריו על העליונה.\nויעזור השי\"ת שיהי' זה ללא העלמות והסתרים, ומתוך התרחבות והתפשטות, ועד שיגיעו (\"מ'וועט דערלאַנגען\") – ע\"י הפצת המעיינות חוצה – במרחב העצמי, שזהו\"ע \"ענני במרחב י-ה\"<sup data-n=\"163\">50</sup>, בגאולה האמיתית והשלימה, במהרה בימינו.\n***\n<b>ט</b>. כ\"ק אדמו\"ר שליט\"א צוה לנגן ואמר מאמר ד\"ה באתי לגני.\n***\n<b>י</b>. בהמשך להמדובר לעיל אודות הענין ד\"מה זרעו בחיים אף הוא בחיים\" – כיון שנמצאים כאן תלמידי הישיבות של הרבי, ינגנו יחד ניגון שמח, ובאופן שיראו ש\"<b>זרעו בחיים</b>\", ויהי' זה ראי' נוספת ש\"אף <b>הוא בחיים</b>\", למטה מעשרה טפחים.\n– מסתמא ינגנו ניגון <b>שמח</b>, כדי שיהי' ניכר יתר חיות (\"ס'זאָל זיך אָנזען מערער חיים\").\n[כ\"ק אדמו\"ר שליט\"א התחיל בעצמו לנגן ניגון שמח, ועודד מאד את השירה.\nאח\"כ אמר]: כיון שניתוספו שני ענינים חדשים ב\"זרעו בחיים\" – תלמידי הישיבות בנואַרק וטורונטו<sup data-n=\"164\">51</sup>, שנמצאים כאן – יאמרו גם הם \"לחיים\" במיוחד, וגם עם \"ניגון\".\n[כ\"ק אדמו\"ר שליט\"א הורה לכו\"כ מעסקני הישיבה שיאמרו \"לחיים\"].\n***<b>יא</b>. בנוגע להקביעות דיום הילולא ביום השבת<sup data-n=\"165\">52</sup> – הנה, בנוגע לעובדין דחול השייכים ליאָרצייט שאי אפשר לעשותם בשבת, ישנם ג' אפשרויות: לא לעשותם (בשנה זו) כלל, להקדימם לערב שבת, או לדחותם ליום ראשון.\nובפרטיות יותר<sup data-n=\"166\">53</sup>:\nבנוגע להמנהג להתענות ביום מיתת אביו<sup data-n=\"167\">54</sup> – איתא בשו\"ע<sup data-n=\"168\">55</sup> ש\"אם אירע יום מיתת אביו בשבת . . ידחה למחר\"<sup data-n=\"169\">56</sup>.\nוהקשו אחרונים<sup data-n=\"170\">57</sup>: כיון שהתענית צ\"ל ביום זה (\"יום מיתת אביו\") דוקא – משום כבוד אביו להקל עליו בדין של מעלה, או משום שלא לרעי' מזלי' דנפשי'<sup data-n=\"171\">58</sup> – מהי התועלת בכך ש\"ידחה למחר\", <b>לאחר המעשה</b><sup data-n=\"172\">59</sup>?!\nואכן, מטעם זה יש דעות שאין מתענין כלל – כמ\"ש הרמ\"א<sup data-n=\"168\">55</sup> ש\"אין נוהגין כן (לדחות למחר), אלא אין מתענין כלל\"<sup data-n=\"173\">60</sup>.\nונוסף לזה, מצינו באחרונים דעה שלישית<sup data-n=\"174\">61</sup> – שמקדימים התענית לערב שבת (אף שבדרך כלל בכגון-דא \"אקדומי כו' לא מקדמי\"<sup data-n=\"175\">62</sup>).\nובנוגע לסדר הלימוד, תפלות ובקשות השייכים ליאָרצייט שאין לאמרם בשבת<sup data-n=\"176\">63</sup> – מובא<sup data-n=\"177\">64</sup> מנהג ירושלים <b>להקדימם</b> לערב שבת (ולא לדחותם לאחרי השבת, שאז הוא לאחר המעשה, כנ\"ל).\nובנוגע לפועל:\nבנוגע לתענית – הרי אין מנהגנו להתענות ביאָרצייט, ובפרטבהילולא של צדיקים, גם כשחל בחול, ועאכו\"כ כשחל בשבת, שלדעת הרמ\"א \"אין מתענין כלל\".\nויש לומר ההסברה בזה – שמעלת יום השבת מהני במקום תענית, ע\"ד שמצינו במדרש תנחומא<sup data-n=\"178\">65</sup> ש\"כבוד שבת עדיף מאלף תעניות\".\nאמנם, בנוגע לנתינת צדקה בממון, כתיבת וקריאת פדיונות – הנה ע\"פ הנ\"ל הוחלט שלא לדחות זאת ליום ראשון, לאחר המעשה, אלא להקדים ולעשות זאת בערב שבת<sup data-n=\"179\">66</sup>.\n<b>יב</b>. ולהעיר, שבנדו\"ד יש סברא לדחות ענינים אלה ליום ראשון, להיותו <b>יום הקבורה</b><sup data-n=\"180\">67</sup>:\nיש דעה<sup data-n=\"181\">68</sup> שכאשר המיתה והקבורה אינם ביום אחד, קובעים היאָרצייט ביום הקבורה. ואף שאין אנו פוסקים כן (אלא קובעים היאָרצייט ביום המיתה)<sup data-n=\"182\">69</sup>, מ\"מ, יש דעה באחרונים<sup data-n=\"183\">70</sup> שבמקום שאי אפשר לקיים היאָרצייט ביום המיתה, יש לסמוך – בתור \"סניף\" – על הדעה שהיאָרצייט הוא ביום הקבורה. ועפ\"ז, יש סברא לדחות עניני היאָרצייט שאי אפשר לעשותם בשבת, ליום ראשון, שהוא יום הקבורה.\nאבל, ההוראה ששמעתי מכ\"ק מו\"ח אדמו\"ר, היא: \"יא\"צ – ביום המיתה אפילו בשנה ראשונה, ואפילו כשיום הקבורה רחוק מיום המיתה\"<sup data-n=\"184\">71</sup>.\nומזה גם משמע שהדעה שהיאָרצייט יהי' ביום הקבורה – <b>מושללת לגמרי</b>, כך, שאין לסמוך על דעה זו אפילו לא בתור \"סניף\".\nולכן, היתה ההנהגה כדעת האחרונים שיש להקדים הענינים השייכים ליאָרצייט, ולעשותם ביום הששי.\n<b>יג</b>. והנה, ביום הששי גופא – יש חילוק בין קודם חצות ולאחר חצות, כידוע<sup data-n=\"185\">72</sup> שביום הששי לאחרי חצות מתחילה כבר הארת יום השבת.ומשום זה היתה לכתחילה סברא לדייק שכתיבת ועאכו\"כ קריאת הפדיונות, וכן נתינת הצדקה, יהיו לאחר חצות דוקא, בזמן ששייך וקשור כבר עם קדושת שבת.\nולהעיר גם ממ\"ש בכתבי האריז\"ל<sup data-n=\"186\">73</sup> ש\"הנקבר בערב שבת <b>אחר חמש שעות ביום</b> . . אינו רואה חיבוט הקבר . . כי . . כבר קדושת שבת מאירה אז\".\nוכן גם בכללות, בענינים של שמחה – לענין עליית העולמות בשבת – שעלי' זו מתחילה מערב שבת אחר חצות, שאז ישנה כבר הארת יום השבת, כנ\"ל.\nאמנם, לאחר העיון – המסקנא היא שעניני היאָרצייט שחל בשבת שנעשים בערב שבת אינם שייכים <b>לקדושת</b> שבת, ובמילא, אין בהם חילוק בין קודם חצות ולאחר חצות.\n<b>יד</b>. ויובן ויתבאר ע\"פ דוגמא מדין בנגלה:\nבנוגע לקידוש בליל שבת ויו\"ט – אין צורך להמתין עד צאת הכוכבים, אלא יכולים לקדש גם מבעוד יום, בזמן שמוסיפים מחול על הקודש<sup data-n=\"187\">74</sup>. וכפי שמצינו<sup data-n=\"188\">75</sup> ש\"בימי הקדמונים . . היו מקדימין . . בע\"ש <b>בעוד היום גדול כ\"כ</b> שהי' רב העיר שהי' מהגדולים הקדמונים וכל טובי הקהל עמו הלכו לטייל אחר אכילה של סעודת שבת . . והיו חוזרים לבתיהם קודם הלילה\".\nאמנם, בנוגע לקידוש בליל פסח – \"אינו יכול לעשות כן (לקדש ולאכול מבעוד יום) . . אלא בלילה . . כוס של קידוש הוא אחד מן הד' כוסות לפיכך צריך בלילה ממש, ולא במה שהוסיף מחול על הקודש\"<sup data-n=\"189\">76</sup>. ועד\"ז בנוגע לאכילת כזית פת בליל סוכות – ש\"לא יאכל בסוכה עד לאחר צאת הכוכבים\"<sup data-n=\"190\">77</sup>.\nוטעם החילוק<sup data-n=\"191\">78</sup> – לפי שפעולת ההוספה מחול על הקודש היא המשכת קדושת הלילה ביום, היינו, שהיום נשאר <b>יום</b> (ולא שהיום נעשה לילה), אלא שנמשכת בו <b>קדושת</b> הלילה. ובהתאם לכך, הענינים השייכים <b>לקדושה</b> – יכולים לעשותם גם בזמן ההוספה, ואילו הענינים שצריכיםלהיות <b>בלילה</b> – אי אפשר לעשותם בזמן ההוספה, אלא צריכים להמתין עד צאת הכוכבים.\nולכן:\nקידוש שבת (ויו\"ט), שקשור עם <b>הקדושה</b> דיום השבת, כמ\"ש<sup data-n=\"192\">79</sup> \"זכור את יום השבת לקדשו\", ואינו קשור עם זמן הלילה דוקא – שהרי הקידוש הוא גם ביום<sup data-n=\"193\">80</sup>, ובפרט שאם שכח או נאנס ולא קידש בלילה, אומר נוסח הקידוש הארוך ביום<sup data-n=\"194\">81</sup> – יכול להיות גם מבעוד יום, בזמן שמוסיפים מחול על הקודש, כיון שיש בו <b>קדושת</b> שבת (ויו\"ט).\nמשא\"כ בנוגע אכילת כזית פת בסוכה, ש\"נלמד בג\"ש מאכילת מצה\"&lt;77&gt;, ואכילת מצה \"הוקשה לאכילת פסח\" שבו נאמר<sup data-n=\"195\">82</sup> \"ואכלו את הבשר בלילה הזה\", \"בלילה ממש\", וכן \"גם כל הד' כוסות (כולל גם \"כוס של קידוש\") שתקנו חכמים אינו אלא בלילה בזמן הראוי לאכילת מצה\"&lt;76&gt; – לא מהני ההוספה מחול על הקודש, שכבר מבעוד יום מתחילה <b>קדושת</b> חג הסוכות או חג הפסח, להחיובים שצריכים להיות <b>בלילה</b> דוקא.\n<b>טו</b>. ומזה מובן גם בנדו\"ד:\nגם כאשר יום ההילולא חל בשבת, הרי עניני יום ההילולא שביום זה אינם שייכים <b>לקדושת</b> השבת, כי אם <b>לכ\"ד שעות המעת-לעת</b> (שבשנה זו הוא יום השבת).\nובמילא, גם עניני היאָרצייט, כמו נתינת צדקה והפדיונות, שנעשים ביום ששי, אינם שייכים לקדושת השבת שמתחילה ביום ששי אחר חצות.\nוכיון שכן, הרי, בנוגע לעניני היאָרצייט אין מקום לחלק בין ערב שבת קודם חצות לאחר חצות, כי, החילוק דערב שבת קודם חצות ולאחר חצות אינו אלא בנוגע <b>לקדושת</b> השבת, אבל בנוגע לענינים שאינם שייכים לקדושת שבת שבערב שבת, וזה שנעשים בערב שבת אינו אלא להיותו ערב <b>כ\"ד שעות המעל\"ע</b> דיום ההילולא, הרי, ערב שבת <b>כולו</b> הוא ערב יום ההילולא, ולא שייך בזה המעלה דלאחר חצות שמצד <b>קדושת</b> השבת.\n<b>טז</b>. מעין דוגמא לזה מצינו גם בנוגע לירידת המן בערב שבת – כמ\"ש בפרשת השבוע<sup data-n=\"196\">83</sup> \"והי' ביום הששי והכינו את אשר יביאו והי'משנה גו'\", הן עבור יום ששי והן עבור יום השבת שבו לא ירד המן – שיש בזה ב' ענינים: \"ברכו במן . . בערב שבת שני עומרים, וקדשו במן, שלא ירד בו כל עיקר\"<sup data-n=\"197\">84</sup>.\n[המשך הביאור, ש\"<b>קדשו</b> במן\" שייך <b>לקדושת</b> שבת, ואילו \"<b>ברכו</b> במן\" אינה מוגבלת להזמן דקדושת שבת, אלא <b>להמעת-לעת</b> דשבת, ולכן נמשכת גם לסעודה <b>דמוצאי</b> שבת – הוגה ע\"י כ\"ק אדמו\"ר שליט\"א ונדפס בלקו\"ש חל\"ו ע' 72 ואילך&lt;28&gt;].\n<b>יז</b>. ויש להוסיף ולבאר הלימוד וההוראה בעבודת בנ\"י מהסדר דירידת המן:\nנתבאר לעיל שברכת המן דיום השבת נמשכה גם <b>במוצאי</b> שבת – כמו בכל יום שירידת המן היתה בבוקר, \"בבוקר תשבעו לחם\"<sup data-n=\"198\">85</sup>, וממנו אכלו גם סעודת הלילה.\nויתירה מזה – שברכת המן ביום השבת נמשכה בכל ימי השבוע, שהרי, זה שבשבת \"לא ירד בו כל עיקר\" אינו אלא בנוגע לירידת המן <b>למטה</b>, אבל המשכת הברכה <b>מלמעלה</b> – עיקרה ביום השבת, ובכח זה היתה ירידת המן למטה בכל ימי השבוע, כדאיתא בזהר<sup data-n=\"199\">86</sup> \"ויברך אלקים את יום השביעי . . מה ברכתא אשתכח בי' . . כל ברכאן . . ביומא שביעאה תליין . . מתברכאן מיני' כל שיתא יומין\".\nוההוראה מזה בעבודת בנ\"י בזמן הזה:\nכ\"ק מו\"ח אדמו\"ר אמר בשם אדמו\"ר מהר\"ש<sup data-n=\"200\">87</sup>, שפרנסת בנ\"י בזמן הזה היא בדוגמת \"מן\", כי, כשמתבוננים בדרך הטבע לא רואים כיצד תספיק הפרנסה לכל המצטרך, ועכצ\"ל שזהו \"לחם מן השמים\"<sup data-n=\"201\">88</sup>, אלא ש\"אין בעל הנס מכיר בנסו\"<sup data-n=\"202\">89</sup>.\nזוהי איפוא ההוראה – שכאשר יהודי רוצה שתהי' לו פרנסה בגשמיות בימות החול, ובזמן הגלות שנמשל ללילה<sup data-n=\"203\">90</sup>, צריך \"לקחת\" מיום השבת, וממצב של גאולה שנמשל ליום<sup data-n=\"204\">91</sup>:\nמתי נמצא יהודי במצב של גאולה מהגלות – כשלומד תורהומקיים מצוות, כמארז\"ל<sup data-n=\"205\">92</sup> \"אין לך בן חורין אלא מי שעוסק בתלמוד תורה\", שכן, בנוגע לענינים רוחניים הקשורים עם הנשמה, אין שליטה לגוים, וכדברי כ\"ק מו\"ח אדמו\"ר<sup data-n=\"206\">93</sup> בעל ההילולא שרק הגוף נמסר לשעבוד גלויות, אבל הנשמה היא בת-חורין.\nובכן, כשיהודי נמצא במצב של גאולה, שנמשל ליום (בוקר) – אזי \"בבוקר תשבעו לחם\", ומזה נמשכת ברכת הפרנסה גם בלילה, בזמן הגלות.\nועד\"ז בנוגע לפרנסה דימות החול – שכאשר ממשיכים מיום השבת בכל ימי החול, \"היום יום ראשון בשבת\", \"שני בשבת\" וכו'<sup data-n=\"207\">94</sup>, שבכל יום תומשך קדושת השבת, שענינו \"שבת להוי'\"<sup data-n=\"208\">95</sup>, שבו לא עוסקים בעובדין דחול, כי אם בעניני אלקות, תורה ומצוותי' – אזי נמשכת ברכת הפרנסה בימות החול.\nזאת ועוד:\nכשם שהמן לא הי' בו פסולת<sup data-n=\"209\">96</sup>, כך יהי' גם בנוגע לפרנסה – שלא זו בלבד שלא יהי' בה פסולת כפשוטו, ענינים שאין בהם תועלת והנאה כלל, אלא עוד זאת, שגם התועלת וההנאה מהפרנסה עצמה תהי' ללא פסולת (דוגמת <b>אכילת</b> המן מבלי שיצטרכו להסיר פסולת לאחרי האכילה), היינו, שהשימוש בפרנסה יהי' רק עבור דברים בריאים ושמחים<sup data-n=\"210\">97</sup>.\n<b>יח</b>. ויש לקשר זה עם האמור לעיל (ס\"ד) שמסעודת מלוה מלכה ניזון ונהנה העצם לוז שממנו יהי' תחיית המתים&lt;21&gt;:\nגשמיות מצד עצמו – ענינו \"מות\"<sup data-n=\"211\">98</sup>, שאין לו חיות וקיום מצד עצמו, וחיותו אינה אלא מצד הנשמה והרוחניות שממשיכים ונותנים בו.\nוזהו גם ענינו של העצם לוז – שכיון שלא נהנה מחטא עץ הדעת, \"אילנא דטוב ורע\"<sup data-n=\"212\">99</sup>, שייך הוא ל\"אילנא דחיי\"<sup data-n=\"212\">99</sup>, ולכן, ה\"ה ממשיך ונותן חיות בה\"מתים\", בענינים הגשמיים.ובפשטות – שיהי' שבוע בריא וחי (\"אַ געזונטע וואָך און אַ לעבעדיקע וואָך\"), בבני חיי ומזוני רויחי.\n***\n<b>יט</b>. בהמשך להמדובר לעיל (בהמאמר<sup data-n=\"213\">100</sup>) בענין \"לחזות בנועם הוי'\"<sup data-n=\"214\">101</sup> שהו\"ע התענוג (\"נועם\" מלשון תענוג) דעולם הבא – מבואר בלקו\"ת פרשתנו<sup data-n=\"215\">102</sup> שמהות תענוג זה הוא \"באופן אחר מה שאין ערוך אליו כלל כל עניני התענוגים שבעוה\"ז\",\nוממשיך, ש\"לכן ארז\"ל<sup data-n=\"216\">103</sup> גבי אלישע אחר מוטב דלדייני' וליתי לעלמא דאתי, אשר כדאי כל יסורי גיהנם כל י\"ב חודש . . [שהצער והיסורים דשעה אחת בגיהנם הם באין ערוך לכל יסורי עוה\"ז, כפי שמביא אדמו\"ר הזקן באגרת התשובה<sup data-n=\"217\">104</sup> \"מ\"ש הרמב\"ן<sup data-n=\"218\">105</sup> . . שאפילו יסורים של איוב ע' שנה אין להן ערך כלל ליסורי הנפש שעה אחת בגיהנם\"] בשביל שיקבל העונג כו'\".\nומקדים<sup data-n=\"219\">106</sup> לבאר שגם בתענוגי עוה\"ז יש חילוקי דרגות בתענוג, \"כמו דרך כלל יש תענוג בחוש הטעם . . וכן יש תענוג בדבור . . וכן יש תענוג בשמיעה קול נאה זמרא דפומא או כלי זמר ערב כו'\", ועד ל\"התענוג שבשכל . . (ש)הוא מהות תענוג אחר לגמרי מהתענוג שבחוש הטעם וכו'\".\nזאת ועוד:\nאצל בעל שכל (שזוהי שלימות האדם) שהוא חכם גדול – כל כח התענוג מונח רק בענין השכל והחכמה, שלכן מצינו אצל כמה חכמים, שלהיותם שקועים בעניני שכל וחכמה, לא הרגישו צער מענינים אחרים, וגם לא התענגו משאר ענינים, מלבד ענין השכל והחכמה, שבזה הי' מונח העצם שלהם.\nויש להביא דוגמא לזה – מאדם מבוגר, שלצחוק יחשב לו התענוג שמתענג תינוק קטן בענינים שלו. וכמו כן בנוגע ל\"קטנות\" ו\"גדלות\" אצל אדם מבוגר גופא, שהצורך שלו באכילה ושתי' הו\"ע של קטנות אצלו, ואילו הגדלות שלו היא שביכלתו להשיג ולחדש גם בשכל גדול ועמוק – הרי התענוג שבמילוי רעבונו וצמאונו ע\"י אכילה ושתי',<b>אינו תופס מקום כלל</b> ונחשב <b>כלא וכאין</b> לגבי התענוג שיש לו בלימוד החכמה.\nומזה מובן בנוגע לעניני חכמה גופא, שגם בהם (כמו בכל הענינים) יש חילוקים של קטנות וגדלות, חכמות קטנות וחכמות גדולות ועמוקות – שהתענוג בחכמות שהם בדרגא תחתונה אינו דומה להתענוג שבחכמה נעלית יותר, וכאשר מעלת החכמה היא שלא בערך, גם התענוג שבה הוא שלא בערך, ועד שיכול להיות שלגבי תענוג זה התענוג שבשאר החכמות הוא באופן של העדר תפיסת מקום לגמרי.\nוזוהי מעלת התענוג <b>שבתורה</b>:\nאע\"פ שגם התורה נקראת בשם חכמה, וכמ\"ש<sup data-n=\"220\">107</sup> \"כי היא חכמתכם גו' לעיני העמים\", היינו, שגם אינם-יהודים רואים את החכמה שבה, כך שיש לה נקודה משותפת עם סתם חכמות, מ\"מ, להיותה חכמה נעלית ביותר שלא בערך לגבי שאר חכמות,\n– שהרי התורה היא חכמתו ורצונו של הקב\"ה, והוא וחכמתו ורצונו אחד<sup data-n=\"221\">108</sup>, וא\"כ, כשם ש\"אין ערוך לך\", כך גם אין ערוך לחכמתו ית' –\nהרי גם התענוג שבה הוא שלא בערך לגבי כל שאר התענוגים, כולל גם התענוג שבחכמה נעלית ביותר.\n<b>כ</b>. והנה, בתענוג שבתורה גופא יש חילוקי דרגות.\nובהקדמה – שיש ב' אופני תענוג: תענוג המורכב, ותענוג פשוט<sup data-n=\"222\">109</sup>. וכשם שדבר שסובל הרכבה, ובפרט דבר המורכב, הוא באופן של <b>ירידה גדולה</b> לגבי מדריגתו בהיותו בפשיטותו, וכמ\"ש הרמב\"ם<sup data-n=\"223\">110</sup> שיסוד היולי הוא <b>באין ערוך</b> אפילו לגבי ד' היסודות הפשוטים ועאכו\"כ לגבי כל פרטי הנבראים שנוצרו מהרכבת ד' היסודות הפשוטים – הרי מובן שכן הוא גם בנוגע <b>לתענוג</b>, שתענוג המורכב <b>אינו בערך</b> לתענוג הפשוט.\nומזה מובן, שגם בתענוג שבתורה ישנו החילוק שבין תענוג המורכב לתענוג הפשוט, שזהו חילוק שבאין ערוך.\n<b>כא</b>. ובכללות – ה\"ז החילוק שבין נגלה דתורה לפנימיות התורה:איתא בזהר<sup data-n=\"224\">111</sup> שפנימיות התורה היא <b>נשמתא</b> דאורייתא, ונגלה דתורה – הן הן <b>גופי</b> תורה.\nוהחילוק שבין נשמה לגוף – שהנשמה היא ענין של <b>פשיטות</b> בערך הגוף, שהרי הגוף הוא <b>מורכב</b> מד' יסודות, והוא בעל שינויים, משא\"כ הנשמה שמצד עצמה <b>כולה רוחניות</b>, במכ\"ש ממלאכים שנקראים \"שכלים נבדלים\"<sup data-n=\"225\">112</sup>, כיון שנבדלים מד' יסודות, ועאכו\"כ נשמות, ש\"מחיצתן לפנים ממלאכי השרת\"<sup data-n=\"226\">113</sup>.\nומזה מובן גם בנוגע לתורה – שהחילוק בין פנימיות התורה, נשמתא דאורייתא, לנגלה דתורה, גופי תורה, הוא בדוגמת החילוק שבין <b>פשיטות</b> לגבי דבר <b>המורכב</b>.\nוההסברה בזה<sup data-n=\"227\">114</sup>:\nנגלה דתורה – קשור <b>ומורכב</b> עם עניני העולם שבהם דנים הלכות התורה, כמו הלכות תפילין בקלף גשמי והלכות ציצית בצמר גשמי,\n[וענין זה הוא בלימוד התורה דוקא, ולא במצוות, כי: קיום המצוות הוא <b>בגשם</b> הדבר, וא\"כ, אופן ההרכבה של המצוה עם הגשם הוא <b>שלא בערך</b>, ובמילא, אין זו \"הרכבה\"; אבל לימוד התורה אינו בהגשם (הקלף או הצמר) עצמו, אלא <b>בהסברא הרוחנית</b> הקשורה עם הדברים הגשמיים, ובמילא, שייך בזה \"הרכבה\" – כמ\"ש בתניא&lt;108&gt; שחכמתו של הקב\"ה \"נסעה וירדה . . ממדרגה למדרגה כו'\", עד שנתלבשה בהלכה הקשורה עם ענין גשמי].\nמשא\"כ פנימיות התורה – מדברת אודות עניני אלקות, עשר ספירות, אשר, \"איהו וחיוהי חד איהו וגרמוהי חד\"<sup data-n=\"228\">115</sup>, שזהו\"ע של <b>פשיטות</b> בערך כל העולמות והבריאה כולה.\n<b>כב</b>. וזוהי ההוספה שבלימוד פנימיות התורה לגבי לימוד נגלה דתורה וחיצוניות התורה:\nמחד גיסא יש מעלה בלימוד נגלה דתורה לגבי לימוד פנימיות התורה – כמ\"ש אדמו\"ר הזקן בסוף ספר התניא<sup data-n=\"229\">116</sup> ש\"בלימוד הלכותאתרוג (למשל) משיג ותופס האתרוג ממש ומצוותו כהלכה\", <b>השגת המהות</b>, משא\"כ בלימוד פנימיות התורה, עניני הספירות וכו' – \"אי אפשר לנברא להשיג כלום במהות האלקות\" [ובמכ\"ש וק\"ו: ומה מהות הנפש שלו אינו יכול להשיג, מהות הספירות – על אחת כמה וכמה], כי אם <b>ידיעת המציאות</b> בלבד.\nאבל לאידך גיסא – דוקא בפנימיות התורה ישנה ה\"<b>פשיטות</b>\" דתורה בערך להענינים שנשתלשלו למטה ונתלבשו ב\"גופי תורה\".\n<b>כג</b>. ועל זה ניתוסף החידוש של <b>תורת החסידות</b> – ע\"י הבעש\"ט, וממלאי מקומו, המגיד, אדמו\"ר הזקן, ורבותינו נשיאינו לדורותיהם, ועד לבעל ההילולא בדורנו זה:\nהחידוש של תורת החסידות הוא – שפנימיות התורה (ה\"<b>פשיטות</b>\" דתורה) תהי' לא רק באופן שלומדים מציאות האותיות והענינים, אלא שיומשך ויבוא <b>בהבנה והשגה</b>.\nוכיון ש\"גדול תלמוד שמביא לידי מעשה\"<sup data-n=\"230\">117</sup>, הרי לימוד תורת החסידות מביא גם תוספת אור וחיות במעשה:\nלכל לראש – שעי\"ז שיודע או לומד עכ\"פ כוונת המצוה, ניתוסף אצלו אור וחיות בקיום המצוות, שהרי כוונת המצוה היא כמו נשמה שמוסיפה חיות בהגוף<sup data-n=\"231\">118</sup>.\nזאת ועוד – שנוסף על תורת החסידות ולימוד תורת החסידות, ישנם גם <b>דרכי</b> החסידות.\n<b>כד</b>. אמנם, ישנם כאלה שרוצים לומר, ח\"ו, שכל זה שייך להבעל שם טוב, תלמידי הבעש\"ט וממלאי-מקומם, המגיד, אדמו\"ר הזקן ורבותינו נשיאינו. אבל בדורנו זה, כיון שהבעש\"ט הוא בעולם האמת, וכן גם המגיד, אדמו\"ר הזקן והרביים שלאחריו – איך יכולים בדורנו זה, דור יתום, לעסוק בענינים נעלים כאלה, ולומר שזוהי ההליכה בדרכי הבעש\"ט ואדמו\"ר הזקן וממלאי-מקומם, בה בשעה שלא הבעש\"ט עצמו נמצא, וגם לא תלמידיו ממלאי-מקומו?!...\nוהמענה לזה:\nכיון שהבעש\"ט הודיע לנו<sup data-n=\"232\">119</sup> שבעת \"עליית נשמה\" הידועה אמרלו מלכא משיחא (במענה לשאלתו אימת אתי מר) שיבוא כשיפוצו מעינותיך – דהבעש\"ט – חוצה, ולעת-עתה משיח עדיין לא בא,\nהרי, דבר ברור, שכל מי שמאמין בהבעש\"ט ובדברים ששמע הבעש\"ט ממלכא משיחא, מוכרח הוא גם להאמין שעכשיו ישנם המעיינות דהבעש\"ט, ועכשיו ישנו הענין דהפצת המעיינות – שהרי הוא \"מאמין . . בכל יום שיבוא\", \"אָט אָט קומט משיח\", עי\"ז שישלימו את הענין דהפצת המעיינות, ה\"פכים קטנים\" שעד עתה עדיין לא השלימו.\nזוהי איפוא <b>הוכחה ברורה</b> שעל כל אחד מאתנו מוטל התפקיד הקדוש להפיץ את המעיינות של הבעש\"ט והנשיאים שלאחריו שיגיעו גם ב\"חוצה\", שבזה תלוי' ביאת המשיח בפועל כאן למטה.\n<b>כה</b>. אלא שעדיין יש מקום לקושיא – מה כבר יוכל לפעול <b>בכחו הוא</b>, ובפרט שידע איניש בנפשי' מעמדו ומצבו?!\nהנה בנוגע למעלת הכחות שלו – \"בהדי כבשא דרחמנא למה לך\"<sup data-n=\"233\">120</sup>;\nאבל, מה שברור הוא – שהקב\"ה אינו מבקש \"אלא לפי כחן\"<sup data-n=\"234\">121</sup>, \"לפי הכח של כל או\"א\"<sup data-n=\"235\">122</sup>, ובמילא, תובעים ממנו שיעסוק בדבר – בכחו הוא – באופן ד\"בכל מאדך\"<sup data-n=\"236\">123</sup>, אשר, עם היותו \"מאד <b>שלך</b>\" בלבד, ה\"ז קשור עם \"מאד\" האמיתי<sup data-n=\"237\">124</sup>.\nוהמשל לזה – מתענוג של תינוק קטן, שאף שבאמת אין זה תופס מקום כלל אפילו לגבי כח היותר קטן של האב החכם, מ\"מ, כאשר התינוק הקטן מתמסר בכל עצמותו (\"גיט זיך אינגאַנצן אַוועק\") עם כח התענוג שלו, ה\"ה מגיע <b>בהתענוג דהאב</b>, ופועל שהאב מצמצם את עצמו בהתענוג של התינוק קטן (כנ\"ל בהמאמר<sup data-n=\"238\">125</sup>) – לא צמצום של העלם והסתר, אלא ע\"ד שאמרו<sup data-n=\"239\">126</sup> \"לעולם ישנה אדם לתלמידו דרך קצרה\", וב\"דרך קצרה\" זו מכניס הרב את כל עצמותו<sup data-n=\"240\">127</sup>.\nוכדאיתא במדרש<sup data-n=\"241\">128</sup> המשל מראיית בבואה ב\"מראות קטנות\" באותו אופן כמו ב\"מראות גדולות\".ולכן, מבלי להיות מרומה (\"ניט נאַרנדיק זיך\") במעמדו ומצבו, בכחו וביכלתו – הרי זה דבר ברור ופשוט, שכל אחד מששים ריבוא מישראל וענפיהם כו'<sup data-n=\"242\">129</sup> שבדרא דעקבתא דמשיחא, לא זו בלבד <b>שביכלתו</b> להפיץ את מעיינות הבעש\"ט, אלא עוד זאת שהראו לו <b>כיצד</b> לעשות זאת – כדברי כ\"ק מו\"ח אדמו\"ר<sup data-n=\"243\">130</sup>, בעל ההילולא, שהבעש\"ט גילה אודות <b>יכלתו</b> של כל יהודי, ואדמו\"ר הזקן הראה <b>כיצד</b> יכול כל יהודי לעשות זאת.\nעתה בדורנו זה, כל אחד הוא תלמיד של הבעש\"ט והנשיאים שלאחריו, אצלו נמצאים המעיינות דהבעש\"ט, ובכחו להפיץ אותם בחלקו בעולם עד שיחדור גם בה\"חוצה\" דחלקו בעולם – שזה יביא את המשיח (הפרטי<sup data-n=\"244\">131</sup>) בחלקו בעולם, ולאח\"ז – את המשיח הכללי דכללות ישראל, משיח כפשוטו, בשר ודם, ברמ\"ח אברים ושס\"ה גידים, למטה מעשרה טפחים.\n<b>כו</b>. ועדיין יש מקום לקושיא – שסוף-סוף, גם כשעוסקים בזה, רואים שפועלים רק \"קטנות\"?\nוהמענה לזה – ע\"פ דברי הגמרא במסכת סנהדרין<sup data-n=\"245\">132</sup>:\n\"כתיב<sup data-n=\"246\">133</sup> צדיק הוא חי' יחי', כשהי' רבן גמליאל מגיע למקרא הזה, הי' בוכה ואמר מאן דעביד <b>לכולהו</b> [כל הענינים הנעלים שנזכרו לפנ\"ז: \"אל ההרים לא אכל\"<sup data-n=\"247\">134</sup>, \"שלא אכל בזכות אבותיו\"<sup data-n=\"245\">132</sup>, וכן כל שאר הענינים שנימנו בהמשך לזה] הוא דחיי, בחדא מינייהו לא. א\"ל ר\"ע אלא מעתה אל<sup data-n=\"248\">135</sup> תטמאו בכל אלה<sup data-n=\"249\">136</sup> הכי נמי בכולהו אין בחדא מינייהו לא, אלא באחת מכל אלה, הכי נמי <b>באחת</b> מכל אלה\".\nועד\"ז במסכת מכות<sup data-n=\"250\">137</sup>: \"כתיב<sup data-n=\"251\">138</sup> עושה אלה לא ימוט לעולם . . מי כתיב עושה <b>כל</b> אלה, עושה אלה כתיב, אפילו <b>בחדא</b> מינייהו\".\nומזה מובן גם בנדו\"ד – שאצל כל אחד מאתנו ישנם המעיינות של הבעש\"ט, עכ\"פ באופן ד\"<b>אחת</b> מכל אלה\".ואין לומר שרק \"מאן דעביד לכולהו הוא דחיי, בחדא מינייהו לא\". – חס ושלום לומר שיהודי אינו קשור עם הבעש\"ט באופן של דביקות, שעז\"נ<sup data-n=\"252\">139</sup> \"ואתם הדבקים גו' (ועי\"ז) חיים\".\nגם מי שאינו עושה \"כל אלה\", אלא רק \"<b>אחת</b> מכל אלה\" – פעל וסיים (\"אויפגעטאָן און אָפּגעטאָן\") חלקו בהפצת המעיינות חוצה, וקירב – במקצת עכ\"פ – את הגאולה האמיתית ע\"י ביאת משיח.\n<b>כז</b>. המורם מכל האמור לעיל – שהפצת המעיינות אינו ענין של \"דרכי החסידות\", או ענין ששייך ליחידי סגולה בלבד, אלא זהו ענין השייך לכל אחד ואחת מישראל,\nאשר, לא זו בלבד שעליו מוטל החוב דהפצת המעיינות, אלא עוד זאת, שניתן לו הכח והיכולת (שהרי \"אין הקב\"ה בא בטרוניא עם בריותיו\"<sup data-n=\"253\">140</sup>) לעשות פעולה כזו שעשאה <b>הבעש\"ט בזמנו</b>!...\nאלא שהפעולה שלו היא כננס על גבי הענק<sup data-n=\"254\">141</sup>,\nוגם – לאחרי פתיחת הצינור והשביל [כתורת הבעש\"ט<sup data-n=\"255\">142</sup> בפירוש מארז\"ל<sup data-n=\"256\">143</sup> \"כל העולם ניזון <b>בשביל</b> חנינא בני\", \"שביל הוא צנור, שפתח צינור ושביל השפע\"] ע\"י רבותינו נשיאינו, שפתחו וגם סללו את השביל והדרך – \"<b>ה</b>דרך\" בה\"א הידיעה – דרך רחבה ביותר, כדאיתא בגמרא<sup data-n=\"257\">144</sup> ש\"<b>ה</b>דרך\" היא (לא רק \"דרך\" סתם של י\"ו אמה, אלא) של ל\"ב אמה, שבה ועל ידה נוכל להמשיך את המעיינות דהבעש\"ט חוצה.\nועוד והוא העיקר:\n\"גופא\" – כל חלקי הגוף, אפילו החלק היותר תחתון, העקב שברגל, שגם הוא חלק מהגוף – \"בתר רישא אזיל\"<sup data-n=\"258\">145</sup>, כיון שקשור עמו. וכמו כן קשורים אנו עם הנשמה הכללית שלנו (\"אָט אַזוי זיינען מיר פאַרבונדן מיט אונזער נשמה כללית\").\nוא\"כ, <b>התקשרותנו עם הנשיאים</b> בקשר אמיץ וחזק בל ינתק, היא היא שנותנת לכל אחד את <b>הכח</b> – מבלי הבט על הכח שלו (מצד עצמו) בתור איש פרטי – לפעול חלקו בהפצת המעיינות.<b>כח</b>. וע\"י ההתעסקות בהפצת המעיינות, זוכים לכל השכר – \"כל הון ביתו\"<sup data-n=\"259\">146</sup>, שניתן לו על ידי הקב\"ה (\"דאָס גיט אים אָפּ דער אויבערשטער\"), באופן ד\"בוז יבוזו לו\"<sup data-n=\"260\">147</sup>,\nועד שזוכים \"לחזות בנועם הוי'\"&lt;101&gt; (כנ\"ל בהמאמר<sup data-n=\"261\">148</sup>) – גילוי עצם התענוג שישנו בפנימיות התורה, ועי\"ז נמשך גם בנגלה דתורה,\n– כן תהי' לנו במהרה ממש, כאשר יקויים היעוד<sup data-n=\"262\">149</sup>:\n\"ונגלה כבוד הוי'\" – שהקב\"ה \"מוציא חמה מנרתקה\"<sup data-n=\"263\">150</sup>, שמוציא את ה\"שמש הוי'\" מהמגן ונרתק דשם אלקים<sup data-n=\"264\">151</sup>,\n\"וראו כל בשר\" – אפילו בשר הגשמי, ולא רק של בני אדם, אלא גם של בעלי-חיים, ע\"ד מ\"ש<sup data-n=\"265\">152</sup> \"וישרנה הפרות\",\n\"כי פי הוי' דיבר\".\n***\n<b>כט</b>. דובר בארוכה אודות מ\"ש בפרשת השבוע&lt;89&gt; \"הנני ממטיר לכם <b>לחם מן השמים</b>\" (שלכן, הברכה שהוצרכו לברך לפניו<sup data-n=\"266\">153</sup> לא היתה יכולה להיות \"המוציא לחם <b>מן הארץ</b>\"), שדוגמתו בתורה הוא <b>פנימיות</b> התורה (שחלוקה מנגלה דתורה שהיא בדוגמת \"לחם מן הארץ\")<sup data-n=\"267\">154</sup>,שניתנה ושייכת (לא רק ליחידי סגולה, אלא) לכאו\"א מישראל (לא רק לצדיקים או בינונים אלא גם לרשעים), כפי שלמדים מזה ש\"כבר הי' לעולמים\" ב\"לחם מן השמים\" כפשוטו, שירידת המן היתה לכל הסוגים דבנ\"י – הוגה ע\"י כ\"ק אדמו\"ר שליט\"א, ונדפס בלקו\"ש ח\"ד ע' 1035 ואילך<sup data-n=\"268\">155</sup>.\n[בהמשך הענין (שם ע' 1040), בנוגע לטענות החדשות שלימוד החסידות שייך ליחידי סגולה ויש צורך בהכנות כו' – אמר:\nמהטענות החדשות – שמפורש בגמרא<sup data-n=\"269\">156</sup> \"אם דומה הרב למלאך ה' צבאות יבקשו תורה מפיו\", וא\"כ, צריך להמתין עד שירד \"מלאך ה' צבאות\", ואז יתיישב ללמוד עמו פנימיות התורה!...\nיש לדעת, איפוא, שזוהי \"תחבולה\" ו\"המצאה\" נוספת של היצה\"ר – ככל שאר תחבולות היצה\"ר ש\"היום אומר לו עשה כך כו'\"<sup data-n=\"270\">157</sup> – שבאה מצד החושך כפול ומכופל דזמן הגלות.\nובהקדים פתגם כ\"ק מו\"ח אדמו\"ר בעל ההילולא בשם אביו<sup data-n=\"271\">158</sup> – שלפעמים מתעטף היצה\"ר באצטלא של קדושה \"<b>אַ זיידענע זשופּיצע</b>\" (סירטוק של משי),\n– וכידוע פתגם זקני החסידים (ויש אומרים שהוא בשם הנשיאים)<sup data-n=\"272\">159</sup>: \"וואָס מיינסטו? עשו איז געגאַנגען אַרומגעגאַרטלט מיט אַ האַרטע שטריק; ער איז געגאַנגען מיט אַ זיידענע זשופּיצע\"!... ואעפ\"כ \"הולך לקראתך וארבע מאות איש עמו\"<sup data-n=\"273\">160</sup>, כדי למנוע מיעקב לבוא לקיום היעוד<sup data-n=\"274\">161</sup> \"ועלו מושיעים בהר ציון לשפוט את הר עשו\", וטוען \"יש לי רב\"<sup data-n=\"275\">162</sup>, וכו' וכו' –\nוכן הוא בנדו\"ד, שכיון שמדובר אודות העלם והסתר על לימוד פנימיות התורה, בהכרח שיבוא דוקא ע\"י יהודי שיש לו גם \"בבואה דבבואה\"<sup data-n=\"276\">163</sup>, ואכן מצא היצה\"ר <b>שוטים</b>\n– (כ\"ק אדמו\"ר שליט\"א חייך ואמר:) שוטים ישנם בכל דור,ובלשון חז\"ל<sup data-n=\"277\">164</sup> \"יאבד עולמו מפני השוטים\" (בתמי'). שכן, כשם שישנם צדיקים בכל דור, כמארז\"ל<sup data-n=\"278\">165</sup> \"ראה הקב\"ה שצדיקים מועטין עמד ושתלן בכל דור ודור\", כן הוא גם בלעו\"ז, ובמילא, ניתן למצוא שוטים אחדים \"אפילו\" בדורנו זה... –\nש\"אימצו\" את טענת היצר שכדי ללמוד פנימיות התורה צריך להמתין לרב שדומה למלאך ה' צבאות!...\nלפי הבנתם המגושמת – צריך להתעופף אדם עם שני כנפיים על גבו... לטפח בכנפיו (\"פּאַטשן מיט די פליגלען\") ולצעוק \"קדוש קדוש\"... – או אז \"יודה\" שאכן מראים לו (מלמעלה) שצריך הוא ללמוד פנימיות התורה!...\n– כ\"ק מו\"ח אדמו\"ר סיפר פעם<sup data-n=\"279\">166</sup> אודות אדמו\"ר הצמח-צדק והרה\"צ ר' יעקב ישראל מטשערקאַס (בנו של הרה\"צ ר' מרדכי מטשרנוביל) – שניהם היו חתניו של אדמו\"ר האמצעי – שהתחנכו אצל רבינו הזקן, והיו נוהגים ללמוד יחד בעלי', ולאחר משך זמן התיישבו בדעתם לעסוק בתעניות כו' כדי לזכות לגילוי אליהו. ואכן התענו במשך זמן עד שכבר לא היו בכחם לטפס לעלי', כך שאירע שאחד מהם נשאר למטה.\nבסופו של דבר פגשו מישהו שלא הכיר את מקומו... ורצה \"להצטרף\" אליהם. הלה הי' יושב (או שוכב) למטה ומתטען (\"ער פלעגט זיך אויס'טענה'ן\") בינו לבין עצמו: היתכן שלאחרי שכבר גמר להתענות מספר התעניות הדרוש, וכבר קיים את כל הסיגופים – אין לו עדיין גילוי אליהו, <b>היפך המפורש בספרים</b> שלאחרי הכנות הנ\"ל, שעשאם כבר, בא גילוי אליהו?!... וכיון שאין שום תירוץ על זה, הרי סימן שמשהו פה אינו כשורה (\"עפּעס שטימט דאָ ניט\")...\nכאשר ראו הצ\"צ וחברו שיש להם \"עסק\" עם יהודי מסוג כזה... החליטו ללמדו לקח:\nהלה הי' נוהג לבוא מידי לילה בלילה – לערוך \"תיקון חצות\", לקונן על גלות השכינה, או כדי להתטען אודות גילוי אליהו. ובשעה שהי' עסוק ב\"עבודתו\", שאז ישבו הם בעלי' – שפכו עליו מים מלמעלה, והכריזו בקול: \"<b>טהור טהור</b>\"!... ואכן, \"נתיישב\" אצלו שכל מהשכתוב בספרים (אודות הדרכים לזכות לגילוי אליהו) הוא דבר <b>אמת</b>, והראי', ששמע בעצמו קול מלמעלה... וכבר נתקיים בו \"וזרקתי עליכם מים טהורים\"... ועוד הכריזו עליו \"טהור טהור\"... ומזה מוכח ש\"משה אמת ותורתו אמת\"!...\nוכמו כן בנדו\"ד – שמצד ההגשמה שלו, חושב שצריך לעוף מישהו עם שתי כנפיים, לטפח בכנפיו ולצעוק \"קדוש\", ואזי יתחיל ללמוד פנימיות התורה... אלא שעתה, אין הזמן גרמא לוותר ולהתרצות (\"נאָכגעבן\") ולמלא את רצונו בה\"שטותים\" שלו (כבסיפור האמור), ולפועל, לעת עתה, לא זו בלבד שהוא בעצמו אינו לומד פנימיות התורה, אלא עוד זאת, שרוצה לפעול ח\"ו על הזולת שגם הוא לא ילמוד.\nובכל אופן, כיון שמדובר אודות <b>שוטים</b> – מוטב שלא להתעסק עמהם כלל (\"עס איז געזינטער האָבן מיט זיי וואָס ווייניקער צו טאָן\").\n– כ\"ק מו\"ח אדמו\"ר (בעל ההילולא) סיפר פעם<sup data-n=\"280\">167</sup> אודות א' מזקני החסידים של הצ\"צ, שהקפיד על מנהגו לילך <b>רגלי</b> לליובאוויטש, עד כדי כך, שכאשר לא הי' בכחו לילך בכל שנה (כדרכו בצעירותו), הי' הולך רק פעם בשנתיים, אמר פעם לבניו ונכדיו – במענה לטענתם למה מתעקש לילך <b>רגלי</b> דוקא, ולא <b>לנסוע</b> – שכאשר יגיע לעולם האמת (או לעתיד לבוא) יצרף למשקולת זכיותיו את הליכתו לליובאוויטש כך וכך פעמים, שעל זה מגיע לו שכר פסיעות, שכר הליכה (נוסף על \"שכר מעשה\"). וסיים, שכל זמן שילך לליובאוויטש <b>רגלי</b>, יהי' מונח על קו המשקולות הוא לבדו, אבל, אם יסע לליובאוויטש עם סוס (או שור), הרי יבוא גם <b>הסוס</b> (או השור) ויטיל את עצמו על קו המשקולות, ויתבע את חלקו... ובמילא (כ\"ק אדמו\"ר שליט\"א אמר בשחוק:) \"<b>וויל ער מיט קיין פערד ניט האָבן צו טאָן</b>... אפילו דאָרטן אויך ניט\" (אינו רוצה להתעסק עם סוס, אפילו לא בעולם האמת)!\nונוסף על זה בנדו\"ד – שכאשר מתעסקים עם שוטה (באיזה קו שיהי', אפילו בקו של דחי' כו'), הרי, נוסף לכך שחבל על הזמן, ומה גם שאין צורך לדחות את החושך ע\"י ההתעסקות (\"דורך פּאָרקען זיך\") עם <b>החושך</b>, כיון שיכולים לדחותו אפילו ע\"י \"<b>מעט אור</b>\"<sup data-n=\"281\">168</sup>, ועאכו\"כ ע\"י <b>ריבוי אור</b> – הנה עוד זאת, בנוגע לשוטים יש צורך בזהירות, כמובןמדברי המשנה<sup data-n=\"282\">169</sup> ש\"פגיעתן רעה, החובל בהן חייב והם שחבלו באחרים פטורין\"...\nומה שגרוע עוד יותר, והוא העיקר – ש\"המתאבק עם מנוול מתנוול ג\"כ\"<sup data-n=\"283\">170</sup>, כך שבשעה שמתאבק עם שוטה, עלול להתדבק בו משהו.\n(כ\"ק אדמו\"ר שליט\"א סיים שהעצה היא איפוא להוסיף אומץ בלימוד והפצת החסידות, ועי\"ז זוכים לביאת משיח צדקנו, למטה מעשרה טפחים)].\n***\n<b>ל</b>. הסדר ביו\"ד שבט הוא – לערוך מגבית לטובת \"קרן תורה\"<sup data-n=\"284\">171</sup>:\n\"קרן תורה\" נוסדה לעזור ולסייע לאלה הרוצים ללמוד תורה שלא לשם \"תכלית\",\n– כי, כשם שהקב\"ה, נותן התורה, הוא בלי תכלית ובלי גבול ובלי סוף, כך צריך האדם להקדיש מזמנו כמה שנים (ולכל הפחות כמה חדשים או כמה שבועות) ללימוד התורה ללא תכלית –\nובפשטות – לימוד תורה לשמה, ללא ענינים צדדיים (כמו על מנת שיהי' רב, שעושה את התורה קרדום לחפור בו<sup data-n=\"285\">172</sup>, או כדי לקבל \"סמיכה\", וכיו\"ב),\nאלא שישנם כאלה שמבלבלת אותם השאלה \"וכי תאמרו מה נאכל גו'\"<sup data-n=\"286\">173</sup> – ולכן נתייסדה \"קרן תורה\", כדי להסיר את השאלה \"מה נאכל\" ע\"י הסיוע מקרן זו במשך הזמן שבו ילמדו תורה באופן האמור.\nוע\"פ הנהוג בשנים האחרונות – תורמים ומפרישים לקרן זו בעת ההתוועדות דיום ההילולא.\nוכיון שמדובר אודות ענין שרוצים שיהי' באופן של פנימיות בטהרתו (\"פנימיות אַליין\"), ללא פניות צדדיות – הנה גם ההפרשה והנתינה לקרן זו היא לא באופן שמדפיסים אודותי' בעיתון, שולחים מכתבי תודה, או מכריזים בקול גדול שפלוני בן פלוני הפריש סכום כךוכך, אלא משאירים את הדבר לכאו\"א, שיתן כפי יכלתו, ומה טוב, \"בכל מאדך\"&lt;123&gt;, לכל הפחות \"מאד שלך\"&lt;124&gt;.\nוכל מי שרוצה, יכול לרשום על פתקא שמו ושם אמו – כדי להזכירו על ציונו של בעל ההילולא, שהשתתף ב\"קרן תורה\".\nובא' משני אופנים: (א) לרשום באותה פתקא – גם את סכום הנתינה, (ב) ליתן הסכום בפ\"ע, והפתקא בפ\"ע, כי, הפתקא תהי' נקראת גם ע\"י בן-אדם – שהרי מסתמא אקרא אני את הפתקא על הציון, ובמילא, אם רצונו להעלים גם ממני את הסכום, הברירה בידו לרשום שמו ושם אמו על פתקא בפ\"ע, ואת הסכום בפתקא בפ\"ע.\nואלה שרוצים ליתן ב\"מזומן\" – תבוא עליהם ברכה, והם מוקדמים לברכה, ע\"ד מ\"ש בגמרא (במסכת תענית<sup data-n=\"287\">174</sup>) החילוק בין אבא חלקי' ואשתו, שתפלתה פעלה במהירות יותר, לפי ש\"יהבא ריפתא לעניי ומקרבא הנייתה\" (\"שדבר אכילה היא נותנת לעני והוא בלא טורח ממה שהיתה נותנת מעות ויטריח העני עד שיקנה\"<sup data-n=\"288\">175</sup>), ואילו אבא חלקי' \"יהיבנא זוזא ולא מקרבא הנייתי'\". וכ\"ש וק\"ו כשמישהו נותן רק <b>הבטחה</b> על ממון – שדבר זה רחוק לא רק מנתינת אוכל ומשקה כפשוטו, אלא אפילו מנתינת ממון.\nאבל, מכיון שאין רוצים לקבוע הגבלות באופן הנתינה – יכול כאו\"א ליתן <b>במזומן</b> את הסכום המתאים לפניו, <b>ולהבטיח</b> על להבא סכום גדול יותר.\nויהי רצון שע\"י ההוספה בצדקה,\n– כמ\"ש באגה\"ק&lt;48&gt; ש\"עיקר עבודת ה' בעתים הללו . . היא עבודת הצדקה . . בעקבות משיחא שנפלה סוכת דוד עד בחי' רגלים ועקביים שהיא בחי' עשי', אין דרך לדבקה בה באמת . . כ\"א בבחי' עשי' ג\"כ שהיא מעשה הצדקה כו'\" –\nובפרט ריבוי הצדקה, שזוהי מעלתה המיוחדת של ארצות הברית –\nתמשיך ותביא את ה\"צדקה\" של הקב\"ה – גאולה האמיתית והשלימה בקרוב ממש.\n[כ\"ק אדמו\"ר שליט\"א צוה לחלק פתקאות בין הקהל, ואח\"כ אמר:]דובר פעם<sup data-n=\"289\">176</sup> שכדי שתהי' הנתינה לצדקה בשמחה – כדאי לנגן בעת מעשה ניגון שמח, \"וועט דאָס גיין פריילעכער\".\n[ניגנו ניגון שמח. אח\"כ צוה כ\"ק אדמו\"ר שליט\"א לכו\"כ אנשים פרטיים – בנקבו בשמותיהם – לומר \"לחיים\". אח\"כ התחיל לנגן \"כי אנו עמך\"].\n***\n<b>לא</b>. יום הש\"ק דמיני' אזלינן – כיון ש\"מיני' מתברכין כולהו יומין\", כולל הוא את כל ימי השבוע הבאים אחריו.\nוע\"פ האמור לעיל (סי\"ז) ש\"מיני' מתברכין כולהו יומין\" נאמר בזהר בנוגע לירידת המן – ה\"ז מודגש ביותר בש\"ק פרשת בשלח, שבה מסופר בתורה אודות ירידת המן, ו\"אסתכל באורייתא וברא עלמא\"<sup data-n=\"290\">177</sup>, שע\"י הקריאה <b>בתורה</b> מתחיל ענין חדש בזה גם <b>בעולם</b>.\nומהענינים המיוחדים בימי השבוע הבא (שמתברכים מיום הש\"ק זה) הוא – יום חמשה עשר בשבט, \"ראש השנה לאילנות\".\n<b>לב</b>. ובהקדם הפלוגתא שבדבר – כדאיתא במשנה<sup data-n=\"291\">178</sup> \"באחד בשבט ראש השנה לאילן, כדברי בית שמאי. בית הלל אומרים בחמשה עשר בו\":\nדובר כמ\"פ<sup data-n=\"292\">179</sup> אודות ה\"לשיטתייהו\" דב\"ש וב\"ה בכמה ענינים בש\"ס – שב\"ש סברי שאזלינן בתר \"בכח\", היינו, שגם כשהדבר נמצא בכח ובמחשבה ה\"ז נחשב כאילו כבר ישנו בפועל, וב\"ה סברי שאזלינן בתר \"בפועל\", היינו, שלא מספיק קיומו של הדבר בכח, אלא יש צורך להמתין עד שישנו בפועל.\nאמנם, כלל זה אינו בכל הענינים [דא\"כ, היתה צ\"ל הפלוגתא דב\"ש וב\"ה <b>בכל</b> הענינים שבתורה, שהרי בכל ענין ישנו כפי שהוא \"בכח\" וכפי שהוא \"בפועל\"], כי אם, בענין <b>שגדרו</b> הוא \"<b>בכח</b>\", בענין כזה דוקא פליגי ב\"ש וב\"ה אם גם בו צ\"ל ה\"<b>בפועל</b>\" של ה\"בכח\", או, שכיון שכל גדרו של ענין זה הוא \"בכח\", עכצ\"ל שבענין זה לא נוגע ה\"בפועל\", וא\"כ, מספיק גם ה\"<b>בכח</b>\" של ה\"בכח\".וזהו שפלוגתתם היא (בין השאר) בנרות חנוכה – כיון שנס חנוכה הו\"ע של \"<b>בכח</b>\":\nנס חנוכה הוא – ש\"לא הי' בו (בפך השמן) אלא להדליק יום אחד, נעשה בו נס והדליקו ממנו שמונה ימים\"<sup data-n=\"293\">180</sup>, היינו, שבשיעור השמן של יום אחד (לוג א'<sup data-n=\"294\">181</sup>) הי' <b>בכח</b> שמונה לוגים, שלכן \"הדליקו ממנו שמונה ימים\".\nוכיון שמדובר אודות נס שהי' באופן של \"בכח\" – פליגי בזה ב\"ש וב\"ה<sup data-n=\"293\">180</sup>:\nב\"ש סוברים <b>שבענין זה</b> אזלינן בתר ה\"בכח\", ולכן, \"יום ראשון מדליק שמונה מכאן ואילך פוחת והולך . . כנגד ימים הנכנסין\", כי, הנס היותר גדול הוא ביום ראשון, שבו ישנו ה\"בכח\" של שמונה ימים, ואילו למחרת, יש \"בכח\" רק שבעה ימים, ומיום ליום פוחת והולך ה\"בכח\";\nוב\"ה סוברים, שהן אמת שהנס מצד עצמו הו\"ע של \"בכח\", אבל אעפ\"כ, בזה גופא צ\"ל ה\"<b>בפועל</b>\" של הנס, וכיון שה\"בפועל\" של ה\"בכח\" הולך וגדל מיום ליום, לכן, \"יום ראשון מדליק אחת מכאן ואילך מוסיף והולך . . כנגד ימים היוצאין\", עד ליום השמיני שבו מדליקים כל שמונת הנרות.\nוכמו כן פליגי בסוף מסכת עוקצין<sup data-n=\"295\">182</sup> – \"חלות דבש מאימתי מיטמאות משום משקה, ב\"ש אומרים משיהרהר, ב\"ה אומרים משירסק\":\nהמדובר כאן הוא לא בנוגע לקבלת טומאה בפועל, כי אם, אודות <b>הכשר</b> לקבלת טומאה (מאימתי יוצאים מתורת אוכל לתורת משקה שיהיו מוכשרין לקבל טומאת משקין), שזהו ענין של \"<b>בכח</b>\".\nולכן פליגי בזה ב\"ש וב\"ה: ב\"ש סוברים שבענין של \"בכח\" מספיקה גם עשיית האדם (לשנות החלות דבש מאוכל למשקה) באופן של \"בכח\" – \"משיהרהר\", מחשבה בלבד, <b>שמחשבה</b> לגבי מעשה היא כמו \"<b>כח</b>\" לגבי פועל; וב\"ה סוברים שגם בענין זה יש צורך בה\"בפועל\" – לכל הפחות ה\"בפועל\" של ה\"בכח\".\nוזוהי גם פלוגתתם בנוגע לראש השנה לאילנות – כיון ש\"ראש השנה\" הו\"ע של \"<b>בכח</b>\":ענינו של \"ראש השנה\" – שכולל את כל ימי השנה הבאים לאחריו. וכמודגש בדיוק הלשון \"<b>ראש</b> השנה\", ולא \"תחלת השנה\"<sup data-n=\"296\">183</sup> – כי, כמו שה\"ראש\" כולל כל איברי הגוף, כך כולל \"ראש השנה\" את החיות של כל ימי השנה הבאים לאחריו.\nודוגמתו בנוגע ל\"<b>ראש</b> השנה לאילנות\" – שבו כלולים \"<b>בכח</b>\" כל הימים הבאים לאחריו (עד ר\"ה לאילנות הבא) – שכל הפירות הצומחים במשך כל השנה כולה נמנים <b>יחד</b> עם הפירות שצמחו ביום ר\"ה לאילנות <b>עצמו</b>.\nוכן הוא לפי פשוטם של דברים – שאז כבר \"יצאו רוב גשמי שנה\", \"ועלה השרף באילנות, ונמצאו הפירות חונטין מעתה\"<sup data-n=\"297\">184</sup>, \"מכאן ואילך הן חיין מימי השנה הבאה\"<sup data-n=\"298\">185</sup> – הרי אין פירוש הדברים שבימים אלה נראים כבר השרף והלחלוחיות הדרושים בשביל כל הפירות שיצמחו במשך שנה הבאה, כי אם, שאז היא <b>ההתחלה</b> שכוללת (\"בכח\") את השרף דכל הפירות שיצמחו ממנו במשך השנה כולה.\nוכיון שתוכנו של ראש השנה לאילנות הו\"ע ד\"בכח\" – פליגי בזה ב\"ש וב\"ה:\nב\"ש סוברים שמספיק שישנו הענין \"בכח\" – \"באחד בשבט\", שלהיותו \"<b>ראש</b> חודש\" שכולל את כל ימי החודש, ה\"ה כולל גם את החיות של יום חמשה עשר בשבט, ואין צורך להמתין שיום חמשה עשר בשבט יבוא בפועל, דכיון שגם בבוא חמשה עשר בשבט בפועל ישנו הענין ד\"ראש השנה לאילנות\" רק \"בכח\", הרי מספיק שגם חמשה עשר בשבט עצמו יהי' \"בכח\" (בר\"ח שבט); וב\"ה אזלי לשיטתייהו, שגם בדבר שגדרו \"בכח\" יש צורך לה\"בפועל\" של ה\"בכח\", ולכן צריך להמתין שיבוא יום חמשה עשר בשבט בפועל.\n<b>לג</b>. ויש להוסיף ולבאר תוכן הפלוגתא בנוגע לר\"ה לאילנות בקשר ובשייכות לעבודת האדם – \"כי האדם עץ השדה\"<sup data-n=\"299\">186</sup>:\nובהקדמה<sup data-n=\"300\">187</sup> – שבתחלת בריאת האדם, בימי ההריון, ובכמה ענינים אפילו בתחלת הלידה – הרי הוא בדוגמת \"<b>דומם</b>\", שאינו יכול לנוע ממקומו, ואין בו צמיחה; ולאח\"ז מתעלה האדם מ\"דומם\" ל\"<b>צומח</b>\" – בדוגמת \"עץ השדה\" – שנעשית אצלו הצמיחה מקטנות לגדלות.ובזה נכללת גם העלי' לדרגא נעלית עוד יותר – מ\"צומח\" ל\"חי\", ומ\"חי\" ל\"מדבר\" – שהרי האדם הוא הבריאה <b>התיכונה</b> שכולל את הבריאה כולה:\nמ\"צומח\" ל\"חי\" – שלא זו בלבד שיש בו צמיחה מקטנות לגדלות, אלא עוד זאת, ששוב אינו זקוק להחיבור לשרשו (כצומח), אלא יכול להתנתק מהשורש שממנו נולד וצמח, ולילך <b>למקום חדש</b> ולהמשיך להתפתח שם.\nוכל זה אינו מספיק עדיין, אלא צריך להוסיף ולהתעלות מ\"חי\" ל\"<b>מדבר</b>\" – עליו נאמר<sup data-n=\"301\">188</sup> \"ורדו בדגת הים ובעוף השמים ובכל חי' הרומשת על הארץ\" – שנוסף על השלימות <b>שלו</b>, יש לו די כח ושכל <b>לפעול בהבריאה כולה</b> את התכלית הנדרשת ממנה.\n<b>לד</b>. וכן הוא הסדר בעבודת האדם לקונו<sup data-n=\"302\">189</sup> – שזוהי תכלית בריאתו – \"אני נבראתי לשמש את קוני\"<sup data-n=\"303\">190</sup>:\nבתחלת העבודה – אין האדם אלא <b>מקבל</b> בלבד, שמקבל כח והדרכה, ולא עוד אלא שמקבלה <b>כמו שהיא</b> (ולא באופן שנעשית אצלו איזו צמיחה כמו גרעין שמתחיל לצמוח), כי, להיותו עדיין בתחלת העבודה, אין בכחו להוסיף משהו בכח עצמו, כי אם להיות בבחינת מקבל בלבד, שזהו בדוגמת דומם.\nאמנם, תפקידו של האדם הוא (לא רק להיות \"מקבל\" בלבד, אלא) לעבוד גם <b>בכח עצמו</b>, שההתחלה בזה היא כשיוצא ממדרגת \"דומם\" (מקבל בלבד) למדרגת \"<b>צומח</b>\", לעבוד עבודתו בכח עצמו, ובזה גופא הולך ומתעלה מדרגא לדרגא.\nובפרטיות יותר:\nכאשר יוצא מדרגת דומם, מקבל בלבד, ומתחיל העבודה בכח עצמו – הנה תחילת הדרך, תחילת העלי', היא באופן של \"צומח\", שהצמיחה היא בהיותו מחובר לשרשו, היינו, שבנוגע לכל ענין צריך הוא לשאול את ה\"שרש\" – את המשפיע, ואין בכחו להתנתק ממקומו, מהסביבה שבה גדל ונתחנך, ומהענינים שעליהם נתחנך והורגל בהם. –בענינים אלה הוא אמנם \"מבין דבר מתוך דבר\"<sup data-n=\"304\">191</sup>, אבל, כל זה אינו אלא באותו מקום ובאותם ענינים שלימדוהו חינכוהו והדריכוהו בהם, ואילו בשעה שעוקר משרשו ומקורו – מאבד עשתונותיו (\"ער פאַרלירט זיך\"), ואין בכחו להתמודד עם המצב החדש שנקלע אליו.\nולכן אין זה מספיק עדיין, אלא צריך להתעלות מדרגת \"צומח\" לדרגת \"חי\" – שלא ישאר לעסוק רק באותם ענינים שבהם הדריכוהו, ולא ישאר רק באותה סביבה שבה גדל ונתחנך, אלא ילך למקום <b>חדש וזר</b>, וגם שם ימשיך באותו אורח-חיים – כמשל בן המלך שאביו המלך שולחו למדינה רחוקה, כמבואר בארוכה בהמשך תרס\"ו<sup data-n=\"305\">192</sup> שהתענוג האמיתי של המלך מבנו אינו כל זמן שהבן נמצא בהיכל המלך, אלא דוקא כאשר שולח אותו למדינה רחוקה, ובהיותו שם מראה בן המלך שאינו מאבד עשתונותיו (\"ער פאַרלירט זיך ניט\"), וממשיך להתנהג כפי שהתנהג בהיותו בהיכל המלך.\nאמנם, גם העלי' ממדרגת \"צומח\" למדרגת \"חי\" אינה מספיקה עדיין, כיון שזוהי רק עבודתו <b>בעצמו</b>, ונוסף לזה צריכה להיות העלי' למדרגת \"מדבר\" – \"ורדו בדגת הים ובעוף השמים ובכל חי' הרומשת על הארץ\" – שתהי' לו שליטה וממשלה על <b>חלקו בעולם</b>, למלא שם את שליחותו בעולם, לעשות רצונו בלב שלם.\nועוד ענין עיקרי בזה – שנוסף על עבודתו בעצמו צריך להיות גם הענין ד\"ואהבת לרעך כמוך\"<sup data-n=\"306\">193</sup>,\n– שזהו ענין עיקרי בכללות העבודה, כדברי בעל ההילולא<sup data-n=\"307\">194</sup> ע\"ד פתגם רבינו הזקן ש\"ואהבת לרעך כמוך\" <b>חד הוא</b> עם \"ואהבת את הוי' אלקיך\"&lt;123&gt;. והענין בזה – ש\"ואהבת את ה' אלקיך\" הוא שרש לכל מצוות עשה&lt;108&gt;, כולל גם המ\"ע דיראת השם (\"את ה' אלקיך תירא\"<sup data-n=\"308\">195</sup>), שהיא השרש לכל מצוות לא תעשה&lt;108&gt;, ונמצא, ש\"ואהבת את ה' אלקיך\" היא השרש לכל מצוות התורה. ועל זה אומר רבינו הזקן שמצוה זו חד היא עם \"ואהבת לרעך כמוך\", לפי שדוקא ע\"י התאחדות כל בנ\"י יחד יכולים לפעול ולקיים (\"דורכטאָן\") כל התומ\"צ –\nוכיון שגם לחבירו ניתן חלקו בעולם, וגם חלקו של חבירו שייךאליו כיון ש\"כל ישראל ערבין זה בזה\"<sup data-n=\"309\">196</sup> – צריך הוא לפעול על כל שאר בנ\"י שגם הם יתעלו למדריגת \"מדבר\", שתהי' להם שליטה וממשלה על חלקם בעולם ע\"י מילוי שליחותו של הקב\"ה לעשות רצונו בלב שלם.\n<b>לה</b>. וכאן באה פלוגתת בית שמאי ובית הלל בנוגע לראש השנה לאילנות כפי שהוא ב\"האדם עץ השדה\" – שמורה על העבודה בכח עצמו, ששלימותה כשהולך ומתעלה מ\"צומח\" ל\"חי\", ומ\"חי\" ל\"מדבר\", שמושל ושולט על חלקו בעולם, ויתירה מזה – ע\"י הצירוף והאחדות עם כל שאר בנ\"י – גם בכל העולם כולו.\nותוכן הפלוגתא – האם הצירוף והאחדות עם כל בנ\"י [שבזה מתבטאת שלימות עבודת האדם בכח עצמו – ענין הצמיחה – שיש לו שליטה וממשלה בכל העולם] מספיק שיהי' \"<b>בפועל</b>\" (במעשה ובדיבור), או שצריך שיהי' ניכר גם \"<b>בכח</b>\" (במחשבה):\nבית שמאי – מלשון \"השם אורחותיו . . ששוקל דרכיו איך ומה הוא\", כמבואר בלקו\"ת<sup data-n=\"310\">197</sup>, וכן הוא פשטות סיפור הגמרא<sup data-n=\"311\">198</sup> אודות \"<b>קפדנותו</b> של שמאי\" – דורשים הם שלא רק כשיבוא למעשה בפועל יתנהג באופן של \"ואהבת לרעך כמוך\" לעסוק עם הזולת, אלא גם כאשר הענין הוא <b>במחשבה</b> צריך להיות <b>נוגע לו</b> מציאותו של הזולת. כלומר, הענין ד\"ואהבת לרעך כמוך\" צריך להיות לא רק \"בפועל\", אלא אפילו \"<b>בכח</b>\", בכח המחשבה שלו.\nובית הלל סוברים שמספיק אם עכ\"פ <b>במעשה בפועל</b> – בבוא יום חמשה עשר שבו קיימא סיהרא באשלמותא<sup data-n=\"312\">199</sup>, שאז הוא ראש השנה לאילנות <b>בפועל</b> (כנ\"ל סל\"ב) – ישנו הענין ד\"ואהבת לרעך כמוך\",\n– הן בנוגע להעזר והסיוע לחבירו באופן ד\"כמוך\", והן בנוגע לכללות עבודתו בקיום המצוות שהיא באופן ד\"ברכנו אבינו כולנו כאחד\"<sup data-n=\"313\">200</sup>, כמודגש גם בכך שלפני עשיית כל מצוה (או בהתחלת התפלה) אומרים \"לשם יחוד . . <b>בשם כל ישראל</b>\" (כמובא בחסידות מספרי קבלה<sup data-n=\"314\">201</sup>), שעי\"ז מתייחד מקיים המצוה עם כל שאר בנ\"י, ובפרט ש\"נכוןלומר קודם התפלה הריני מקבל עלי מ\"ע של ואהבת לרעך כמוך\"<sup data-n=\"315\">202</sup>, שאמירה זו, להיותה קודם התפלה, לפני העסק בתורה, וההתעסקות בכל צרכיו, היא על כללות היום –\nכלומר: גם אם <b>במחשבתו</b> חושב רק אודות <b>עצמו</b>, מ\"מ, כיון <b>שבמעשה בפועל</b> ישנו הענין ד\"ואהבת לרעך כמוך\" – ה\"ז מספיק.\nוע\"ד מ\"ש בספרי<sup data-n=\"316\">203</sup> \"מאבד סלע מתוך ידו ומצאה עני והלך ונתפרנס בה מעלה עליו הכתוב כו'\" – דאף <b>שלא חשב</b> אודות העני, ואדרבה, יתכן <b>שמיצר ודואג</b> על אבידת הסלע, מ\"מ, כיון שבנוגע <b>לעני</b> אין נפק\"מ בדבר, העיקר הוא שהשיג צרכי חיות נפשו <b>בפועל</b> – קיים מצות צדקה.\n<b>לו</b>. ויש להוסיף, ששיטת בית שמאי שלא מספיק המעשה בפועל, אלא צריך לבוא גם במחשבה – היא בהתאם להמעמד ומצב <b>דלעתיד לבוא</b>:\nלעתיד לבוא יהי' בגילוי לא רק מעשה ודיבור, אלא גם המחשבה תהי' בגילוי. ורק בזמן הזה שישנו העלם והסתר – הנה למעלה, שם אלקים הוא מגן ונרתק לשם הוי', ולמטה, הגוף ובשר הוא מגן ונרתק על הנשמה, והמעשה ודיבור הוא מגן ונרתק על המחשבה, שלכן מתגלים רק הדיבור והמעשה.\nוכיון שבזמן הזה מתגלים רק הדיבור והמעשה – לכן, ההלכה היא כבית הלל שנוגע רק המעשה בפועל והדיבור בפועל.\nאבל לעתיד לבוא תהי' הלכה כבית שמאי<sup data-n=\"317\">204</sup> – כי, לעתיד לבוא יהיו בגילוי הן המעשה הן הדיבור והן המחשבה, שיהיו מתאימים כולם כאחד, \"תוכו כברו\"<sup data-n=\"318\">205</sup>, שהפנימיות והחיצוניות יהיו כולא חד – למעלה, כמ\"ש<sup data-n=\"319\">206</sup> \"ביום ההוא יהי' הוי' אחד ושמו אחד\", ובמילא יהי' כן בכל הענינים, עד למטה מטה, בענינים גשמיים, שהגוף לא יהי' מעלים ומסתיר על הנשמה, אלא להיפך, הגוף <b>יסייע</b> להנשמה, ובמילא, גם המחשבה הדיבור והמעשה של האדם יהיו מתאימים כולם כאחד.\nאלא, שלדעת בית שמאי – מדת הדין – נדרש שגם עכשיו תהי' ההלכה כן, ע\"ד המעמד ומצב דלעתיד לבוא.<b>לז</b>. וכיון שהשלימות דראש השנה לאילנות – לא רק בפועל (במעשה ובדיבור), אלא גם בכח (במחשבה) – היא לעתיד לבוא, מובן, שהנתינת-כח על זה היא <b>מיום השבת</b>, כי, יום השבת הוא מעין לעתיד לבוא, \"יום שכולו שבת ומנוחה לחיי העולמים\"<sup data-n=\"320\">207</sup>, ולכן, ביום השבת ישנם \"בכח\" וממנו נמשכים כל הענינים דימות השבוע.\nאלא, שמצד העלם הגלות נוגע לעת-עתה רק המעשה בפועל, ולכן הלכה כבית הלל שחמשה עשר בשבט הוא ראש השנה לאילנות (ובמילא, גם יום השבת שמיני' מתברכין, הוא הסמוך ולפני יום חמשה עשר דוקא); אבל, גם אופן העבודה בזמן הזה מהוה הכנה שממהרת את המעמד ומצב דלעתיד לבוא (אע\"פ שאז תהי' ההלכה באופן אחר, כבית שמאי).\nמעין דוגמא לדבר (שדוקא ע\"י העבודה בזמן הזה באים להמעמד ומצב דלעתיד לבוא) – מצינו גם בנוגע ל\"מן\" (שבפרשת השבוע):\nאע\"פ שה\"מן\" הוא כלחם לענין \"ברכת הזן\", וכן לענין הברכה שלפניו (אלא שנוסח הברכה לא הי' \"המוציא לחם מן הארץ\", כנ\"ל סכ\"ט), מ\"מ, מצינו<sup data-n=\"321\">208</sup> ש\"לא יצאו חובת מצה מן המן . . דבמצה בעינן שיהי' בבל תאכל חמץ<sup data-n=\"322\">209</sup>, וזה ליתא במן\" (שלא הי' יכול להחמיץ), ולכן אפו בנ\"י מצה במדבר מהתבואה שתגרי אוה\"ע היו מוכרין להם&lt;96&gt;, או ממה שהיו זורעין וקוצרין בעצמם<sup data-n=\"323\">210</sup>.\nולכאורה אינו מובן: מכיון שמצה <b>אסורה</b> להיות חמץ, הרי, המצה <b>הכי מובחרת</b> היא כשנעשית מ\"מן\" <b>שאינו יכול</b> להחמיץ?!\nוהביאור בזה:\nלצאת ממצרים – אי אפשר באופן של \"לחם מן השמים\", ללא עבודה ויגיעה; אדרבה, יש צורך \"בעבודה קשה בחומר ובלבנים ובכל עבודה בשדה גו' אשר עבדו בהם בפרך\"<sup data-n=\"324\">211</sup>, וכפירוש הזהר<sup data-n=\"325\">212</sup> \"בעבודה קשה זו קושיא, בחומר דא קל וחומר, ובלבנים דא ליבון הלכה וכו'\" – שלכן, צריכה להיות המצה באופן כזה שרק ע\"י <b>יגיעת נפש ויגיעת בשר</b> אינה באה לידי חימוץ. ובאופן כזה דוקא יוצאים (\"קריכט מען אַרויס\") מהגלות.וע\"ד דברי הגמרא<sup data-n=\"326\">213</sup> \"אדם רוצה בקב שלו מתשעה קבים של חבירו\": ה\"קב שלו\" הוא אמנם מה שמשיג ע\"י העבודה בכח העשי' היותר נמוך, אבל זהו \"<b>שלו</b>\", ולכן, אף שענין זה דורש יגיעה, ויגיעה עצומה, הרי, בו דוקא ישנו רצון ותענוג האדם, ודוקא עי\"ז מגיע הוא ל\"בכל מאדך\" – מאד שלך, שזהו הכלי ל\"מאד\" שלמעלה&lt;124&gt; – שיהי' הגילוי ד\"ונגלה כבוד הוי'\"&lt;149&gt;.\n<b>לח</b>. זוהי איפוא ההוראה מראש השנה לאילנות:\nהעבודה בכח עצמו – שמתחילה מהיציאה ממצב של \"דומם\" למצב של \"צומח\", \"האדם עץ השדה\" – צריכה להיות באופן שבתחילת העבודה יודעים כבר שצריכים לבוא לתכלית העלי': מ\"צומח\" – ל\"חי\", מ\"חי\" – ל\"מדבר\", ומ\"מדבר\" – למעמד ומצב ש\"אתם הדבקים בה' אלקיכם\"&lt;139&gt;, כי, \"בנים אתם לה' אלקיכם\"<sup data-n=\"327\">214</sup>, \"שהבן נמשך ממוח האב . . (ו)הוא וחכמתו אחד\"<sup data-n=\"328\">215</sup>, כך, שהנברא נעשה חד עם הבורא, \"ישראל וקוב\"ה (ע\"י אורייתא) כולא חד\"<sup data-n=\"329\">216</sup>.\nונמצא, שמראש השנה לאילנות, ולפנ\"ז, מיום השבת שמיני' מתברך גם ראש השנה לאילנות – לוקחים את הכח לעבור את כל הדרגות שבעבודה, עד שבאים לההתאחדות דכל ישראל כולם כאחד, שעי\"ז מתאחדים עם קוב\"ה (ע\"י אורייתא) באופן ד\"כולא חד\".\nועי\"ז נפעל גם בעולם ש\"יהי' ה' אחד ושמו אחד\" – כדרשת חז\"ל<sup data-n=\"330\">217</sup> \"אטו האידנא לאו אחד הוא . . לא כעולם הזה העולם הבא, על בשורות טובות אומר ברוך הטוב והמטיב ועל בשורות כו', לעולם הבא <b>כולו הטוב והמטיב</b>\", שאז יהי' יום שכולו טוב ויום שכולו מנוחה.\nוהעיקר – שכש\"יהי' ה' אחד ושמו אחד\" עד למטה מטה, אזי יהי' עיקר שכינה בתחתונים (כמו ש\"עיקר שכינה בתחתונים היתה\"<sup data-n=\"331\">218</sup>, לשון עבר) – דירה לו ית' בתחתונים<sup data-n=\"332\">219</sup>, בגאולה האמיתית והשלימה במהרה ממש.\n[כ\"ק אדמו\"ר שליט\"א צוה לנגן ניגון ה\"בינוני\". ואח\"כ התחיל לנגן הניגון \"אבינו מלכנו\"].\n***<b>לט</b>. כ\"ק מו\"ח אדמו\"ר סיפר<sup data-n=\"333\">220</sup> (וכנראה שמע זה מאביו – כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע):\nבש\"פ בשלח שנת תרכ\"א אמר כ\"ק אדמו\"ר הצמח צדק את המאמר \"ראו כי הוי' נתן לכם השבת\"<sup data-n=\"334\">221</sup> הנדפס בלקו\"ת (בתחלתו, בפרשת בשלח). לאח\"ז קרא הצ\"צ לבנו אדמו\"ר מהר\"ש (זקנו של כ\"ק מו\"ח אדמו\"ר), וסיפר לו, שבש\"פ בשלח שנת תקס\"ה אמר רבינו הזקן זה המאמר, ואח\"כ קרא אותו (את הצ\"צ) וסיפר לו, אשר בשנת תקכ\"ט בהיותו במעזריטש קרא אותו הרב המגיד וסיפר לו: בש\"פ בשלח שנת תקט\"ז אמר הבעש\"ט מאמר ע\"פ<sup data-n=\"335\">222</sup> \"וישב הים לפנות בוקר לאיתנו\", \"אל תיקרי לאיתנו אלא לתנאו\"<sup data-n=\"336\">223</sup>, ובשנת תקכ\"א (שנה אחר הסתלקות הבעש\"ט) – המשיך הרב המגיד לספר לרבינו הזקן – הי' אצלו רבו הבעש\"ט, וחזר את המאמר, והוסיף ביאור בענין \"עושין רצונו של מקום\"<sup data-n=\"337\">224</sup>, \"רצונו\" ולא \"דברו\". ואמר הרב המגיד את המאמר לפני אדמו\"ר הזקן, והוסיף ביאור בענין \"גינאי נהרא כו' חלוק לי מימך\"<sup data-n=\"338\">225</sup>, שזהו כענין קריעת ים סוף.\n– (ואמר כ\"ק אדמו\"ר שליט\"א:) מצאתי מאמר שתוכנו מתאים להמבואר לעיל, וכנראה שזהו המאמר שאודותיו סופר סיפור הנ\"ל. וז\"ל<sup data-n=\"339\">226</sup>:\n\"וישב הים לפנות בוקר לאיתנו, ודרשו רז\"ל לתנאו, שהתנה הקב\"ה שיקרע הים לישראל, ולכאורה אינו מובן, עם מי התנה הקב\"ה, אך הענין הוא, בשעה שאמר המאמר, התנה שיקרע הים, ואם לאו לא היו נמצאים הימים ולא נבראו במקום הזה, כי יתבטלו ממציאות הבריאה, כי כל התורה כולה היא עשה ול\"ת.\nובזה יובן מ\"ש רז\"ל צדיקים עושים רצונו של מקום, ולא אמרו עושים דברו או מאמרו, כי הלוא רצון השם יתברך אינו מושג, אך המשל בזה אב שאומר בפני בנו איזה דבר הלכה או איזה חידוש בתורה, והבן מגודל חריפתו ופלפולו סותר את דבריו, והנה אף שהבן מתנגד לאביו וסותר את דבריו, עכ\"ז יש לאב נחת ותענוג גדול ושמחה גדולה מזה . .וזהו רצון הטוב מן האב יותר משהי' שותק ומסכים לדבריו, כך הוא הצדיק מושל ביראת אלקים<sup data-n=\"340\">227</sup> כביכול (שאני גוזר גזירה והצדיק מבטלה<sup data-n=\"341\">228</sup>). וזהו עושים רצונו אע\"פ שאינם עושים דברו ומאמרו<sup data-n=\"342\">229</sup>.\nובזה יובן מ\"ש רבי פינחס בן יאיר לגינאי נהרא פלוג מימיך שאני הולך לדבר מצוה, אמר לו גם אני הולך לעשות רצון קוני, א\"ל אם אין אתה חולק מימיך גוזרני עליך שלא יעברו בך מים לעולם, ולכאורה קשה, הלא השיב לו תשובה נכונה, ויובן עם מ\"ש לעיל שהתנה הקב\"ה עם מעשה בראשית שיעשו רצון הצדיקים אף שאינם בטבעם, ומכלל הן אתה שומע לאו, וכך אמר לו ר' פינחס בן יאיר אם אין אתה חולק מימיך נמצא שאין אתה מקיים תנאך הנאמר בשעת המאמר, והרי אתה כלא הי' מעולם, וכמו שלא נבראו כאן מים, ונמצא שלא יעברו בך מים לעולם\". עכ\"ל. –\nוסיים הצ\"צ לספר לבנו אדמו\"ר מהר\"ש: היום היו אצלי הבעש\"ט, הרב המגיד ורבינו הזקן, וכל אחד אמר לי המאמר בסגנונו הוא.\nכעבור איזה שעות – כשאדמו\"ר מהר\"ש הספיק בקושי להתאושש (\"ער איז נאָך קוים געקומען צו זיך\")... – שלח הצ\"צ לקרוא לו עוד הפעם, ואמר לפניו ביאור על המאמר.\n<b>מ</b>. והנה, סיפור זה שסיפרו כ\"ק מו\"ח אדמו\"ר, אינו סיפור דברים בעלמא, אלא, ככל סיפור שנשיא מספר למושפעיו שהוא הוראה בעניניהם, בודאי שגם סיפור זה מהוה הוראה שנוגעת לכל אלה ששמעו (או שומעים עכשיו) את הסיפור<sup data-n=\"343\">230</sup>.\nוההוראה בזה:\nיהודי צריך לדעת שישנו תנאי מששת ימי בראשית, שבכל הנוגע לעניני <b>תומ\"צ</b>, צריך ההעלם והסתר שבעניני העולם <b>להבקע</b> (\"דער העלם והסתר דאַרף זיך שפּאַלטן\"), וכמו שבשעה שבנ\"י היו בדרכם <b>לקבלת התורה</b>, הרי, אף שבאמצע הדרך היו מים – \"ידעו\" המים <b>שצריכים להבקע</b>, כדי שבנ\"י יוכלו לילך \"בתוך הים ביבשה\"<sup data-n=\"344\">231</sup>.ולאידך גיסא – אף שהמים \"יודעים\" שצריכים להבקע, הנה הבקיעה <b>בפועל</b> נעשית בבוא נחשון בן עמינדב<sup data-n=\"345\">232</sup> – <b>שאינו יודע</b> אודות תנאי האמור, הוא יודע רק שצריך לצאת ממצרים ולבוא להר סיני, ולפתע רואה שבאמצע הדרך ישנו ים סוף – <b>קופץ לתוך הים</b>, ללא חשבון, מצד <b>מסירת-נפש</b>; ואז \"מרגיש\" <b>הים</b> את התנאי שהותנה עמו מששת ימי בראשית, ומקיים אותו, בידעו שבזה תלוי קיומו.\nוזוהי ההוראה בנוגע לכל ההעלמות והסתרים וכל הקשיים שיש לבנ\"י בעניני תומ\"צ – שאין זה אלא ענין <b>המדומה</b>; הצורך בהעלם והסתר זה אינו אלא כדי לעורר אצל יהודי ענין <b>המס\"נ</b> – שיקפוץ לתוך הים, ואז נעשה הענין ד\"לאיתנו\", \"לתנאו\", התנאי שהתנה הקב\"ה עם מעשה בראשית, ובמילא מתבטל ההעלם והסתר – שנבקע הים, ונחלק הנהר כו'.\n<b>מא</b>. ועוד להוסיף בנוגע לשאר הפרטים שבעובדא ד\"גינאי נהרא כו' חלוק לי מימך\" – \"מאי בהמתן של צדיקים, דרבי פינחס בן יאיר הוה קאזיל לפדיון שבויין, פגע בי' בגינאי נהרא וכו' חלק לי' וכו'. ההוא . . דלווה בהדייהו, אמר לי' (רפב\"י) חלוק לי' נמי להאי, דלא לימא כך עושים לבני לוי', חלק לי'\" – שלא זו בלבד שהנהר נחלק בשביל רבי פינחס בן יאיר, אלא שנחלק גם בשביל \"<b>בני לוי'</b>\", ואפילו בשביל <b>חמורו</b> של רבי פינחס בן יאיר.\nוההוראה מזה בנוגע אלינו:\nמבלי הבט על המעמד ומצב שלנו (\"וואָס מ'איז אַליין\"), הרי, \"<b>בני לוי'</b>\" אנו, שהולכים יחד עם נשיא הדור, כ\"ק מו\"ח אדמו\"ר,\nובמילא, כשם שהוא פועל את הענין ד\"חלוק לי מימך\", שמתבטלים כל ההעלמות והסתרים – כמו כן נבקעים כל הנהרות וכל ההעלמות וההסתרים עבור \"בני לוי'\", באותו אופן שנבקעים לפני רבי פינחס בן יאיר!\nונקודת הענין – שמצד ההבטחה לחסידים שתהי' \"ידם על העליונה\"&lt;49&gt;, בטלים כל ההעלמות וההסתרים, ונפרצת הדרך (\"מ'ברעכט דורך די וועג\") שיוכלו לקבל את התורה בתוספת כח ובתוספת חיזוק על כל השנה כולה.\nועי\"ז נעשה הענין ד\"פדיון שבויין\" (\"דרבי פינחס בן יאיר הוהקאזיל לפדיון שבויין\") – כמבואר<sup data-n=\"346\">233</sup> בענין \"מקבץ נדחי עמו ישראל\", שקאי על ניצוצות הקדושה שנמצאים בשבי' בלעו\"ז, אשר, זוהי כללות עבודתו של כאו\"א מישראל משעה שנולד – לקבץ ולפדות את ניצוצות הקדושה שנפלו למטה ונמצאים בשבי' דלעו\"ז, שזהו\"ע דפדיון שבויים.\nוכאמור, בנוגע לכל ההעלמות וההסתרים שישנם על העבודה ד\"פדיון שבויין\", ישנו התנאי שהותנה מששת ימי בראשית שעליהם להתבטל לא רק בשביל רבי פינחס בן יאיר בעצמו, אלא גם בשביל חמורו של רבי פינחס בן יאיר, וגם בשביל \"בני לוי'\" שלו.\n<b>מב</b>. ונקודת הענין – שיהודי, ע\"י התורה, הוא <b>בעה\"ב</b> על העולם ועל כל עניני העולם.\nובלשון המדרש<sup data-n=\"347\">234</sup> (בנוגע ליעקב אבינו) \"מה הקב\"ה בורא עולמות, אף אביכם בורא עולמות\", וכח זה של יעקב אבינו נמסר גם <b>לכל</b> בנ\"י אחריו, שכל יהודי, ע\"י התורה, נעשה בעה\"ב על כל העולם.\nאלא, שכח זה צריך לנצלו <b>באופן המתאים</b>,\n– וכפי שאמר פעם כ\"ק מו\"ח אדמו\"ר<sup data-n=\"348\">235</sup> שאצל כל יהודי יכול להיות \"רוח-הקודש\", אלא, שצריך לדעת כיצד <b>לנצלו</b>, שלא לנצלו על דברים של מה-בכך (\"אויף כ'ווייס וואָס\") –\nשלא לנצל כח זה בשביל \"זבחי ריב\"<sup data-n=\"349\">236</sup> ו\"מלבושי כבוד\"<sup data-n=\"350\">237</sup> שהם ללא תועלת – כפי שמאריך אדמו\"ר מהר\"ש בהמשך \"מים רבים\"<sup data-n=\"351\">238</sup> בביאור הפסוק<sup data-n=\"352\">239</sup> \"אולת אדם תסלף דרכו\"<sup data-n=\"353\">240</sup>,\nכי אם – בשביל הענין ד\"יש לי כל\"<sup data-n=\"354\">241</sup>, \"דאחיד בשמיא ובארעא\"<sup data-n=\"355\">242</sup>, לקשר ולאחד \"שמים\" ו\"ארץ\", שהרוחניות והגשמיות יהיו אצלו <b>דבר אחד</b>, כלומר, שהצורך שלו בגשמיות אינו אלא כדי שיוכל למלאות הענינים <b>הרוחניים</b> שהוטלו עליו.\nועי\"ז נעשה גם \"יש לי כל\" <b>כפשוטו</b> – שלא חסר אצלו שום דבר,כיון ש\"ברכך הוי' אלקיך בכל אשר תעשה\"<sup data-n=\"356\">243</sup>, היינו, שברכתו של הקב\"ה, שהיא \"עד בלי די\"<sup data-n=\"357\">244</sup>, נמשכת \"<b>בכל</b> אשר תעשה\", מבלי הבט על <b>סוג</b> ה\"כלי\", אם יש לו מקום בטבע ובעולם המסחר, אם לאו – שורה בו ברכתו של הקב\"ה, באופן ד\"עד בלי די\", בבני חיי ומזוני רויחי.\n[כ\"ק אדמו\"ר שליט\"א התחיל לנגן את הניגון \"דרכך אלקינו כו'\".\nצוה לבאי-כח ולבעלי-בתים של \"ערי השדה\" – בנקבו בשמותיהם – לומר \"לחיים\", וליקח בשביל כל העיירה. אח\"כ צוה שמנהלי \"קעמפּ גן ישראל\" יאמרו \"לחיים\".\nבמהלך חלוקת \"לחיים\" צוה כ\"ק אדמו\"ר שליט\"א לא' לנגן ניגון שלו מתוך שמחה (וניגן הנ\"ל \"עזרני א-ל חי\"). אח\"כ ערכו \"שבע ברכות\"].\n***\n<b>מג</b>. לקראת<sup data-n=\"358\">245</sup> י' שבט (שבת שירה) נדפסה שיחה של כ\"ק מו\"ח אדמו\"ר בעל ההילולא<sup data-n=\"359\">246</sup> – שיחה הקשורה עם שבת שירה.\nבשיחה זו מסופר אודות אשה בישראל ופעולותי', וע\"י סיפור זה תירץ אדמו\"ר הצמח-צדק בשם רבינו הזקן את השאלה על כך שההפטורה של שבת שירה היא \"ותשר דבורה\"<sup data-n=\"360\">247</sup> דוקא, שירת אשה, ולא שירת דוד, כמו ההפטורה של שביעי של פסח<sup data-n=\"361\">248</sup>:\nדלכאורה, כיון שבפרשת בשלח מסופר הן ע\"ד שירת <b>האנשים</b>, \"אז ישיר משה גו'\"<sup data-n=\"362\">249</sup>, והן ע\"ד שירת הנשים, \"ותקח מרים הנביאה גו' ותצאן כל הנשים אחרי' בתופים ובמחולות\"<sup data-n=\"363\">250</sup> – מדוע ההפטורה של פרשת בשלח היא בשירת <b>אשה</b> דוקא, \"ותשר דבורה\"?\nוביאר אדמו\"ר הצ\"צ – כאמור בשם רבינו הזקן נ\"ע – שזהו לפי ששירת הנשים היתה בשמחה גדולה, \"בתופים ובמחולות\", ולכן, ה\"ז נוגע יותר, והכל תלוי בהן (לפי ש\"הכל הי' מן העפר\"<sup data-n=\"364\">251</sup>, ספירתהמלכות). וכן הוא בכללות הנהגת הבית – שכל אופן ההנהגה בבית תלוי <b>באשה היהודי'</b><sup data-n=\"365\">252</sup>, \"עקרת הבית\"<sup data-n=\"366\">253</sup>, כולל גם בנוגע להבא לקמן.\n<b>מד</b>. דובר לעיל<sup data-n=\"367\">254</sup> בשם אדמו\"ר מהר\"ש נ\"ע אודות הענין ד\"אולת אדם תסלף דרכו\", שכאשר האדם מתמסר לחפש \"לוקסוס\" – מותרות – דברים שאינו מוכרח אליהם, אזי מפסיד הוא את שניהם, כי, עי\"ז שמתמסר לחפש מותרות, נעשה מבולבל בדעתו, ולא זו בלבד שאין לו המותרות, אלא שמאבד גם הדברים המוכרחים.\nמשא\"כ כשמונח אצלו ש\"וברכך <b>ה' אלקיך</b> בכל אשר תעשה\", ובמילא, אינו מחפש מותרות, אלא מתמסר ללימוד התורה וקיום המצוות, בידעו שזהו <b>העיקר</b>, וכל התעסקותו בפרנסה היא רק בתור עשיית \"<b>כלי</b>\" להשפעת הפרנסה (מלמעלה), כדי להרויח את הזקוק לו, כדי שיוכל להתמסר לתומ\"צ – אזי, הפרנסה שהקב\"ה שולח לו הולכת בשביל דברים בריאים ושמחים (כנ\"ל סי\"ז). הכסף אינו הולך, רח\"ל, בשביל רפואות ורופאים, או כדי לסלק מניעות אחרות, כי מלכתחילה אין לו מניעות אלו, כמ\"ש<sup data-n=\"368\">255</sup> \"כל המחלה גו' לא אשים עליך כי אני ה' רופאך\", היינו, שהקב\"ה עוזר שמלכתחילה אינו חולה, ובמילא, יתכן אמנם שיש לו עשר דולר פחות מהזקוק בשביל רופא, מדוע? – לפי שהוא <b>אינו זקוק</b> לרופא<sup data-n=\"369\">256</sup>.\nזאת ועוד: כאשר האדם אינו מחפש מותרות, בידעו שהברכה באה <b>מהקב\"ה</b>, וצריך רק לעשות \"כלי\" ולסמוך על הקב\"ה שהוא כל יכול – אזי, אפילו כאשר עושים \"כלי\" קטן, משפיע הקב\"ה לתוכו הצלחה מופלגה (\"אומגעהויערע הצלחה\") ביחד עם עשירות גדולה, פשוט עשירות בגשמיות.\n– אין צורך לרדוף אחרי עשירות ומותרות; אבל כאשר אין רודפים אחריהם, מצד הידיעה וההכרה שהעיקר הוא רוחניות, והגשמיות דרושה רק במדה כזו כדי שיוכלו לקיים תומ\"צ – אזי נותן הקב\"ה \"מידו המלאה והרחבה\", עשירות מופלגה, גם בגשמיות.\n<b>מה</b>. וענין זה – שלא לרדוף אחרי מותרות – תלוי ב\"עקרת הבית\"<sup data-n=\"369\">256</sup>:כאשר האשה נותנת לבעלה להבין שהעיקר הוא <b>הרוחניות</b> של הבית, לא הגשמיות, וממילא אינו צריך להיות טרוד (\"פאַריאָגט\") יומם ולילה בפרנסה, באופן שלא יהי' לו פנאי בשביל לימוד התורה וההתעסקות בעניני הכלל, כיון שרודף (\"ער יאָגט זיך\") להרויח עוד דולר ועוד דולר בשביל עניני מותרות;\nנוסף לכך היא מסבירה לו, שהרדיפה אחרי פרנסה אינה יכולה להועיל לו מאומה, שכן, מכיון ש\"מזונותיו של אדם קצובים לו מראש השנה ועד יום הכיפורים וכו'\"<sup data-n=\"370\">257</sup>, הרי כבר נקבע מלמעלה כמה הוא ירויח בפרנסתו, ויותר מזה לא ירויח בשום אופן, ולאידך, כדי להשיג את הפרנסה שהוקבעה בשבילו מלמעלה, יכול לעשות גם \"כלי\" קטן, ללא ריבוי טרדות ותחבולות,\nוכיון שכן – לשם מה צריך לרדוף ביגיעה רבה אחרי פרנסתו, ואז ישנו הצורך להבטיח (\"באַוואָרענען\") לא רק \"יברכך<sup data-n=\"371\">258</sup> בנכסים\", אלא גם \"וישמרך מן המזיקים\"<sup data-n=\"372\">259</sup> – הרי טוב יותר לסמוך על הקב\"ה, \"ברכת ה' היא תעשיר\"<sup data-n=\"373\">260</sup>, שאז מובטחים (\"מען איז באַוואָרנט\") בכל הענינים;\nהנה בשעה שהבעל שומע את הטענות האמורות מאשתו – הרי אפילו באם המותרות תופסים מקום אצלו, מ\"מ, ה\"ז פועל עליו שמתבייש מאשתו, ושוב אינו מתפעל מהשכן או השכנה להקפיד על עשיית כלי בית (\"פוירניטשור\") מהודרים דוקא, ושה\"וילון\" (מסך מעלים ומסתיר) על גבי החלון שבביתו יהי' יפה יותר מה\"וילון\" של השכנה,\nוכתוצאה מזה מפסיק הוא לבזבז כחות וכסף ובלבד לפעול שיהי' \"מרבה<sup data-n=\"374\">261</sup> נכסים מרבה דאגה\"<sup data-n=\"375\">262</sup>, אלא מתחיל לומר \"יש לי <b>כל</b>\" (\"כל בשמים ובארץ\"<sup data-n=\"376\">263</sup>, \"דאחיד בשמיא ובארעא\"), שמאחד גשמיות ורוחניות, ועושה מביתו \"מקדש\" בשביל הקב\"ה, ובמילא, מפסיק לרדוף יומם ולילה אחרי פרנסה, אלא עושה \"כלי\" בשביל ברכתו של הקב\"ה, וקובע עתים בשביל לימוד התורה, וסומך על הקב\"ה,ואז – \"ברכת ה' היא תעשיר\", ולא זו בלבד שהכסף אינו הולך בשביל רפואות וכו', אלא יש לו פרנסה בהרחבה, והכסף מספיק לו בשביל פרנסה בהרחבה ובשביל נתינת צדקה ביד פתוחה ולב שמח, והוא ואשתו ובני ביתו מאושרים.\n<b>מו</b>. וכן הוא גם בנוגע לחינוך הבנים והבנות:\nעיקר התמסרותם של ההורים צריך להיות בנוגע לחינוך הילדים בדרך התומ\"צ, כדי להבטיח שהילדים יגדלו להיות חסידים, יראי שמים ולומדים, שעי\"ז מביאים אושר נצחי להילדים וכן לההורים.\nאבל כאשר מתמסרים לקשט (\"פאַרפּוצן\") את הילד במלבושים יקרים, כדי שהילד שלו ילך לבוש בבגדים יפים יותר מילדיהם של השכנים, הרי, אושר כזה יכול להמשך ליום, שבוע, חודש, שנה, אבל לאח\"ז, כאשר הילד יגדל, רואים (\"כאַפּט מען זיך\") שהחסירו להעניק אליו את האושר האמיתי, שעל ידו הי' מאושר במשך כל ימי חייו.\nוגם ענין זה תלוי באשה היהודית, שכן, להיותה עקרת הבית, יש בכחה דוקא לקבוע אופן חינוך הבנים והבנות, כמו הנהגת כל הבית כולו, שיהי' בית מאושר ברוחניות, ובמילא, בית מאושר בגשמיות<sup data-n=\"377\">264</sup>.\n<b>מז</b>. ענין האמור מודגש במיוחד בפרשת השבוע שנכנסים אלי' עתה – פרשת יתרו:\nכאשר הקב\"ה נתן את התורה לבנ\"י אמר למשה רבינו \"כה תאמר לבית יעקב\"<sup data-n=\"378\">265</sup>, \"אלו <b>הנשים</b>\"<sup data-n=\"379\">266</sup>, כלומר, לכל לראש נצטווה משה לילך לנשי ישראל ולדבר עמהן כיצד צריכה אשה בישראל להתנהג ע\"פ תורה, <b>שעי\"ז</b> נעשים מובטחים גם בנוגע להנהגתם של <b>האנשים</b>.\nוכמו כן הוא בכל שנה ובכל זמן ובכל מקום – ש\"בית יעקב\", נשי ישראל, מקבלות על עצמן בכל התוקף לקבוע את בתיהן לעשות מהם מקדש בשביל הקב\"ה, כמ\"ש<sup data-n=\"380\">267</sup> \"ועשו לי מקדש ושכנתי בתוכם\", ואזי מעניק הקב\"ה<sup data-n=\"381\">268</sup> אושר בבית, אושר בגשמיות ואושר ברוחניות, ומחנכים את הילדים לתורה, חופה ומעשים טובים, מתוך הרחבה, הן הרחבה בגשמיות והן הרחבה ברוחניות.[כ\"ק אדמו\"ר שליט\"א צוה לכו\"כ אנשים פרטיים – בנקבו בשמותיהם – לומר \"לחיים\".\nאח\"כ צוה לנגן ניגון מאדמו\"ר הצ\"צ (וניגנו \"ימין ה' גו'\"). ניגון הכנה, ניגון ד' הבבות לרבינו הזקן (בבא הרביעית – פעם אחת), \"ניע זשוריצי כלאָפּצי\".\nואח\"כ אמר:]\nכדאי ונכון ש\"ועד המסדר\" יכריז אודות ברכה אחרונה (כדאיתא בספרים<sup data-n=\"382\">269</sup>).\n***\n<b>מח</b>. על הפסוק \"וישמע יתרו גו'\" – בהתחלת הפרשה דשבוע הבא – פירש רש\"י (ומקורו בגמרא ובמדרש<sup data-n=\"383\">270</sup>): \"מה שמועה שמע ובא . . מלחמת עמלק\", שזהו טעם סמיכות הפרשיות: \"וישמע יתרו גו'\" עם \"מלחמה לה' בעמלק מדר דר\"<sup data-n=\"384\">271</sup>.\nוזוהי התחלת הפרשה דמתן תורה, היינו, שהדרך למתן תורה – שבאה על ידי הודאת יתרו, כדאיתא בזהר<sup data-n=\"385\">272</sup> – היא על ידי ההקדמה ד\"מלחמת עמלק\", שעי\"ז נסללה הדרך ללמוד אפילו ל\"כהן מדין\" לעזוב ארצו ונחלתו, לבוא למדבר, ולקבל שם תורה נצחית, על כל הדורות ועל כל המקומות.\nוגם ענין זה מהוה הוראה נצחית עד לדורות האחרונים בעקבתא דמשיחא, כדלקמן.\n<b>מט</b>. וביאור הענין:\nאיתא בחסידות<sup data-n=\"386\">273</sup> ש\"עמלק\" בגימטריא \"ספק\". ועל זה נאמר<sup data-n=\"387\">274</sup> \"ראשית גויים עמלק\", כי, ה\"ספק\" הוא הראשית וההתחלה לכל ענינים המבלבלים.\nוזוהי ההוראה הכללית מהקדמת מלחמת עמלק למתן תורה – כולל גם מתן תורה שבכל יום, כמרומז בנוסח ברכת התורה: \"נותן התורה\",לשון הוה<sup data-n=\"388\">275</sup> – שכאשר מתעורר אצל יהודי איזה ספק בנוגע לעניני תומ\"צ ועניני אלקות, צריך <b>לבטל</b> את הספק (כדלקמן בפרטיות), ואז יוכל – מתוך מנוחת הנפש – ללמוד תורה ולקיים מצוות, אשר, עי\"ז מתקיימת גם הבטחתו של הקב\"ה (שהיא גם בקשה ונתינת כח) \"אם (\"אין אם אלא לשון תחנונים\"<sup data-n=\"389\">276</sup>, שהקב\"ה <b>מתחנן</b>) בחוקותי תלכו ואת מצוותי תשמרו גו' ונתתי גשמיכם בעתם ונתנה הארץ יבולה ועץ השדה יתן פריו\"<sup data-n=\"390\">277</sup>, עם כל שאר הברכות המנויות בפרשה.\n<b>נ</b>. והדרך לבטל את הספק (שזהו תוכן הענין דמלחמת עמלק) – נלמדת מהמסופר בסיום פרשתנו אודות פרטי הענינים דמלחמת עמלק.\nולכל לראש – \"ויאמר משה ליהושע בחר לנו אנשים וגו'\"<sup data-n=\"391\">278</sup>:\nאדמו\"ר הזקן מבאר<sup data-n=\"392\">279</sup> ש\"לכבוש מלחמת עמלק צריכים <b>אנשי משה</b> דוקא\".\n\"אנשי משה\" – הם אנשים שקשורים עם נשיא הדור, אתפשטותא דמשה שבכל דרא ודרא<sup data-n=\"393\">280</sup>, ובדורנו – כ\"ק מו\"ח אדמו\"ר נשיא הדור, ועל ידו – עם הנשיאים שלפניו, עד לרבינו הזקן, הבעש\"ט, ואחי' השילוני, ולמעלה יותר, עד לעצמות ומהות א\"ס ב\"ה; ובאם רוצים ישנה דרך קצרה יותר – ע\"י נשיא הדור, מה\"עצם\" שלו לעצמות ומהות למעלה.\nואז – כשישנם \"אנשי משה\" – בא הציווי \"צא הלחם בעמלק\",\nועל ידם נעשה הנצחון במלחמה באופן ש\"ויחלוש . . את עמלק ואת עמו לפי חרב\"<sup data-n=\"394\">281</sup>.\n<b>נא</b>. ולימוד נוסף – מהנצחון במלחמת עמלק באופן ד\"<b>ויחלוש</b>\":\nמצינו במדרשי חז\"ל<sup data-n=\"395\">282</sup> בפירוש \"ויחלוש\", שלא הרגם, אלא רק החלישם – לפי שעמלק מכשף הי', ובחר לו אנשים שראה במזל שלהם שאינם עתידין למות באותה מלחמה, לכך לא הי' יהושע יכול להרגם אלא רק להחלישם. וגם זה הי' מספיק לפעול את הענין ד\"וישמע יתרו\", שהביא אח\"כ למתן תורה.וההוראה מזה בנוגע לעמלק בגימטריא ספק – שגם במצב שאינו יכול לבטל את הספק (לתרצו כו') מכל וכל, יכול וצריך הוא <b>להחלישו</b> שלא יוכל לבלבלו בעבודתו לבוראו – עי\"ז <b>שדוחה</b> הספק ואינו שם לבו אליו, ובודאי שאינו נכנס לשקו\"ט כו', ואז יכול הוא כבר לילך לקבלת התורה, החל מאמירת \"נעשה ונשמע\", שעי\"ז נעשית קבלת התורה עד סוף כל הדורות.\nובאותיות פשוטות:\nכשמתעורר ספק אצל יהודי בנוגע לעניני תומ\"צ ועניני אלקות, הרי אחת מהשתים: אם ביכלתו לתרץ את הספק – מה טוב; ואם אינו יכול לתרצו – אין לו להתעסק בזה כלל.\nעליו לענות, שאין לו פנאי להכניס עצמו ב\"שקלא וטריא\", שכן, \"אני נבראתי לשמש את קוני\"&lt;190&gt;, ובמילא, אינו בעל-הבית על עצמו כלל, אלא הוא <b>עבד המלך</b>, וצריך לקיים את התפקיד והשליחות שהוטלה עליו – לימוד התורה וקיום המצוות!\nאלא מאי, ישנם ספיקות שאלות וקושיות – הנה כאשר יהי' לו זמן פנוי (אם אכן יהי' לו פעם...) אזי יתעסק בענינים אלו, אבל, לעת עתה, יש לו שיעור בלימוד התורה, ולאח\"ז צריך לנצל את הזמן בשביל קיום המצוות, ולאח\"ז יש לו שיעור נוסף בלימוד התורה, כך, שעסוק הוא (\"ער איז אַ פאַרנומענער מענטש\") \"מן בקר עד ערב\"<sup data-n=\"396\">283</sup>, וגם לאח\"ז – כמבואר בהמשך תרס\"ו<sup data-n=\"397\">284</sup> – אפילו בשעה <b>שישן</b>, הרי אימת ועול אדונו עליו, להיותו עבדו של מלך מלכי המלכים הקב\"ה!\nונקודת ההוראה – שהענין שנוגע במלחמה זו הוא לא <b>ביטול הספקות</b>, אלא <b>לדחותם</b> ולהשליכם (\"אַרויס-וואַרפן זיי\") מגבול ישראל, באופן <b>שלא יבלבלו</b> לקיום התומ\"צ, שזהו תוכן הענין ד\"ויחלוש\".\nועוד וג\"ז עיקר – שע\"י <b>דחייתם</b> באופן שלא יבלבלו לקיום התומ\"צ (\"ויחלוש\"), <b>מתבטלת מציאותם לגמרי</b>, כי, מציאותם לא נעשית אלא כדי <b>לנסות</b> את בנ\"י<sup data-n=\"398\">285</sup>, וא\"כ, כשהאדם משליך את הספיקות מחוץ לד' אמותיו, מתבטלת סיבת קיומם (\"זיי האָבן מערניט וואָס צו טאָן\"), ובמילא מתבטלת מציאותם.וענין זה מרומז במ\"ש \"ויחלוש גו' לפי חרב\" – שפעולת החלישות כשלעצמה מביאה ביטול מציאותו של עמלק, שזוהי פעולת ה\"חרב\", שרומזת גם על שם הוי', כדאיתא בזהר ובתיקוני זהר<sup data-n=\"399\">286</sup> שראש החרב הוא אות יו\"ד וכו'.\nוכיון שמספיק הענין ד\"ויחלוש\" בלבד, מובן, שענין זה יכול להיות גם בזמן הגלות, במעמד ומצב ד\"אנכי הסתר אסתיר פני ביום ההוא\"<sup data-n=\"400\">287</sup> – שגם אז בכחו של יהודי להתייצב בתוקף המתאים שלא להתעסק כלל עם ענין הספיקות וכו'.\n<b>נב</b>. ועי\"ז נעשה \"וישמע יתרו כהן מדין גו'\" – שאפילו ב\"<b>מדין</b>\" שומעים (\"דערהערט מען\") אודות הענין דמלחמת עמלק ונצחון עמלק,\nואז הולכים לקבלת התורה ופועלים הענין דמתן תורה, ומתוך שמחה.\nובאופן ש\"וירד ה' על הר סיני\"<sup data-n=\"401\">288</sup>, \"ואל משה אמר עלה אל ה'\"<sup data-n=\"402\">289</sup> – שזהו\"ע \"דאחיד בשמיא ובארעא\", \"כל בשמים ובארץ\", היינו, שפועלים את החיבור והאיחוד דרוחניות וגשמיות יחדיו,\nועי\"ז ממשיכים בהגשמיות המשכת האור והחיות של הרוחניות, ונעשית שנה טובה ומבורכה, בבני חיי ומזוני רויחי.\n(וסיים כ\"ק אדמו\"ר שליט\"א:)\n\"אַ גוט יום-טוב\", ושניפגש יחדיו בהתוועדויות חסידותיות, מתוך שמחה והרחבת הדעת.\n**********",[["113","*","ההתוועדות נערכה באולם \"בילטמאָר\"."],["114","1","ירושלמי שקלים פ\"ב ה\"ה – לגירסת שו\"ת הריב\"ש סתכ\"א. וראה ב\"ר פפ\"ב, יא ובעץ יוסף שם."],["115","2","ה, ב. – נתבאר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261007\" data-slug=\"likkutei-sichot\" data-id=\"1300261007\">לקו\"ש חכ\"ו ע' 7</a> ואילך. חל\"ה ע' 223 ואילך."],["116","3","ב\"מ פד, א. ב\"ב נח, א."],["117","4","ראה תניא אגה\"ק ס\"ז."],["118","5","ויק\"ר פל\"ו, ה. פרש\"י ויחי מז, לא."],["119","6","פרש\"י ר\"פ נח. וראה ב\"ר פ\"ל, ו."],["120","7","סוטה מו, סע\"א."],["121","8","שבת פח, סע\"ב ואילך."],["122","9","תהלים ח, ב."],["123","10","תענית שם. פרש\"י ויחי מט, לג."],["124","11","תענית שם."],["125","12","הוריות ו, א."],["126","13","ככר לאדן (להחיד\"א) ס\"ז בפי' המשנה (אבות פ\"ב מ\"ד) אל תפרוש מן הצבור. דברים אחדים (להנ\"ל) דרוש כב (שבת הגדול) קטו, ג. קה\"י ערך שליח ציבור (השני)."],["127","14","ע\"פ שמואל-ב יד, יד."],["128","15","<a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא ספל\"ט</a>. וראה הל' ת\"ת לאדה\"ז פ\"ד סה\"ג."],["129","16","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061054\" data-slug=\"likkutei-sichot\" data-id=\"1300061054\">לקו\"ש ח\"ו ע' 54</a>."],["130","17","שמו\"ר פ\"ב, ב."],["131","18","<a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא רפמ\"ב</a>."],["132","19","ר\"ה כה, א."],["133","20","תהלים עח, עא."],["134","21","בהבא לקמן – ראה גם מכתב כ\"ח שבט שנה זו (אג\"ק חי\"ד ע' שצב): \"על פי המדובר בהתועדות יום ההילולא כו'\"."],["135","22","לטאו\"ח ס\"ש (משבלי הלקט)."],["136","23","להעיר, שבדרך-כלל מביא הב\"י ענינים מגמרא ומראשונים, ואילו כאן מביא מסידורים."],["137","24","אלי' רבה או\"ח שם אות ב (ממטה משה)."],["138","25","ב\"ר פכ\"ח, ג. ויק\"ר פי\"ח, א. תוד\"ה והוא (ב\"ק טז, ב). זח\"א סט, א. קכו, סע\"א (מהנ\"ע). זח\"ב כח, ב. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181257\" data-slug=\"likkutei-sichot\" data-id=\"1300181257\">לקו\"ש חי\"ח ע' 248</a>. וש\"נ. וראה גם \"רשימות\" חוברת ז ע' 14 ואילך."],["139","26","יחזקאל לז, ז-ח."],["140","27","לשון הכתוב – בראשית ג, כב."],["141","28","בשילוב עם שיחת מוצש\"ק פ' צו, אור לי\"ג ניסן תשכ\"ו."],["142","29","ישעי' כו, יט."],["143","30","ראה תניא אגה\"ק סז\"ך וכח. סידור (עם דא\"ח) שער הל\"ג בעומר (דש, סע\"ב ואילך)."],["144","31","או\"ח סו\"ס שמג."],["145","32","ראה גם אג\"ק ח\"ז ע' שנז."],["146","33","הל' שגגות פ\"ט ה\"ג. וראה גם הל' איסורי ביאה פ\"ג הי\"ז. הל' נדרים פי\"א ה\"ד."],["147","34","תנחומא קרח ג (בסופו). פרש\"י קרח טז, כז."],["148","35","ב, רע\"א."],["149","36","\"בע\"ח שכ\"ד\" (לקו\"ת שם)."],["150","37","קנו, א."],["151","38","אבות ספ\"ה."],["152","39","תהלים פד, ח."],["153","40","ברכות ומו\"ק בסופן."],["154","41","ברכות מח, ב. וש\"נ."],["155","42","סה\"ש תרפ\"ז ע' 3-132."],["156","43","שבועות לו, א. וראה מגילה לב, א."],["157","44","לשון הכתוב – ישעי' מט, יז."],["158","45","ולהעיר ממש\"נ (קהלת ז, א. וראה קה\"ר שם) \"טוב גו' יום המוות מיום הוולדו\", שבזה מרומז גם שהשלימות דיום ההסתלקות נלקחת ובאה \"מיום הוולדו\"."],["159","46","רמ\"ז בס' תיקון שובבים. הובא ונתבאר בספר לב דוד (להחיד\"א) פכ\"ט. וראה תו\"מ חי\"ח ע' 330. וש\"נ."],["160","47","אסתר ט, כח."],["161","48","תניא אגה\"ק ס\"ט."],["162","49","אג\"ק אדמו\"ר מוהריי\"צ ח\"ד ס\"ע רסד ואילך. וש\"נ."],["163","50","תהלים קיח, ה. וראה סה\"מ עת\"ר בתחלתו. ועוד."],["164","51","ישיבות שנתייסדו לאחרונה. ראה מכתב י\"ד טבת; ז' אד\"ר שנה זו (אג\"ק חי\"ד ע' עדר; ע' תיג) – בנוגע לטורונטו. שיחת ש\"פ נח סי\"ז; מוצש\"ק פ' וישב, כ\"ף כסלו סמ\"ד (תו\"מ חי\"ח ס\"ע 191; ע' 290) – בנוגע לנואַרק (<b>המו\"ל</b>)."],["165","52","יש לציין שהקביעות דיום ההילולא ביום השבת (כבפעם הראשונה בשנת תש\"י) היתה בשנה זו (תשי\"ז) <b>לראשונה</b> (<b>המו\"ל</b>)."],["166","53","ראה גם אג\"ק ח\"ח ע' קכה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191132\" data-slug=\"likkutei-sichot\" data-id=\"1300191132\">לקו\"ש חי\"ט ע' 132</a>. וש\"נ."],["167","54","ב\"י יו\"ד סו\"ס תג. רמ\"א שם סשע\"ו ס\"ד. סו\"ס תב."],["168","55","או\"ח סתקס\"ח ס\"ט."],["169","56","ראה ס' גשר החיים ח\"א פל\"ב ס\"ז."],["170","57","שו\"ת חת\"ס או\"ח סי' קסב. ספרים שהובאו בשד\"ח אסיפת דינים מערכת אבילות ס\"ק צו; כף החיים או\"ח שם ס\"ק צד."],["171","58","מהר\"ם מינץ ס\"ט. לקט יושר ע' 98."],["172","59","אבל להעיר שמצינו לפעמים שתענית מהני גם לאחר המעשה – אם קיבלו ההחלטה מקודם: \"עיר שהקיפוה עכו\"ם . . אינם רשאים להתענות שלא לשבר כוחם, אלא יקבלו עליהם להתענות . . לכשינצלו כו'\" (שו\"ע שם סתקע\"א ס\"ג)."],["173","60","ראה ס' כל בו על הלכות אבילות (להרב גרינוואַלד) ע' שצ."],["174","61","עיקרי הד\"ט יו\"ד סי' לו אות לה. ועוד. – הובאו בשד\"ח וכף החיים שם."],["175","62","מגילה ה, א."],["176","63","דאף שהלימוד מצד עצמו הי' יכול להיות גם ביום השבת, מ\"מ, מצד <b>התפלות והבקשות</b> שלאחרי סדר הלימוד (שאינם יכולים להיות בשבת), צריך להשתנות גם זמן הלימוד."],["177","64","בשד\"ח שם."],["178","65","בראשית ג."],["179","66","ראה גם מכתב א' שבט שנה זו (אג\"ק חי\"ד ע' שכד)."],["180","67","שהרי ההסתלקות היתה ביום הש\"ק, והקבורה – ביום ראשון."],["181","68","מובא בשד\"ח שם ס\"ק צד."],["182","69","ראה שו\"ע או\"ח סתקס\"ח ס\"ח; רמ\"א סו\"ס תב, ובנ\"כ שם."],["183","70","מובא בכף החיים שם ס\"ק צה."],["184","71","\"היום יום\" יג שבט. ספר המנהגים חב\"ד ע' 79. וראה \"רשימות\" חוברת ה (יומן ב) ע' 10, ובהנסמן שם בהערה 53."],["185","72","ראה שער הכוונות ענין ליל ו' וענין טבילת ע\"ש. פע\"ח שער השבת פ\"ג. מ\"ח מס' תוספות שבת בתחלתה. סהמ\"צ להצ\"צ מצות לא תבערו אש (דרמ\"צ צ, א)."],["186","73","שער הגלגולים הקדמה כג. ועוד."],["187","74","שו\"ע אדה\"ז או\"ח סרע\"א ס\"ב."],["188","75","מהרא\"י בת\"ה ס\"א – הובא בב\"ח או\"ח סרס\"א."],["189","76","שו\"ע אדה\"ז שם סתע\"ב ס\"ב."],["190","77","שם סתרל\"ט ס\"כ."],["191","78","ראה ב\"ח לטאו\"ח ר\"ס תעב (\"כ\"כ מהר\"ל מפּראַג ז\"ל ודבריו נכונים\"). וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191058\" data-slug=\"likkutei-sichot\" data-id=\"1300191058\">לקו\"ש חי\"ט ע' 58</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111201\" data-slug=\"likkutei-sichot\" data-id=\"1300111201\">תו\"מ חי\"א ע' 194</a> ואילך. וש\"נ."],["192","79","יתרו כ, ח. שו\"ע אדה\"ז שם ר\"ס רעא."],["193","80","שם סרפ\"ט ס\"ב."],["194","81","שם סרע\"א סט\"ז."],["195","82","בא יב, ח."],["196","83","בשלח טז, ה."],["197","84","ב\"ר פי\"א, ב. וראה פרש\"י בראשית ב, ג. יתרו כ, יא."],["198","85","בשלח טז, יב."],["199","86","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161173\" data-slug=\"likkutei-sichot\" data-id=\"1300161173\">ח\"ב</a> פח, א (ועד\"ז בפרשתנו סג, ב). וראה גם הנסמן בלקו\"ש חט\"ז ע' 173."],["200","87","ראה אג\"ק אדמו\"ר מוהרש\"ב ח\"א ע' קלט. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161178\" data-slug=\"likkutei-sichot\" data-id=\"1300161178\">לקו\"ש שם ע' 178</a> הערה 38. וש\"נ."],["201","88","בשלח טז, ד."],["202","89","נדה לא, א."],["203","90","ראה זח\"ג סז, רע\"ב. הנסמן בסה\"מ מלוקט ח\"ב ע' רסו הערה 16."],["204","91","ראה פי' האוה\"ח ר\"פ צו."],["205","92","אבות פ\"ו מ\"ב."],["206","93","סה\"ש תרפ\"ז ע' 169. וש\"נ."],["207","94","ראה גם תו\"מ חי\"ח ע' 328. וש\"נ."],["208","95","יתרו כ, יו\"ד. ועוד."],["209","96","ראה יומא עה, ב."],["210","97","ראה גם תו\"מ חט\"ז ריש ע' 133. וש\"נ."],["211","98","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380127\" data-slug=\"likkutei-torah\" data-id=\"4001380127\">לקו\"ת צו יב, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381012\" data-slug=\"likkutei-torah\" data-id=\"4001381012\">האזינו עב, ב</a>. ובכ\"מ."],["212","99","זח\"ג קכד, ב (ברע\"מ). הובא בתניא אגה\"ק רסכ\"ו."],["213","100","פ\"ג (לעיל ס\"ע 8 ואילך)."],["214","101","תהלים כז, ד."],["215","102","בשלח א, ד."],["216","103","חגיגה טו, ב."],["217","104","פרק יב."],["218","105","\"בהקדמה לפי' איוב\" (אגה\"ת שם)."],["219","106","לקו\"ת שם, ג."],["220","107","ואתחנן ד, ו."],["221","108","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>."],["222","109","ראה סה\"מ תרס\"ג ע' כד ואילך. המשך תרס\"ו ע' 53 ואילך. ועוד."],["223","110","ראה מו\"נ ח\"א פע\"ב."],["224","111","ח\"ג קנב, א."],["225","112","מו\"נ ח\"א רפמ\"ט. וראה תניא אגה\"ק ס\"כ (קכט, ב)."],["226","113","ירושלמי שבת ספ\"ו. דב\"ר פ\"א, יב. פרש\"י בלק כג, כג."],["227","114","ראה גם תו\"מ חי\"ח ע' 314. וש\"נ."],["228","115","תקו\"ז בהקדמה (ג, סע\"ב). הובא בתניא אגה\"ק רס\"כ."],["229","116","קו\"א ד\"ה להבין מ\"ש בפע\"ח (קנה, סע\"ב ואילך)."],["230","117","קידושין מ, ב. וש\"נ."],["231","118","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">תניא פל\"ח</a>."],["232","119","באגה\"ק הידועה – נדפסה בכש\"ט בתחלתו. ובכ\"מ."],["233","120","ברכות יו\"ד, סע\"א."],["234","121","תנחומא נשא יא. במדב\"ר פי\"ב, ג."],["235","122","המשך באתי לגני ה'שי\"ת פ\"ב (סה\"מ תש\"י ע' 113)."],["236","123","ואתחנן ו, ה."],["237","124","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370180\" data-slug=\"torah-or\" data-id=\"3901370180\">תו\"א מקץ לט, ד</a>. ובכ\"מ."],["238","125","פ\"ב (לעיל ריש ע' 8)."],["239","126","פסחים ג, ב. וש\"נ."],["240","127","ראה גם לקו\"ת בשלח שם, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201088\" data-slug=\"likkutei-sichot\" data-id=\"1300201088\">לקו\"ש ח\"כ ע' 88</a> הערה 17. וש\"נ."],["241","128","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380527\" data-slug=\"likkutei-torah\" data-id=\"4001380527\">ב\"ר פ\"ד, ד</a>. וראה לקו\"ת קרח נג, ב ואילך."],["242","129","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, א</a>)."],["243","130","ראה סה\"ש תש\"ח ע' 259. וראה גם תו\"מ ח\"א ע' 190. וש\"נ."],["244","131","ראה תניא אגה\"ק ס\"ד."],["245","132","פא, א."],["246","133","יחזקאל יח, ט."],["247","134","שם, ו."],["248","135","אחרי יח, כד."],["249","136","פסוק שמדבר אודות ענינים בלתי- רצויים, שלכן, אין רצוני לסיים את הפסוק."],["250","137","כד, א."],["251","138","תהלים טו, ה."],["252","139","ואתחנן ד, ד. וראה אבות דר\"נ ספל\"ד."],["253","140","ע\"ז ג, סע\"א. וראה המשך באתי לגני שבהערה 122."],["254","141","ראה שבלי הלקט בראש הספר (בשם רבי ישעי' מטראני). הקדמת החוות דעת לפירושו לשו\"ע יו\"ד. המשך תרס\"ו ע' ת. וכבר נאספו המ\"מ בכמה ספרים."],["255","142","כש\"ט ס\"ה."],["256","143","ברכות יז, ב. וש\"נ."],["257","144","ב\"ב ק, רע\"ב."],["258","145","עירובין מא, א. וראה סוטה מה, ב."],["259","146","שה\"ש ח, ז."],["260","147","שה\"ש שם. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370087\" data-slug=\"torah-or\" data-id=\"3901370087\">תו\"א תולדות יח, ג</a>."],["261","148","פ\"ג (לעיל ס\"ע 8 ואילך)."],["262","149","ישעי' מ, ה."],["263","150","נדרים ח, סע\"ב. וש\"נ."],["264","151","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא שעהיוה\"א רפ\"ד</a>."],["265","152","שמואל-א ו, יב."],["266","153","נוסף על הברכה שלאחריו – ברכת המזון, שחיובה מן התורה (ברכות מח, ב), אבל היתה כבר קודם מתן תורה – אצל <b>אוכלי המן</b> [שאכילת המן היתה ההקדמה וההכשרה למתן תורה, כמארז\"ל (מכילתא ר\"פ בשלח. שם טז, ד) \"לא ניתנה תורה כו' אלא לאוכלי המן\", שלכן היתה תחילה אכילת המן – בחמשה עשר (או ששה עשר) באייר (ראה מכילתא ופרש\"י בשלח טז, א ובפי' הרא\"ם וגו\"א שם. ועוד), ואח\"כ ניתנה תורה – בששה (או שבעה) בסיון (שבת פו, ב)], כמאמר רז\"ל (ברכות שם) \"משה תיקן לישראל ברכת הזן בשעה שירד להם מן\", אלא שבמתן תורה נעשית ברכת הזן <b>מצוה מן התורה</b> (כמו כל הענינים שהיו לפני מתן תורה, שבמתן תורה נעשו מצוה מן התורה), ומאז קיימוה (לא מפני שכן נהגו לפני מתן תורה, אלא) מפני שניתנה – מחדש – למשה <b>בסיני</b>."],["267","154","וחילוק זה ישנו גם בקיום המצוות – שיש ענינים שבאים ללא יגיעה, אלא ע\"י סייעתא דשמיא, היינו, שמלמעלה מזמינים לו מצוה מסויימת (וכל הענינים שזקוק אליהם כדי לקיים את המצוה), ובזה גופא, בשעה שיש אצלו \"עת רצון\", כשעומד בהתעוררות לקיים את המצוה – דוגמת לחם מן השמים; ויש ענינים שבאים לאחרי קשיים עצומים (\"געוואַלדיקע שוועריקייטן\"), וצריך יגיעת נפש ויגיעת בשר עד שפועל בעצמו לעשותם, ולא עוד אלא שגם אז אין זה באופן של מן המובחר, כי אם, לצאת ידי חובתו בלבד – דוגמת לחם מן הארץ."],["268","155","בשילוב עם שיחת ש\"פ בשלח תשכ\"ג."],["269","156","מו\"ק יז, א. וש\"נ."],["270","157","שבת קה, ב."],["271","158","ראה גם אג\"ק אדמו\"ר מוהריי\"צ ח\"ד ע' סז (נעתק ב\"היום יום\" כג סיון). מכתב י\"ט אלול שנה זו (אג\"ק חט\"ו ריש ע' תל). תו\"מ חי\"ז ע' 90. וש\"נ."],["272","159","ראה אג\"ק אדמו\"ר מוהריי\"צ ח\"י ע' שצד. סה\"ש תרפ\"ה ע' 83."],["273","160","וישלח לב, ז."],["274","161","עובדי' בסופו."],["275","162","וישלח לג, ט. וראה גם בהמאמר פ\"ז ואילך (לעיל ע' 17 ואילך)."],["276","163","יבמות קכב, א. וש\"נ. וראה תו\"מ ח\"ג ע' 193. וש\"נ."],["277","164","ע\"ז נד, ב (במשנה)."],["278","165","יומא לח, ב."],["279","166","ראה גם \"רשימות\" חוברת קפז ע' 11. תו\"מ שם ע' 288 הערה 33."],["280","167","ראה גם אג\"ק שלו ח\"ו ס\"ע רסט ואילך. תו\"מ שם ע' 325."],["281","168","ראה חובת הלבבות שער יחוד המעשה פ\"ה. <a class=\"ft-cite\" href=\"#/read/tanya/3401310017\" data-slug=\"tanya\" data-id=\"3401310017\">תניא פי\"ב (יז, א</a>). ובכ\"מ."],["282","169","ב\"ק פז, א."],["283","170","<a class=\"ft-cite\" href=\"#/read/tanya/3401310033\" data-slug=\"tanya\" data-id=\"3401310033\">תניא ספכ\"ח</a>."],["284","171","ראה גם שיחת יו\"ד שבט דאשתקד סכ\"ז (תו\"מ חט\"ז ע' 58 ואילך). וש\"נ."],["285","172","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310013\" data-slug=\"tanya\" data-id=\"3401310013\">תניא ספ\"ח</a>, ובהנסמן ב\"מ\"מ, הגהות והערות קצרות\" לשם (ע' עב)."],["286","173","לשון הכתוב – בהר כה, כ."],["287","174","כג, ב."],["288","175","פרש\"י שם."],["289","176","ראה תו\"מ חי\"ב ריש ע' 88. חי\"ד ע' 196. חי\"ז ע' 60. ועוד."],["290","177","זהר ח\"א קלד, סע\"א. ח\"ב קסא, רע\"ב. ח\"ג קעח, א. וראה ב\"ר בתחלתו."],["291","178","ר\"ה בתחילתה."],["292","179","ראה מכתב י\"א תמוז; י\"ז אלול שנה זו (אג\"ק חט\"ו ע' רפו; ס\"ע תיז). תו\"מ חי\"ז ע' 29. וש\"נ."],["293","180","שבת כא, ב."],["294","181","ראה מנחות פט, א: \"חצי לוג מאורתא ועד צפרא\". – ואולי הכוונה לשיטת הרמב\"ם שמדליקין המנורה גם בבוקר (ראה הל' תמידין ומוספין פ\"ג הי\"ב), שעפ\"ז, השיעור של יום הוא לוג שלם (<b>המו\"ל</b>)."],["295","182","פ\"ג מי\"א."],["296","183","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380951\" data-slug=\"likkutei-torah\" data-id=\"4001380951\">לקו\"ת דרושי ר\"ה נח, א</a> ואילך. עט\"ר שער ר\"ה בתחלתו. ובכ\"מ."],["297","184","ר\"ה יד, סע\"א ובפרש\"י."],["298","185","ירושלמי ר\"ה פ\"א ה\"ב."],["299","186","פ' שופטים כ, יט."],["300","187","ראה גם תו\"מ ח\"ט ס\"ע 190 ואילך."],["301","188","בראשית א, כח."],["302","189","ראה מכתב ה' טבת; ו' טבת שנה זו\n(אג\"ק חי\"ד ע' רמה; ע' רמח). וראה גם תו\"מ חי\"ח ריש ע' 273. וש\"נ."],["303","190","משנה וברייתא סוף קידושין."],["304","191","חגיגה יד, א. וש\"נ. וראה פרש\"י תשא לא, ג. דברים א, יג."],["305","192","ראה המשך תרס\"ו ס\"ע שפ ואילך. וראה גם תו\"מ חי\"ח ע' 194. וש\"נ."],["306","193","קדושים יט, יח."],["307","194","סה\"ש קיץ ה'ש\"ת ע' 3. וראה תו\"מ ח\"ב ע' 205. 210. חי\"ח ע' 256. וש\"נ."],["308","195","ואתחנן ו, יג."],["309","196","שבועות לט, סע\"א. וש\"נ."],["310","197","שה\"ש מח, רע\"ג."],["311","198","שבת לא, א."],["312","199","זהר ח\"ב רטו, א. וראה ח\"א קנ, רע\"א. רכג, א-ב. רכה, סע\"ב. רמט, ב. ח\"ב פה, רע\"א. וראה גם שמו\"ר פט\"ו, כו."],["313","200","נוסח ברכת \"שים שלום\" בתפלת העמידה. וראה תניא פל\"ב."],["314","201","ראה סה\"מ מלוקט ח\"ב ע' פב. וש\"נ."],["315","202","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251385\" data-slug=\"likkutei-sichot\" data-id=\"1300251385\">לקו\"ש חכ\"ה ע' 374</a>. וש\"נ."],["316","203","תצא כד, יט."],["317","204","ראה מק\"מ לזח\"א יז, ב. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380532\" data-slug=\"likkutei-torah\" data-id=\"4001380532\">לקו\"ת קרח נד, רע\"ג</a>."],["318","205","לשון חז\"ל – ברכות כח, א. וש\"נ."],["319","206","זכרי' יד, ט. וראה פסחים נ, א. וש\"נ."],["320","207","תמיד בסופה."],["321","208","שו\"ת חדות יעקב סכ\"ה."],["322","209","ראה פסחים לה, א-ב."],["323","210","ראה שהש\"ר פ\"ד, יב. \"רשימות\" חוברות כט ע' 7 ואילך. לב ע' 7. וש\"נ."],["324","211","שמות א, יד."],["325","212","ח\"ג קנג, א. הובא ונתבאר בתו\"א שמות בתחלתו."],["326","213","ב\"מ לח, א."],["327","214","פ' ראה יד, א."],["328","215","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ\"ב</a>."],["329","216","ראה זח\"ג עג, א."],["330","217","פסחים שבהערה 206."],["331","218","שהש\"ר רפ\"ה."],["332","219","ראה המשך באתי לגני ה'שי\"ת בתחלתו (סה\"מ תש\"י ע' 111)."],["333","220","שיחת ליל אחש\"פ תרצ\"ו סט\"ז (סה\"ש תרצ\"ו ע' 136). נעתק (בקיצור) ב\"היום יום\" יז שבט. וראה גם שיחת ליל שמח\"ת תרצ\"ז ס\"י (סה\"ש תרצ\"ז ע' 198)."],["334","221","בשלח טז, כט."],["335","222","שם יד, כז."],["336","223","זח\"ב קצח, סע\"ב. וראה ב\"ר פ\"ה, ה. שמו\"ר פכ\"א, ו."],["337","224","ברכות לה, ב."],["338","225","חולין ז, א."],["339","226","לקו\"א להה\"מ סרל\"ט (נז, ד). או\"ת ספ\"ט (לא, ג ואילך)."],["340","227","שמואל-ב כג, ג."],["341","228","מו\"ק טז, ב. וש\"נ."],["342","229","כלומר: אף שהצדיקים <b>אינם</b> עושים דברו, שהרי \"הקב\"ה גוזר וצדיק <b>מבטל</b>\" (כבהערה הקודמת), מ\"מ, ה\"ה \"עושים <b>רצונו</b> של מקום\", לפי שבזה גופא (שהקב\"ה גוזר וצדיק מבטל) ישנו <b>הרצון והתענוג</b> של הקב\"ה <b>יותר</b> מאשר אילו היו הצדיקים מסכימים לדבריו."],["343","230","ראה גם תו\"מ חי\"ג ע' 116. וש\"נ."],["344","231","בשלח יד, טז. ועוד."],["345","232","סוטה לז, א. מכילתא בשלח יד, כב. במדב\"ר פי\"ג, ז."],["346","233","ראה סידור האריז\"ל בתפלת העמידה במקומו. סידור (עם דא\"ח) בתפלת שחרית סז, ד ואילך."],["347","234","ב\"ר פצ\"ח, ג."],["348","235","ראה גם תו\"מ ח\"ד ע' 65. \"רשימות\" חוברת יד (יומן ד) ע' 16."],["349","236","משלי יז, א."],["350","237","ראה תניא אגה\"ק סט\"ז."],["351","238","תרל\"ו בתחלתו."],["352","239","משלי יט, ג."],["353","240","ראה בארוכה בהמאמר פ\"ז (לעיל ע' 18 ואילך). לקמן סמ\"ד."],["354","241","וישלח לג, יא. וראה בהמאמר פ\"ו ואילך (לעיל ע' 14 ואילך)."],["355","242","זח\"א לא, סע\"א. ועוד. וראה בהמאמר פ\"ה (לעיל ע' 12 ואילך)."],["356","243","פ' ראה טו, יח."],["357","244","מלאכי ג, יו\"ד."],["358","245","מכאן עד סו\"ס מז הוגה ע\"י כ\"ק אדמו\"ר שליט\"א (באידית), ונדפס ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021250\" data-slug=\"likkutei-sichot\" data-id=\"1300021250\">לקו\"ש ח\"ב ע' 526</a> ואילך. במהדורא זו ניתוספו עוד איזה ציוני מ\"מ, וכמה פרטים מהנחה בלתי מוגה."],["359","246","שיחת אחש\"פ תרח\"ץ – י\"ל בליקוט לח (נדפס בלקו\"ד ח\"ד תרצה, א ואילך, ולאח\"ז בסה\"ש תרח\"ץ ע' 277 ואילך). וראה מכתב כ\"א טבת שנה זו (אג\"ק חי\"ד ע' רצד)."],["360","247","ס' שופטים ה, א."],["361","248","מגילה לא, א."],["362","249","בשלח טו, א."],["363","250","שם, כ."],["364","251","קהלת ג, כ."],["365","252","ראה גם תו\"מ חי\"ח ע' 190. וש\"נ."],["366","253","ראה ב\"ר פע\"א, ב. זח\"א קנד, א."],["367","254","בהמאמר פ\"ז (לעיל ע' 18 ואילך). וראה גם לעיל סמ\"ב."],["368","255","בשלח טו, כו."],["369","256","ראה גם שיחת יו\"ד שבט דאשתקד סל\"ח (תו\"מ חט\"ז ע' 67). וש\"נ. שם ע' 259."],["370","257","ביצה טז, רע\"א."],["371","258","ספרי ופרש\"י נשא ו, כד."],["372","259","כולל גם – שהכסף לא ילך עבור ענינים בלתי-רצויים ח\"ו, כנ\"ל סמ\"ד (מהנחה בלתי מוגה)."],["373","260","משלי יו\"ד, כב."],["374","261","אבות פ\"ב מ\"ז."],["375","262","ולדוגמא: אם ישנם בבית שלשה חדרים מיותרים (\"מרבה נכסים\") – שלאמיתתו של דבר אין בהם צורך כלל, ואינם אלא עצת היצר – מתרבית בדרך ממילא גם הדאגה להשיג משרתת בשביל יום נוסף בשבוע כדי לנקות גם ג' החדרים היתרים... (מהנחה בלתי מוגה)."],["376","263","דברי-הימים-א כט, יא. וראה בהמאמר פ\"ה ואילך (לעיל ע' 14 ואילך)."],["377","264","ראה גם תו\"מ חי\"ח ע' 149. וש\"נ."],["378","265","יתרו יט, ג."],["379","266","מכילתא ופרש\"י עה\"פ. וראה גם שמו\"ר פכ\"ח, ב."],["380","267","תרומה כה, ח."],["381","268","שהוא ה\"דייר\" (\"ער איז אַ טענענט\") בבית ההוא, כמ\"ש \"ושכנתי בתוכם\" (מהנחה בלתי מוגה)."],["382","269","ראה תו\"מ ח\"ד ע' 71 ובהערה שם. וראה גם שיחת יו\"ד שבט תשי\"ד סל\"ו (תו\"מ חי\"א ס\"ע 49)."],["383","270","זבחים קטז, א. מכילתא כאן."],["384","271","ס\"פ בשלח."],["385","272","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111082\" data-slug=\"likkutei-sichot\" data-id=\"1300111082\">ח\"ב</a> סז, ב. סח, א. נתבאר בסה\"מ תש\"ט ס\"ע 56 ואילך. לקו\"ש חי\"א ע' 74 ואילך. ועוד."],["386","273","ראה כתר שם טוב (הוצאת תשנ\"ט) בהוספות סקי\"ח. סה\"מ עטר\"ת ע' רצד. תש\"ט ע' 65. ועוד."],["387","274","בלק כד, כ."],["388","275","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380172\" data-slug=\"likkutei-torah\" data-id=\"4001380172\">ראה של\"ה כה, א</a>. לקו\"ת תזריע כג, א. ובכ\"מ."],["389","276","ע\"ז ה, סע\"א."],["390","277","ר\"פ בחוקותי."],["391","278","בשלח יז, ט."],["392","279","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370371\" data-slug=\"torah-or\" data-id=\"3901370371\">תו\"א תצוה פג, ב</a>."],["393","280","תקו\"ז תס\"ט (קיב, רע\"א. קיד, רע\"א)."],["394","281","שם, יג."],["395","282","הובאו בתו\"ש עה\"פ (אות קג)."],["396","283","לשון הכתוב – יתרו יח, יד."],["397","284","ע' שיב. וראה גם תו\"מ ח\"ד ע' 30 ואילך. וש\"נ."],["398","285","ע\"ד שהמאורע ד\"ויבוא עמלק\" הי' כדי שבנ\"י יצעקו להקב\"ה – תמורת זה שקודם לכן אמרו \"היש ה' בקרבנו אם אין\" (בשלח יז, ז. וראה פרש\"י שם, ח)."],["399","286","זח\"ג ערב, א. תקו\"ז תכ\"א (מד, ב). ועוד."],["400","287","וילך לא, יח."],["401","288","יתרו יט, כ."],["402","289","משפטים כד, א."]]],[1400260006,"(הנחה בלתי מוגה)\n<b>ויבא</b><sup data-n=\"403\">1</sup> משה בתוך הענן גו' ויהי משה בהר ארבעים יום וארבעים לילה<sup data-n=\"404\">2</sup>. ואמרו רז\"ל<sup data-n=\"405\">3</sup> והובא בפרש\"י ענן זה כמין עשן הוא ועשה לו הקב\"ה שביל בתוכו. ולמדו זה ממה שנאמר<sup data-n=\"406\">4</sup> ויבאו בני ישראל <b>בתוך</b> הים, מה ביאתם לתוך הים היתה ע\"י שביל, כמ\"ש<sup data-n=\"406\">4</sup> והמים להם חומה מימינם ומשמאלם, כך גם מ\"ש ויבא משה <b>בתוך</b> הענן, היתה ביאתו לתוך הענן ע\"י שביל. וצריך להבין מהו ענין הענן שנכנס משה בתוכו, דמאחר שהי' זה ע\"י שביל, היינו שמשה נכנס לא בהענן עצמו אלא בהשביל, א\"כ מהי פעולת הענן. וגם צריך להבין השייכות דקריעת ים סוף לביאת משה בתוך הענן, דהשביל שהי' בקריעת ים סוף, ממנו נמשך השביל בתוך הענן, שזהו שלמדו שהי' שביל בתוך הענן מהשביל שבקריעת ים סוף.\nב) <b>ולהבין</b> זה צריך להקדים תחלה כללות ענין מתן תורה שהי' ע\"י משה, שלצורך זה (בכדי לקבל את התורה) בא בתוך הענן. דהנה איתא במדרש<sup data-n=\"407\">5</sup> שמשה הוא השביעי, וכל השביעין חביבין. וכמו בענין הרקיעים, שהרקיע הנקרא ערבות הוא השביעי, והוא חביב מכולם, כמ\"ש<sup data-n=\"408\">6</sup> סולו לרוכב בערבות גו'. וכמו\"כ הוא גם בענין האבות, שאברהם הוא הראשון ומשה הוא השביעי, הנה כל השביעין חביבין. וכמו\"כ הוא גם בענין הי\"ג תקונים, שתקון השביעי הוא תקון ואמת<sup data-n=\"409\">7</sup> (דהגם שכל התקונים הם אמת, מ\"מ, בענין התקונים גופא הנה תקון השביעי הוא בחי' אמת)<sup data-n=\"410\">8</sup>, וכללות הענין בזה, דאמת הו\"ע התורה, כמארז\"ל<sup data-n=\"411\">9</sup> אין אמת אלא תורה, וזהו שמשה שהוא השביעי, ומדתו מדת אמת<sup data-n=\"412\">10</sup>, כמאמר<sup data-n=\"413\">11</sup> מה ראהאמת ראה, ולכן על ידו דוקא ניתנה התורה שהיא אמת. דהנה<sup data-n=\"414\">12</sup>, אף שגם האבות קיימו כל התורה עד שלא ניתנה<sup data-n=\"415\">13</sup>, מ\"מ, מעשה האבות הי' ריח בלבד, כדאיתא במדרש<sup data-n=\"416\">14</sup> כל המצוות שעשו לפניך האבות ריחות היו, אבל אנו שמן תורק שמך, והיינו, דכמו הריח בגשמיות, שכאשר מריחים איזה פרי או מיני בושם לא נחסר מאומה בעצם הדבר עי\"ז שמריחים ממנו, לפי שהריח הוא הארה בלבד ולא עצם הדבר, כך גם מעשה האבות, כל מה שהמשיכו הוא רק הארה בלבד, משא\"כ אנו שמן תורק שמך, שע\"י קיום המצוות שאחרי מ\"ת ממשיכים את העצם, שזהו שמן תורק שמך, שכאשר מריקים את השמן מכלי אל כלי אזי נמשך בזה כל העצם, כמו\"כ הוא גם בענין קיום המצוות שאחרי מ\"ת, שעי\"ז הוא המשכת העצם. וטעם הדבר הוא, לפי שעבודת האבות הי' בכח עצמם, שהרי לא היו מצווים על זה. וכיון שעבודתם היתה בכח עצמם בלבד, לכן, אף שעבודתם הי' במס\"נ ובתכלית העילוי, וכמו אברהם שעבודתו היתה במדת האהבה, כתיב בי'<sup data-n=\"417\">15</sup> הלוך ונסוע הנגבה, שעלה בעילוי אחרי עילוי בענין האהבה, וכמו\"כ יצחק שעבודתו היתה בחפירת הבארות שהו\"ע העלאת הגבורות, הי' ג\"כ עבודתו במס\"נ, וכמו\"כ יעקב שהיתה עבודתו במדת הת\"ת, וכמ\"ש<sup data-n=\"418\">16</sup> ויקח לו יעקב מקל לבנה לח לוז וערמון, דחשיב כאן כל הג' גוונין, וענין התכללות כל הגוונים מורה על מדת הת\"ת, הנה אף שעבודתם היתה בתכלית העילוי ובמס\"נ, מ\"מ, כיון שלא היו מצווים על זה, היינו, שלא הי' בזה כח המצוה, אלא כל עבודתם הי' בכח עצמם, לכן לא הגיעו כי אם עד שרש הנבראים בלבד, לפי שהנברא בכח עצמו לא יכול להגיע אלא עד שרשו בלבד. וע\"ד דאיתא בגמרא<sup data-n=\"419\">17</sup> שמע מיני' עין עיטם גבוה מקרקע עזרה עשרים ושלש אמות, כי הפתח הי' גבוה כ' אמות, ושיעור המקוה שהיתה על שער העזרה הוא אמה על אמה ברום ג' אמות, ומזה מוכח שהמעין הי' גבוה מקרקע העזרה כ\"ג אמה, דאל\"כ, לא היו יכולים המים להגיע למעלה משרשם. וכל זה הוא במעשה האבות שעשו בכח עצמם. אבל ע\"י קיום המצוות שאחרי מ\"ת, כיון שאנו מצווים ועושים, הנה מצד כח המצוה, ממשיכים את העצם, שזהו ההתחדשות דמ\"ת שהיתה ע\"י משה. וזהו ג\"כ מ\"ש<sup data-n=\"420\">18</sup> ושמי הוי' לא נודעתי להם, ופרש\"י לא ניכרתילהם במדת אמיתית שלי, דהנה, שם הוי' הוא שם העצם<sup data-n=\"421\">19</sup>, והו\"ע ההמשכה שנעשה ע\"י התורה שנק' אמת כנ\"ל, משא\"כ ההמשכה להאבות היתה רק משאר השמות, ששרשם הוא בהרשימו, ודוקא ע\"י משה נמשך שם הוי', בחי' אור הקו שהוא אור עצמי כמו העצם ממש, דבר המוקש לי<sup data-n=\"422\">20</sup>, שלכן נקרא בשם העצם.\n<b>וענין</b> זה שההתחדשות דמתן תורה היא שע\"י המצוות שמקיימים עכשיו נעשה המשכת העצמות, מובן מעצם הענין דתומ\"צ. דהנה, ענין התומ\"צ הוא שעל ידם נעשה החיבור דגשמיות עם רוחניות, וידוע שחיבור גשמיות ורוחניות הוא בכח המפליא לעשות<sup data-n=\"423\">21</sup> דוקא, שהוא בכח העצמות. וזהו אפילו בענין חיבור גשמיות ורוחניות כפשוטו, ובפרט שעל ידי התומ\"צ נעשה החיבור דמדריגות העליונות שברוחניות גופא עם מדריגות התחתונות שבגשמיות גופא, היינו שנעשה החיבור דתכלית הרוחניות עם תכלית הגשמיות, הרי בודאי שזהו בכח העצמות דוקא. וכיון שההמשכה דמ\"ת שהמשיך משה היתה למטה מטה בעוה\"ז הגשמי, כדאיתא במדרש<sup data-n=\"424\">22</sup> שעיקר שכינה בתחתונים היתה, וע\"י החטאים סילקו את השכינה מלמטה למעלה עד רקיע הז', ואח\"כ עמדו צדיקים והמשיכו את השכינה מלמעלה למטה, עד שבא משה שהוא השביעי (וכל השביעין חביבין) והורידה למטה בארץ, הנה מזה גופא שההמשכה שהמשיך משה היתה למטה בארץ הגשמית, יש ראי' והוכחה נוספת שהמשכה זו היא המשכת העצמות ממש, דאל\"כ לא הי' אפשר להיות ההמשכה למטה מטה ביותר, כי רק ע\"י המשכת העצמות ממש נעשה החיבור דרוחניות עם גשמיות, שע\"י העבודה דאתכפיא סט\"א ממשיכים עיקר שכינה למטה מטה ממש.\nג) <b>והנה</b> המשכת העצמות שהמשיך משה למטה בתחתונים, התגלותה היא ע\"י נשמות ישראל, שזהו מ\"ש<sup data-n=\"425\">23</sup> ועשו לי מקדש ושכנתי בתוכם, בתוכו לא נאמר אלא בתוכם, בתוך כאו\"א מישראל<sup data-n=\"426\">24</sup>, היינו<sup data-n=\"427\">25</sup>, שנשמות ישראל ע\"י עבודתם באתכפיא ואתהפכא נעשים מקדש לו ית'<sup data-n=\"428\">26</sup>,שנמשך בהם הגילוי דשם הוי'. אמנם, גילוי המשכת שם הוי' שנעשה ע\"י נש\"י אינו רק בהנשמות בלבד, אלא ההמשכה היא גם בכללות העולם, ועי\"ז נשלמת הכוונה דנתאוה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"429\">27</sup>, שזוהי תכלית כוונת הבריאה, וכמבואר בתניא<sup data-n=\"430\">28</sup> שהכוונה אינה בשביל עולמות העליונים, אלא תכלית הכוונה שתהי' דירה בתחתונים דוקא, דפירוש תחתונים אינו במקום, שהרי הוא ית' אינו בגדר מקום כלל, וכמ\"ש<sup data-n=\"431\">29</sup> הנה מקום אתי, אלא פירוש תחתונים הוא במעלה ומדריגה, והיינו, שגם במקום החושך תהי' העבודה דאתכפיא סט\"א ואתהפכא סט\"א (דבאמת הנה האתכפיא היא הקדמה שמביאה לידי אתהפכא), שעי\"ז נעשה המשכת העצמות. וזהו שבישראל כתיב<sup data-n=\"432\">30</sup> היכל הוי' היכל הוי' היכל הוי' המה (ג\"פ), לפי שע\"י עבודתם ממשיכים בעולם את העצמות. דהנה, עם היות אשר את השמים והארץ אני מלא<sup data-n=\"433\">31</sup>, מ\"מ, הרי ענין זה הוא בהעלם, וע\"י העבודה הרי זה נעשה בגילוי. ומה שאמרו<sup data-n=\"434\">32</sup> איהו תפיס בכולהו עלמין ולית מאן דתפיס בי', הרי זה רק שאין תופסים בו שיהי' בבחי' תפיסא, אבל מ\"מ הרי הוא בגילוי. וזהו שההמשכה שהמשיכו האבות היתה רק הארה, ולא עצמות, ואילו העצמות הוא בהעלם, אבל נש\"י ע\"י עבודתם לאחרי מ\"ת, ממשיכים את העצמות שיהי' בגילוי, ועי\"ז משלימים את הכוונה דדירה בתחתונים, דפירוש ענין דירה הוא כמו עד\"מ בדירת האדם למטה שכל עצמותו ומהותו נמצא בהדירה בגילוי<sup data-n=\"435\">33</sup>, וכמו\"כ גם למעלה הפירוש דדירה בתחתונים הוא שהעצמות יהי' בגלוי.\n<b>והנה</b> ההמשכה דדירה בתחתונים נעשית ע\"י העבודה דתורה ומצוות. ואף שנת\"ל שענין זה נעשה ע\"י אתכפיא ואתהפכא, וכדאיתא בתניא<sup data-n=\"436\">34</sup>, הנה באמת הרי גם בעבודה דתורה ומצוות יש אתכפיא ואתהפכא. והיינו, לא מבעי במל\"ת שהם דברים שנפש האדם מחמדתם<sup data-n=\"437\">35</sup>, וכאשר פורש מהם הרי זה כפי' גדולה, אלא גם במ\"ע, הרי ידוע בכוונת המצוות, שכל מצוה יש לה איזה עבודה וכפי' פרטית, וכמו במצות אתרוג, אתרגר\"ת<sup data-n=\"438\">36</sup> <b>א</b>ל <b>ת</b>בואני <b>ר</b>גל <b>ג</b>אוה<sup data-n=\"439\">37</sup>, וכמו\"כ האתרוג דר באילנו משנה לשנה<sup data-n=\"440\">38</sup>, שהוא סובל את כל השינויים שישנם במשך השנה, שזה מורה על ענין הביטול, דכאשר הוא בישות, הרי בהכרח שיש בו איזה ציור והגבלה, שישנם ענינים שאינו יכול לסובלם, ומזה שהוא סובל כל השינויים, מוכח שאינו בישות כי אם בביטול. וכן הוא בשרשו למעלה, כמ\"ש בזהר<sup data-n=\"441\">39</sup> ע\"פ<sup data-n=\"442\">40</sup> וימלוך תחתיו הדר, הדר ודאי כמד\"א<sup data-n=\"443\">41</sup> פרי עץ הדר, והיינו, שאתרוג הוא בחי' מלך השמיני, הדר, שהוא שרש התיקון, והרי עיקר ענין התיקון הוא הביטול וההתכללות, שזהו ההפרש בין תהו לתקון<sup data-n=\"444\">42</sup>, שבתהו היו ענפין מתפרדין, משא\"כ בתקון. וזהו ההפרש בין יעקב לעשו, שבעשו, הגם שהיו ששה נפשות בלבד, נאמר<sup data-n=\"445\">43</sup> נפשות לשון רבים, משא\"כ ביעקב, אף שהיו שבעים, מ\"מ כתיב<sup data-n=\"446\">44</sup> נפש לשון יחיד. ומזה מובן שמצות אתרוג בנפש האדם הו\"ע הביטול. וכן במצות תפלין, שהוקשה כל התורה לתפלין<sup data-n=\"447\">45</sup>, הרי<sup data-n=\"448\">46</sup> כוונת מצות תפלין היא לשעבד הלב והמוח<sup data-n=\"449\">47</sup>, ובדרך פרט היינו ליבטל וליכלל בחי' חכמתו ובינתו שבנפשו האלקית בבחי' חכמתו ובינתו של א\"ס ב\"ה המלובשות בפ' קדש והי' כי יביאך, וכן ליבטל ולכלול בחי' הדעת שבנפשו הכולל חו\"ג שהן אהבה ויראה בבחי' דעת העליון הכולל חו\"ג המלובש בפ' שמע והי' אם שמוע<sup data-n=\"450\">48</sup>. וכמו\"כ במצות ציצית, שכוונת ענין הציצית הוא לקבל עליו עול מלכותו ית', שהו\"ע של כפי' גדולה, שהרי ע\"י הקבלת עול מלכות שמים נעשה אתכפיא סט\"א כו', ועד\"מ למטה, שכאשר העבד משועבד לאיזה אדון, אזי לא שייך שישעבד עצמו לאיזה אדון אחר, להיותו משועבד כבר לאדון זה. ועוד זאת, שציצית הוא מלשון ציץ<sup data-n=\"451\">49</sup>, כמו מציץ מן החרכים<sup data-n=\"452\">50</sup>, והו\"ע לאסתכלא ביקרא דמלכא<sup data-n=\"453\">51</sup>, והרי גם בזה נעשה אתכפיא סט\"א, כי מצד הסתכלותו ביקרא דמלכא, אי אפשר שתהי' לו שייכותלענינים אחרים. ונמצא מזה שבתומ\"צ נעשה אתכפיא סט\"א, הן במל\"ת, שפורש את עצמו מדברים שנפשו מחמדתם, והן במ\"ע, ע\"י הכוונה פרטית שבכל מצוה, כמו באתרוג בענין הביטול, ובתפלין בד' הפרשיות קדש והי' כי יביאך שמע והי' אם שמוע, שהו\"ע השעבוד דחכמה ובינה ודעת הכולל חו\"ג, וכמו\"כ בענין מצות ציצית כנ\"ל. וזהו שישראל נקראים היכל הוי', והיינו לפי שעבודתם היא בקיום המצוות שיש בזה אתכפיא ואתהפכא סט\"א, הנה ע\"י קיום מ\"ע, שהם בו\"ה, וע\"י קיום מל\"ת, שהם בי\"ה, נעשים היכל לשם הוי'.\nד) <b>והנה</b> כל זה הוא המשכת שם הוי'. אמנם כתיב<sup data-n=\"454\">52</sup> שאו ידיכם<sup data-n=\"455\">53</sup> קדש וברכו את הוי', היינו, שממשיכים (ברכו מלשון המשכה<sup data-n=\"456\">54</sup>) בשם הוי' בחי' קדש שהוא למעלה גם משם הוי'. והענין בזה, דהנה, אף שגם הוי' הוא בחי' קדוש, כמ\"ש<sup data-n=\"457\">55</sup> אין קדוש כהוי', ואיתא בזהר<sup data-n=\"458\">56</sup> כמה קדישין נינהו כו' ולאו קדישין כהוי', כי, כמה קדישין אינון הרי זה באופן שהם קדושים ומובדלים, אבל שם הוי', יש בו ב' הפכים, דהוי' הוא לשון מהוה<sup data-n=\"459\">57</sup>, שהוא מהוה את היש, ואעפ\"כ הוא קדוש ומובדל מהם, אף שמהוה אותם, ועז\"נ אין קדוש כהוי', שקדוש כזה שיש בו ב' הפכים הנ\"ל, לא נמצא בכל קדישין עלאין. אמנם, כל זה הוא בחי' אור הסובב בלבד, דאף שהוא למעלה מהעולמות, מ\"מ, הרי יש לו איזה שייכות לעולמות, שהוא בבחי' סובב עכ\"פ. ובחי' זו נק' קדוש (בוא\"ו). אמנם בחי' קדש אינו בגדר עלמין כלל<sup data-n=\"460\">58</sup>, גם לא בבחי' סובב, והו\"ע קדושת העצמות. ועז\"נ שאו ידיכם קדש וברכו את הוי'.\n<b>והענין</b> הוא, דהנה, משנת\"ל שישראל נקראים היכל הוי', הרי זה רק המשכת הסובב, ומצד בחי' זו אמרו רז\"ל<sup data-n=\"461\">59</sup> עתידים צדיקים שיאמרו לפניהם קדוש, לפי שהם ממשיכים בחי' אין קדוש כהוי'. אך המשכה זו אינה מספיקה, דכיון שאור הסובב יש לו איזה שייכות לעולמות, הרי אפשר שמצד חטאים ופגמים לא יומשך האור בהעולמות. והיינו, דאף שאין זה כמו הנשמה שמתפעלת ממקרי הגוף ח\"ו, מ\"מ,הנה אין זה סותר למשנ\"ת שע\"י החטאים כו' לא יומשך אור הסובב, כי, בנשמה שמתפעלת ממקרי הגוף, הנה כאשר ישנו קלקול באברי הגוף, אזי מסתלקת לגמרי הנשמה מהגוף, משא\"כ למעלה, הנה גם כאשר יהיו חטאים לא יסתלק האור ח\"ו, אמנם, אף שהאור לא יסתלק לגמרי, מ\"מ, הרי אפשר שיהי' בהעלם. וכל זה הוא באור הסובב, משא\"כ בעצמות שלמעלה מהסובב, לא שייך שמצד החטאים יהי' בזה אפילו העלם בלבד, דמאחר שהוא למעלה מהעולמות לגמרי, הרי אם צדקת מה תתן לו ורבו פשעיך מה תעשה לו<sup data-n=\"462\">60</sup>. וזהו מש\"נ שאו ידיכם קדש גו', כיון שצ\"ל המשכת העצמות דוקא, והיינו, שגם כאשר יהי' איזה סיבה להעלם אור הסובב, מ\"מ, הנה מצד העצמות יהי' בגילוי. ואף שמצד העצמות הרי הוא נמצא תמיד בהעולמות, כמ\"ש את השמים ואת הארץ אני מלא, מ\"מ, הרי זה בהעלם, וע\"י העבודה דשאו ידיכם קדש ממשיכים שיהי' בגילוי, וכמשנת\"ל שאף דלית מאן דתפיס בי', הרי זה בבחי' תפיסא דוקא, אבל מ\"מ ע\"י העבודה הרי זה בגילוי, אף שאינו בתפיסא. וכמו בהמשכה שע\"י המצוות, שהאור הוא בגילוי, אף שאינו נתפס, שהרי הנשמה מלובשת בהחומר, והחומר אינו מבלבל לאור הנשמה, והיינו, שגם כמו שהנשמה מלובשת בהחומר, מאיר לה האור של המצוה, ואעפ\"כ אין החומר מרגיש זה כלל, ומ\"מ, אף שאינו מרגיש, הרי זה בגילוי, שלכן חייבו רז\"ל<sup data-n=\"463\">61</sup> לקום ולעמוד מפני כל עוסק במצוה אף אם הוא בור ועם הארץ, והיינו מפני שמאיר בו בגילוי האור של המצוה<sup data-n=\"464\">62</sup>, אף שאינו בתפיסא. וכמו\"כ הוא בהענין דשבת שאסור בעשיית מלאכה, דבששת ימי החול מותר בעשיית מלאכה, כי, אף שאמרו רז\"ל<sup data-n=\"465\">63</sup> מאן דמחוי במחוג קדם מלכא קטלא חייב, מ\"מ, מצד ההעלם שבימי החול אין זה נחשב קמי מלכא, משא\"כ בשבת, הנה מצד הגילוי (אף שאינו בתפיסא), הרי זה קמי מלכא, ולכן אסור בעשיית מלאכה.\n<b>אך</b> הגורם להיות ההשפעה מבחי' קדש העליון הרי זה הענין דשאו ידיכם. והענין הוא, שידיכם שהם ב' ידים, הם ב' הפסוקים שבק\"ש, שמע ישראל וברוך שם, דשמע ישראל הוא יחו\"ע, וברוך שם הוא יחו\"ת<sup data-n=\"466\">64</sup>, והיינו, שבשמע ישראל ההתבוננות היא בענין ביטול העולמות איך שהם בטלים לאוא\"ס שקדוש ומובדל, שמצד זה נעשה בבחי' רצוא כו', ובברוךשם ההתבוננות היא איך שמצד בחי' שם כבוד ומלכות כמו שהם בהג' עולמות בי\"ע, יש איזה תפיסת מקום להעולמות, שמצד זה הוא בבחי' שוב, שנעשה אצלו ההרגש דעל כרחך אתה חי<sup data-n=\"467\">65</sup>, להיות בהעולם ולפעול בו בירור זיכוך ועלי'. וזהו ענין ב' ידים, יד ימין ויד שמאל, דיחו\"ע הוא בחי' יד ימין, שזהו כמו אדם שמחבק את חבירו בידו הימנית, שנעשה חבוק כולו (ער איז אינגאַנצן אַרומגענומען) ואינו יכול להיות ניזוז למקום אחר כלל, וכמו\"כ הוא בהעבודה דיחו\"ע, שמאיר אצלו האור כ\"כ עד שנעשה בבחי' רצוא, ואינו שייך שיהי' ניזוז למקום אחר כלל. והעבודה דיחו\"ת הוא בחי' יד שמאל, והוא ענין הגבורות וצמצומים, שעי\"ז הוא בבחי' שוב כנ\"ל. וזהו שאו ידיכם קדש וברכו את הוי', שע\"י העבודה דיחו\"ע ויחו\"ת ממשיכים את קדושת העצמות, שהוא בחי' קדש שלמעלה מקדוש, וברכו את הוי', שאור זה (בחי' קדש) נמשך בשם הוי', ועי\"ז נמשך ג\"כ בכללות העולם.\nה) <b>ובזה</b> יובן ג\"כ מ\"ש בגמרא<sup data-n=\"468\">66</sup> יבוא זה ויקבל זאת מזה לעם זו, יבוא זה, זה משה, דכתיב<sup data-n=\"469\">67</sup> זה משה האיש, ויקבל זאת, זו תורה, דכתיב<sup data-n=\"470\">68</sup> וזאת התורה אשר שם משה, מזה, זה הקב\"ה, דכתיב<sup data-n=\"471\">69</sup> זה א-לי ואנוהו, לעם זו, אלו לישראל, שנאמר<sup data-n=\"472\">70</sup> עם זו יצרתי. והנה, בענין זה א-לי ואנוהו איתא במדרש<sup data-n=\"473\">71</sup> שחורה אני ונאוה<sup data-n=\"474\">72</sup>, נאוה אני, באמרי זה א-לי ואנוהו. וצריך להבין, איך שייך שנברא יפעול בהבורא הענין דאנוהו, ויתרה מזה, שענין זה קשור עם הנברא בפנימיותו כל כך עד שמטעם זה יקרא הנברא עצמו בשם נאוה.\n<b>והענין</b> הוא, דהנה אמרו רז\"ל<sup data-n=\"475\">73</sup> בא וראה כמה גדולים יורדי הים, משה רבן של כל הנביאים כמה נתחבט ואמר הראני נא גו', וא\"ל הקב\"ה לא תוכל לראות את פני גו' (כי אם וראית את אחורי גו')<sup data-n=\"476\">74</sup>, ובקי\"ס הי' כל אחד (גם שפחה ואפילו עולל ויונק) מראה באצבעו ואומר זה א-לי ואנוהו. והנה, ענין זה שבקי\"ס היו גילויים נעלים ביותר, אף שלא יראני האדם וחי, הרי זה מצד ב' טעמים. טעם הא', מצד מעלת המס\"נדנחשון שקפץ בים<sup data-n=\"477\">75</sup>, שמס\"נ זו פעלה אצל כל ישראל שיאמרו זה א-לי ואנוהו. וטעם הב', כי, מ\"ש כי לא יראני האדם וחי, וארז\"ל<sup data-n=\"478\">76</sup> אפילו החיות הנושאות את הכסא אינן רואין, הרי זה רק בעלמא דאתגליא, משא\"כ בעלמא דאתכסיא רואין. והיינו, דעלמא דאתגליא הוא עד עולם הבריאה, וכיון שבבריאה לאו איהו וחיוהי וגרמוהי חד, לכן אינן רואין, משא\"כ בעלמא דאתכסיא שהוא באצילות, עולם האחדות, ששם איהו וחיוהי וגרמוהי חד<sup data-n=\"479\">77</sup>, לכן רואין. וכיון שבקי\"ס הפך ים ליבשה<sup data-n=\"480\">78</sup>, שהי' הגילוי דעלמא דאתכסיא, לכן הנה גם שפחה וגם עולל ויונק אמרו זה א-לי ואנוהו. וכנ\"ל דאף שנתחבט בזה משה רבן של כל הנביאים, מ\"מ, מצד ב' טעמים אלו, גדלה המעלה דקי\"ס על מעלת משה רבינו. והענין בזה, דאף שמשה נתנבא בזה, כמארז\"ל<sup data-n=\"481\">79</sup> כל הנביאים נתנבאו בכה ומשה נתנבא בזה, מ\"מ, נבואת משה היתה מאצילות דרך מעבר הבריאה, ולא מאצילות ממש, שהרי נבואת משה היתה מבחי' הבינה, וידוע שאבא עילאה מקננא באצילות<sup data-n=\"482\">80</sup> ואימא עילאה מקננא בכורסיא<sup data-n=\"483\">81</sup>, וכיון שנבואת משה היתה מבחי' בינה, נמצא, שנבואתו היתה מעולם הבריאה, אלא שבבריאה גופא היתה נבואתו מהאצילות שבבריאה, וכמ\"ש הרמ\"ז<sup data-n=\"484\">82</sup> שנבואת משה היא מפנימיות הבריאה, והו\"ע אור האצילות המאיר בה, אמנם בקי\"ס הי' גילוי האצילות ממש שלא ע\"י מעבר הבריאה.\n<b>והנה</b> קריעת ים סוף היתה הכנה למתן תורה<sup data-n=\"485\">83</sup>, דגם מ\"ת הו\"ע גילוי האצילות, היינו מאורות האצילות עד העצמות. והוא ג\"כ מצד ב' טעמים הנ\"ל, טעם הא'<sup data-n=\"486\">84</sup>, וטעם הב', לפי שבמ\"ת הי' החיבור דמעלה ומטה<sup data-n=\"487\">85</sup>, עלמא דאתכסיא ועלמא דאתגליא, ומצד עלמא דאתכסיא אפשר להיות כל הגילויים. וזהו ג\"כ מה שהתורה נקראת זאת, שהוא ג\"כ אותה הבחי' דזה א-לי ואנוהו, שלמעלה מבחי' זה דנבואת משה שהוא בחי' אצילות שבבריאה בלבד, אמנם מה שהתורה נק' זאת הוא גילוי האצילות ממש. וזהו מ\"ש יבוא זה ויקבל זאת, דממ\"ש יבוא ויקבל משמע שמשההוא למטה במדריגה מהתורה, והיינו לפי שמדריגת משה אינה גילוי האצילות ממש, משא\"כ בתורה שהיא גילוי האצילות ממש, שזהו זאת (תורה) מזה (הקב\"ה), היינו שע\"י התורה מתגלים כל האורות עד עצמות ממש. ומה שהתורה (שהיא למעלה ממדריגת משה) נקראת זאת בלשון נוקבא, הרי זה מצד התלבשותה בדברים הגשמיים, וענינה הוא שעל ידה נעשה המשכת כל האורות העליונים עד העצמות למטה ממש, ולכן נקראת זאת בלשון נוקבא (היינו לפי שהיא כלי המקבלת מהעצמות<sup data-n=\"488\">86</sup>). וע\"י וזאת התורה באים להגילוי דזה א-לי ואנוהו. ומצד זה נקראים ישראל בשם נאוה, דהנה, איתא ברמ\"ז<sup data-n=\"489\">87</sup> שתיבת זה, בגימטריא י\"ב, הו\"ע י\"ב אותיות דשם הוי' ג\"פ (ג' הויות שבברכת כהנים), וגם י\"ב אותיות דשם אד' ג\"פ, שהוא מ\"ש ג\"פ היכל הוי', דהיכל הוי' הוא אד', והוא בחי' המוחין, ג\"פ הוי' הו\"ע חב\"ד דז\"א, וג\"פ אד' הו\"ע חב\"ד שבמלכות. וזהו זה א-לי ואנוהו, שע\"י עבודת הנשמות עושים דירה לו ית' בתחתונים, שהו\"ע המשכת העצמות ממש שלמעלה מבחי' זה א-לי (שעי\"ז הם פועלים עילוי בבחי' זה א-לי), והוא בחי' שאו ידיכם קדש. ולכן נקראים ישראל ונאוה, שהוא מלשון דירה.\n<b>והנה</b> הענין דזה א-לי ואנוהו הוא עכשיו, אמנם לעתיד כתיב<sup data-n=\"490\">88</sup> ואמר ביום ההוא הנה אלקינו זה גו' זה הוי' קוינו לו, היינו, דעכשיו ישנו הגילוי דבחי' זה פעם א', ולעתיד יהי' הגילוי דבחי' זה ב\"פ. והענין הוא, שהגילוי דזה א-לי ואנוהו עכשיו הוא בחי' ת\"ת דז\"א, והגילוי דב\"פ זה לעתיד הוא בחי' ת\"ת דעתיק. והנה, הגילוי דב\"פ זה לעתיד נעשה ע\"י בירור בחי' זה דלעו\"ז, כמ\"ש וזה לכם הטמא<sup data-n=\"491\">89</sup>, המן הרע הזה<sup data-n=\"492\">90</sup>, אם פגע בך מנוול זה<sup data-n=\"493\">91</sup>, היינו, שגם הסט\"א נק' בשם זה, כמ\"ש<sup data-n=\"494\">92</sup> את זה לעומת זה עשה האלקים. וע\"י הבירור דלעו\"ז ממשיכים בחי' זה דעתיק. וזהו שאמרו רז\"ל<sup data-n=\"495\">93</sup> טוב זה יצ\"ט מאד זה מלאך המות, והיינו, שע\"י הבירור דלעו\"ז, שבירור זה נעשה ע\"י התורה, כמאמר אם פגע בך מנוול זה משכהו לבית המדרש, דכיון שהתורה היא כולה פנים, ואין בה בחי' אחור כלל<sup data-n=\"496\">94</sup>, לכן אי אפשר שיהי' בהתורה איזה אחיזה ללעו\"ז, ואדרבההתורה דוחה את הסט\"א, הנה ע\"י דחי' זו ממשיכים בחי' זה דעתיק<sup data-n=\"497\">95</sup>. וזהו שמסיים בכתוב זה הוי' קוינו, קוינו מלשון קוין, היינו, שההמשכה היא ע\"י הג' קוין שעליהם העולם עומד על התורה ועל העבודה ועל גמ\"ח<sup data-n=\"498\">96</sup>, שע\"י ג' קוין אלו נעשים כל ההמשכות, אלא שעכשיו הרי זה בהעלם, ולעתיד יהי' בגילוי, כמ\"ש<sup data-n=\"499\">97</sup> ונגלה כבוד הוי' וראו כל בשר יחדיו כי פי הוי' דיבר.\nו) <b>וזהו</b> ויבא משה בתוך הענן, דהנה בשביל הגילוי דמ\"ת שהו\"ע גילוי העצמות, הוצרך להיות ענין של לבוש שיוכל לקבל<sup data-n=\"500\">98</sup> בחי' התורה שנקראת זאת שבה מלובש בחי' זה ממש, ולבוש זה הו\"ע הענן, כמבואר במ\"א שהענן שהי' כמין עשן הוא ע\"ד ענין המשל<sup data-n=\"501\">99</sup>, שהוא כמו לבוש, שע\"י לבוש זה אפשר להיות המשכת העצמות. אמנם, ענין ויבא משה בתוך הענן הוא בדרך העלאה, והרי הכוונה היא שתהי' המשכת העצמות למטה, הנה על זה עשה לו הקב\"ה שביל בתוכו, שע\"י השביל נעשית ההמשכה למטה. וכשם שהי' בקי\"ס, דמ\"ש ויבאו בני ישראל בתוך הים הוא בדרך העלאה, אך הכוונה היא שעלמא דאתכסיא יאיר בעלמא דאתגליא, ולכן הפך ים ליבשה, והמשכת עלמא דאתכסיא היתה ע\"י השביל דהמים להם חומה, שע\"י שביל זה נמשך האור גם בעלמא דאתגליא, הנה כמו\"כ הוא גם בהענין דמ\"ת, שישנו שביל ודרך שבו ועל ידו מאיר האור למטה, וכמ\"ש<sup data-n=\"502\">100</sup> ושמרו דרך הוי' לעשות צדקה ומשפט, היינו שצדקה ומשפט הם הדרך והשביל להמשכת שם הוי' בעולם, שע\"י התומ\"צ נעשה גילוי העצמות בהעולם, אלא שעכשיו אין זה בגילוי, ויתגלה לעתיד, כמ\"ש ונגלה כבוד הוי' וראו כל בשר יחדיו כי פי הוי' דיבר.\n**********",[["403","1","מאמר זה \"הוא המאמר ויבא משה בתוך הענן תרנ\"ד [סה\"מ תרנ\"ד ע' קמז ואילך] . . עם איזה שינוים והוספות\"*."],["404","2","ס\"פ משפטים (כד, יח)."],["405","3","יומא ד, ב."],["406","4","בשלח יד, כב."],["407","5","ויק\"ר פכ\"ט, יא."],["408","6","תהלים סח, ה."],["409","7","זח\"ג (באד\"ר) קלג, סע\"ב ואילך."],["410","8","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת במדבר צג, א</a> (הערת כ\"ק אדמו\"ר שליט\"א בקונטרס הנ\"ל)."],["411","9","ירושלמי ר\"ה פ\"ג ה\"ח. וראה ברכות ה, ריש ע\"ב."],["412","10","שמו\"ר פ\"ה, י. ב\"ב עד, א. ועוד."],["413","11","סנהדרין קיא, א.\n*) <b>לשון ה</b>\"<b>פתח דבר</b>\"<b> לד\"ה הנ\"ל שי\"ל בקונטרס בפ\"ע (קה\"ת </b><b>–</b><b> פורים קטן</b>,<b> תשי\"ז)</b>,<b> בתוספת איזה מ\"מ והערות מכ\"ק אדמו\"ר שליט\"א (חלקם נעתקו לקמן)</b>."],["414","12","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370051\" data-slug=\"torah-or\" data-id=\"3901370051\">תו\"א יא, ד</a> ועוד. תו\"ח ד\"ה לך לך פ\"מ ואילך. לקו\"ת לג' פרשיות פה, ד [אוה\"ת לך לך (כרך ו) תתרעז, ב]. – הערה בקונטרס הנ\"ל."],["415","13","ראה יומא כח, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201200\" data-slug=\"likkutei-sichot\" data-id=\"1300201200\">לקו\"ש ח\"כ ע' 200</a> הערה 6. וש\"נ."],["416","14","שהש\"ר פ\"א, ג (א)."],["417","15","לך לך יב, ט."],["418","16","ויצא ל, לז. וראה אוה\"ת ויצא עה\"פ."],["419","17","יומא לא, א."],["420","18","וארא ו, ג."],["421","19","ראה אוה\"ת ע\"פ זה (הערה בקונטרס הנ\"ל)."],["422","20","ב\"ר פל\"ה, ג. וראה אוה\"ת ס\"פ נח."],["423","21","ראה רמ\"א או\"ח סו\"ס ו."],["424","22","ב\"ר פי\"ט, ז. שהש\"ר פ\"ה, א. וראה ד\"ה באתי לגני ה'שי\"ת פ\"א."],["425","23","תרומה כה, ח."],["426","24","ראשית חכמה שער האהבה פ\"ו קרוב לתחלתו (ד\"ה ושני הפסוקים). אלשיך תרומה עה\"פ (ד\"ה שמעתי לומדים). של\"ה סט, א. רא, א. שכה, ב. שכו, ב."],["427","25","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380052\" data-slug=\"likkutei-torah\" data-id=\"4001380052\">לקו\"ת פקודי ג, א</a>."],["428","26","ראה בארוכה ד\"ה באתי לגני שבהערה 22."],["429","27","ראה תנחומא בחוקותי ג. נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו. ובכ\"מ."],["430","28","שם."],["431","29","תשא לג, כא. וראה שמו\"ר ספמ\"ה."],["432","30","ירמי' ז, ד."],["433","31","שם כג, כד."],["434","32","זח\"ג (רע\"מ) רכה, א."],["435","33","ראה המשך תרס\"ו ס\"ע ג. ד\"ה נעשה אדם דש\"פ בראשית (התוועדות ב) פ\"ג (תו\"מ חי\"ח ע' 118)."],["436","34","פכ\"ז."],["437","35","ראה מכות כג, ב."],["438","36","ספר הליקוטים להאריז\"ל תהלים לו, יב (ע\"פ ב\"ר ספט\"ו ואדר\"נ פ\"א, ה). – ראה המשך וככה תרל\"ז פצ\"ג-ד (הערה בקונטרס הנ\"ל)."],["439","37","תהלים שם."],["440","38","סוכה לה, א."],["441","39","ח\"ג רצב, סע\"א (באדר\"ז)."],["442","40","וישלח לו, לט."],["443","41","אמור כג, מ."],["444","42","ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a> ואילך. ובכ\"מ."],["445","43","וישלח לו, ו."],["446","44","ויגש מו, כז. שמות א, ה."],["447","45","קידושין לה, א."],["448","46","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא רפמ\"א</a> (הערה בקונטרס הנ\"ל)."],["449","47","שו\"ע או\"ח סכ\"ה ס\"ה. שו\"ע אדה\"ז שם סי\"א. סידור אדה\"ז במקומו."],["450","48","ראה זח\"ג רסב, א. סידור שער התפילין ז, סע\"א ואילך."],["451","49","ספרי ופרש\"י שלח טו, לח."],["452","50","שה\"ש ב, ט."],["453","51","ראה זח\"ב רמז, ב. המשך מים רבים תרל\"ו פנ\"א."],["454","52","תהלים קלד, ב."],["455","53","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">לקו\"ת שה\"ש כא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381227\" data-slug=\"likkutei-torah\" data-id=\"4001381227\">שם כד, ג</a> (הערה בקונטרס הנ\"ל)."],["456","54","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370171\" data-slug=\"torah-or\" data-id=\"3901370171\">תו\"א מקץ לז, ג</a>."],["457","55","שמואל-א ב, ב."],["458","56","ח\"ג מד, א."],["459","57","פרדס שער א (שער עשר ולא תשע) פ\"ט. זח\"ג רנז, סע\"ב (ברע\"מ). מו\"נ ח\"א פס\"א. תניא שער היחוד והאמונה רפ\"ד."],["460","58","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380221\" data-slug=\"likkutei-torah\" data-id=\"4001380221\">ראה זח\"ג צג, א</a>. נתבאר בלקו\"ת אמור לג, ד."],["461","59","ב\"ב עה, ב."],["462","60","איוב לה, ו-ז (בשינוי הסדר)."],["463","61","ראה ירושלמי ביכורים פ\"ג ה\"ג."],["464","62","<a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא פמ\"ו (סו, א</a>)."],["465","63","ראה חגיגה ה, ב."],["466","64","זח\"א יח, ב. שער היחוד והאמונה לפני פ\"א. שם פ\"ז."],["467","65","אבות ספ\"ד."],["468","66","מנחות נג, ב."],["469","67","תשא לב, כג."],["470","68","ואתחנן ד, מד."],["471","69","בשלח טו, ב."],["472","70","ישעי' מג, כא."],["473","71","שמו\"ר פמ\"ט, ב."],["474","72","שה\"ש א, ה."],["475","73","שמו\"ר ספכ\"ג (בשינוי לשון קצת)."],["476","74","תשא לג, יח ואילך."],["477","75","ראה סוטה לז, א. פדר\"א פמ\"ב. במדב\"ר פי\"ג, ז."],["478","76","שמו\"ר שם."],["479","77","תקו\"ז בהקדמה (ג, ב). תניא אגה\"ק ס\"כ."],["480","78","תהלים סו, ו."],["481","79","ספרי ר\"פ מטות."],["482","80","ראה רמ\"ז לזח\"ב רכ, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370334\" data-slug=\"torah-or\" data-id=\"3901370334\">תו\"א משפטים עה, א</a>. סה\"מ תרצ\"ו ע' 119. וש\"נ."],["483","81","ראה תקו\"ז ת\"ו."],["484","82","לזח\"ב כג, א."],["485","83","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370282\" data-slug=\"torah-or\" data-id=\"3901370282\">תו\"א בשלח סג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380144\" data-slug=\"likkutei-torah\" data-id=\"4001380144\">לקו\"ת צו יז, א</a> ואילך."],["486","84","חסר קצת (<b>המו\"ל</b>)."],["487","85","ראה תנחומא וארא טו. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370304\" data-slug=\"torah-or\" data-id=\"3901370304\">תו\"א יתרו סח, א</a>. ובכ\"מ."],["488","86","כ\"ה בזכרון אחדים (<b>המו\"ל</b>)."],["489","87","ראה זח\"ג רעא, ב. ערב, ב וברמ\"ז שם."],["490","88","ישעי' כה, ט. שמו\"ר שם."],["491","89","שמיני יא, כט."],["492","90","אסתר ז, ו."],["493","91","סוכה נב, ב."],["494","92","קהלת ז, יד."],["495","93","ראה ב\"ר פ\"ט, י. זח\"א יד, א. יט, ב. ועוד."],["496","94","ראה תניא קו\"א קסא, א. סה\"מ תרמ\"ט ע' רסד."],["497","95","חסר אריכות הביאור בענין ב\"פ זה (<b>המו\"ל</b>)."],["498","96","אבות פ\"א מ\"ב."],["499","97","ישעי' מ, ה."],["500","98","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370074\" data-slug=\"torah-or\" data-id=\"3901370074\">ראה זח\"א סו, א</a> ובכ\"מ. אגה\"ק סכ\"ט. תו\"א טז, א (הערה בקונטרס הנ\"ל)."],["501","99","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370050\" data-slug=\"torah-or\" data-id=\"3901370050\">תו\"א יא, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370412\" data-slug=\"torah-or\" data-id=\"3901370412\">שם צא, ג</a>. ובכ\"מ (הערה בקונטרס הנ\"ל)."],["502","100","וירא יח, יט."]]],[1400260007,"בלתי מוגה\n<b>א</b>. יום הש\"ק מברכים החודש, כיון שבו מברכים את כל ימי החודש, הרי מובן, שכל הענינים שישנם בחודש זה – אפילו ענינים השייכים לימים פרטיים בחודש, ומכ\"ש ענינים שהם הנקודה המשותפת של כל ימי החודש – צריך להיות <b>מעין זה</b> בשבת מברכים, כפי שהפועל נמצא בכח עכ\"פ.\nובנדו\"ד: הנקודה המשותפת של כל ימי חודש אדר היא – שבכל ימים אלו ישנו הענין ד\"ונהפוך הוא\"<sup data-n=\"503\">1</sup>, שהרי ענין זה הוא לא רק בימי הפורים עצמם, אלא גם בימים שקודם פורים וגם בימים שלאחרי פורים, וכלשון חז\"ל<sup data-n=\"504\">2</sup> \"משנכנס אדר מרבין בשמחה\", שמזה מובן שהשמחה היא לא רק בפורים עצמו, אלא \"משנכנס אדר\"<sup data-n=\"505\">3</sup>.\n<b>ב</b>. אמנם, לכאורה מסתבר לומר שענין זה הוא רק בחודש אדר <b>שני</b> – שהרי הטעם לענין השמחה והענין ד\"ונהפוך הוא\" בחודש אדר הוא מצד <b>ימי הפורים</b>, וא\"כ, בחודש אדר שני, שבו חלים ימי הפורים, פועלים ימי הפורים ענין השמחה על כל החודש, משא\"כ בחודש אדר ראשון, שאין בו פורים, הנה גם השמחה דחודש אדר אינה שייכת בו.\nאך יש לומר, שמצד הענין ד\"<b>מרבין</b> בשמחה\", שהפירוש ד\"מרבין\" כולל כל ענין שיש לו איזה שייכות ואחיזה כו' (\"מ'טשעפּעט עס צו\"), יש לכלול בזה גם חודש אדר ראשון, דאף שאינו אלא אדר ראשון, מ\"מ, מצד ענין הריבוי (\"מרבין\"), צריך להיות ענין השמחה גם בחודש זה.\n<b>ג</b>. ועדיין יש להקשות על זה:\n\"משנכנס אדר <b>מרבין</b> בשמחה\" – שייך רק בנוגע לזמן שהוא בודאי חודש אדר, והספק הוא רק אם זהו ענין של שמחה, הנה מצד ענין הריבוי כוללים גם ענין זה; אבל בנוגע לחודש אדר <b>ראשון</b>, שאינו נכלל בענינו של חודש אדר לאמיתתו כלל, הרי לכאורה לא שייך בזה ענין הריבוי.וע\"ד שמצינו<sup data-n=\"506\">4</sup> בענין ספק ברכות להקל<sup data-n=\"507\">5</sup> (שאין מברכים במקום שיש ספק), שזהו דוקא כאשר הספק הוא על <b>הברכה</b>, כמו בברכת הנהנין, משא\"כ בברכת המצוות, כאשר הספק הוא (לא על הברכה, אלא) על <b>המצוה עצמה</b>, אזי לא שייך הכלל ד\"ספק ברכות להקל\".\nוזהו הטעם שמברכים את הברכות השייכות ליום-טוב גם ביו\"ט שני (נוסף על הטעם \"כי היכי דלא לזלזולי בה\"<sup data-n=\"508\">6</sup>) – דכיון שהספק אינו על הברכה, אלא על <b>היו\"ט עצמו</b>, הנה כאשר נפשט (מאיזה טעם שיהי') שהוא אכן יו\"ט, אזי מברכים בו את הברכות דיו\"ט.\nוכן הוא לכאורה בנדו\"ד – שיש חילוק אם הספק הוא על השמחה, שאז ההכרעה היא ש\"<b>מרבין</b> בשמחה\", או שהספק הוא על עצם הענין ד\"אדר\", שאז לא שייך הכלל ד\"מרבין בשמחה\".\nאבל, לאמיתו של דבר, כיון שגם באדר ראשון ישנו \"פורים קטן\", שאין אומרים בו תחנון<sup data-n=\"509\">7</sup> וכו' – הרי אף שבהענין דפורים עצמו אין זה אלא \"פורים <b>קטן</b>\" (ולא \"פורים גדול\" או אפילו \"פורים\" סתם), מ\"מ, די בזה כדי שיהי' נכלל ב\"אדר\", ובמילא הרי זה נכלל ב\"משנכנס אדר מרבין בשמחה\".\nוע\"פ האמור – יש להתחיל כבר עתה בענין השמחה, ולהמשיך זאת מיום זה על כל ימי החודש, כך, שכל הענינים הבלתי-רצויים יהפכו לששון ולשמחה, במהרה בימינו, למטה מעשרה טפחים.\n***\n<b>ד</b>. צוה לנגן ואמר מאמר ד\"ה ויבא משה בתוך הענן.\n***\n<b>ה</b>. [כ\"ק אדמו\"ר שליט\"א הורה לא' האברכים שערך \"שלום זכר\", לנגן ניגון. ואח\"כ אמר:]\nכ\"ק מו\"ח אדמו\"ר סיפר<sup data-n=\"510\">8</sup>, שאצל כ\"ק אדמו\"ר מהר\"ש היו ניגוניםמיוחדים על כל ענין, ועד שהי' אצלו ניגון מיוחד שהי' מנגן בשעה שהי' פושט בגדי חול ולובש בגדי שבת.\nובהתאם לכך, מן הראוי הי' שיעשו סדר בניגונים – לקבוע ניגונים מיוחדים עבור שלום-זכר, ברית, תנאים וחתונה.\nיערוך \"ניח\"ח\" אסיפה רבתי, שבה יבחרו ניגונים, ויקבעו ניגונים מיוחדים עבור כל ענין.\n<b>ו</b>. גם בהפטרת פרשתנו<sup data-n=\"511\">9</sup> מדובר אודות ענין הברית.\nואף שזהו ענין אחר של ברית, הן בתוכן ענין הברית, \"לשלח איש את עבדו ואיש את שפחתו העברי והעברי' חפשים\"<sup data-n=\"512\">10</sup>, והן באופן עשיית הברית, \"העגל אשר כרתו לשנים ויעברו בין בתריו\"<sup data-n=\"513\">11</sup>, מ\"מ, כיון שהפסוק \"העגל אשר כרתו לשנים ויעברו בין בתריו\" מובא בחסידות בנוגע לביאור ענין הברית<sup data-n=\"514\">12</sup>, מובן, שישנה נקודה משותפת לשני ענינים אלו.\nוביאור הענין:\nאמרו חז\"ל<sup data-n=\"515\">13</sup> \"וידבר ה' אל משה ואל אהרן ויצום אל בני ישראל<sup data-n=\"516\">14</sup>, על מה ציום, על פרשת שילוח עבדים\". והיינו, שישראל נצטוו במצות שילוח עבד עברי עוד קודם מתן-תורה, בהיותם עדיין במצרים. ולכן נזכר בציווי זה גם אהרן (ולא משה לבדו, כמו בשאר המצוות שניתנו בשעת מ\"ת), כיון שדיבור זה הי' עוד קודם מ\"ת, ונמסר ע\"י משה ואהרן.\n– בכלל, ידוע שמצוות פסח ומילה ניתנו עוד קודם מ\"ת, וישראל שמרו מצוות אלו עוד בהיותם במצרים<sup data-n=\"517\">15</sup>. אבל, כאמור, מצינו ענין זה גם בנוגע למצות שחרור עבד עברי.\nונמצא, ששני הענינים שלגביהם נאמר לשון \"ברית\" – מצות מילה ומצות שילוח עבד עברי – יש בהם נקודה משותפת, ששניהם נאמרו קודם מ\"ת, ולשניהם ישנה שייכות למצרים ויציאת מצרים.\n<b>ז</b>. וצריך להבין: מהי השייכות דמצות עבד עברי למצרים ויציאת מצרים?\nבשלמא פסח, מובנת שייכותו למצרים – שהרי כל ענין הפסחהוא שהקב\"ה פסח והוציא את ישראל מכל המצרים וגבולים שהיו ב\"ארץ מצרים\"; וכמו\"כ מובנת גם השייכות דמצות מילה למצרים – שהרי בזכות מצוה זו נגאלו ישראל ממצרים&lt;15&gt; (ובפרט בנוגע לשבט לוי, שקיימו מצוה זו במשך כל גלות מצרים, ועז\"נ<sup data-n=\"518\">16</sup> \"תומיך ואוריך לאיש חסידך\"<sup data-n=\"519\">17</sup>). אבל מהי שייכות מצות שילוח עבד עברי למצרים ויציאת מצרים?\nוביאור הענין:\nהטעם למצות שילוח עבד עברי הוא – לפי ש\"עבדי הם<sup data-n=\"520\">18</sup>, ולא עבדים לעבדים\"<sup data-n=\"521\">19</sup>. ולכן, בשעה שעבד אינו רוצה לצאת לחפשי, אזי \"ורצע אדוניו את אזנו\"<sup data-n=\"522\">20</sup>, וכמארז\"ל<sup data-n=\"521\">19</sup> \"אוזן ששמעה על הר סיני כי לי בני ישראל עבדים<sup data-n=\"520\">18</sup>, והלך זה וקנה אדון לעצמו, תרצע\".\nוהענין בזה – ע\"ד המבואר לעיל בהמאמר<sup data-n=\"523\">21</sup>, שבשעה שעבד משועבד לאדון פלוני, אינו שייך שיהי' משועבד לאדון אחר. וכן הוא גם בישראל, שמצד הענין דקבלת עול מלכות שמים, \"לי בני ישראל עבדים\", לא שייך שישעבדו עצמם לאדון אחר.\nוזהו הטעם שפעם בשבע שנים משחררים את העבד – כי עי\"ז שאין שבע שנים שלימות שבהן הוא \"עבד לעבדים\", הרי זה מגלה שגם בשעה שהי' בחיצוניות \"עבד לעבדים\", הנה בפנימיות נפשו הי' גם אז חפשי, והי' עבד להקב\"ה.\nוע\"ד מ\"ש במשנה<sup data-n=\"524\">22</sup> שנהרות \"המכזבים אחד בשבוע\", דהיינו שפעם אחת בשבע שנים מתייבשים, הרי זה מורה שגם בשעה שנמשכים בשופי, אינם \"מים חיים\", אלא נקראים \"מים המכזבים\".\nוכמו\"כ בנוגע למצות מילה:\nהרמב\"ם<sup data-n=\"525\">23</sup> מבאר, שאחד מהטעמים למצות מילה הוא – לפי שע\"י המילה והטפת דם ברית מחלישים את כח התאוה וההתקשרות להעולם. והיינו, שבחינת היסוד הוא ענין ההתקשרות, ומכיון ש\"יסוד סיומא דגופא\"<sup data-n=\"526\">24</sup>, הרי בו ישנה התאוה וההתקשרות לכל עניני הגוף. וע\"י מצות מילה מנתקים אותו מעניני העולם, ומקשרים אותו עם אלקות.\nונמצא, שב' מצוות אלו – מצות מילה ומצות שילוח עבד עברי– ענינם אחד: לנתק את היהודי משעבודו לעניני העולם ולכל הענינים שחוץ מאלקות, ולקשרו עם אלקות.\nולכן נקראו ב' מצוות אלו בשם \"ברית\" – שענינה התקשרות שלמעלה מטעם ודעת, שיהודי מנתק עצמו מכל עניניו, ומתקשר עם הקב\"ה בהתקשרות עצמית.\n<b>ח</b>. ועפ\"ז יובן הטעם שב' מצוות אלו (מצות מילה ומצות שילוח עבד עברי) ניתנו לישראל עוד בהיותם במצרים, קודם מתן-תורה – כיון שדוקא אז היו זקוקים ביותר למצוות אלו, כדי להבהיר, שיהודי צריך לדעת שהוא שונה מכל אומות העולם, להבדיל, ועליו להיות מקושר עם אלקות.\nדהנה, קודם מ\"ת – הרי אפילו למ\"ד קיימו אבותינו כל התורה עד שלא ניתנה<sup data-n=\"527\">25</sup>, יש דיעה<sup data-n=\"528\">26</sup> שקיימוה רק האבות, שבט לוי ויחידי סגולה; ואפילו אם אמנם קיימוה כל ישראל – הרי לא היו \"מצווים ועושים\", ובמילא היתה עבודתם מגעת רק בשורש הנבראים<sup data-n=\"529\">27</sup>, שגם באוה\"ע ישנו מעין זה, בשבע מצוות שנצטוו.\nולכן ניתנו להם מצוות אלו עוד בהיותם במצרים – כי אז הוצרך ביותר להבליט את מעלתו של יהודי, \"כי לי בני ישראל עבדים\".\nועי\"ז שעוד בהיותם במצרים היו לישראל שתי מצוות אלו – פעל בהם הדבר שסוכ\"ס יצאו ממצרים לגמרי, וקיבלו את התורה.\n<b>ט</b>. וביאור הענין בפרטיות יותר:\nבענין שילוח עבד עברי לחפשי ישנם שני זמנים: א) במשך שש שנות העבדות, שאז, בגלוי ובחיצוניות הרי הוא \"עבד לעבדים\", אלא שמצד הציווי להאדון לשלחו לחפשי, הרי גם עתה \"עבדי הם\", בפנימיות ובהעלם. ב) השנה השביעית, ש\"בשביעית יצא לחפשי\"<sup data-n=\"530\">28</sup> גם בחיצוניות ובגלוי.\nוהזמן הב' נמשך מהזמן הא': כיון שמיד בתחלה, כשנעשה עבד, אומרים לו שאין זה אלא ענין חיצוני, אבל בפנימיות הרי הוא עבד להקב\"ה – הרי זה פועל ש\"בשביעית יצא לחפשי\" בפועל ובגלוי.\nועד\"ז בנוגע להענין דמצרים ויציאת מצרים – שעי\"ז שעוד בהיותם במצרים היו לישראל ב' מצוות הנ\"ל, שעל ידם נעשו \"עבדי הם\" בפנימיות, פעל הדבר שלאח\"ז יצאו ממצרים גם בחיצוניות ובגלוי, וקיבלו את התורה.וזהו שהדיבור הראשון דמ\"ת הוא \"אנכי ה' אלקיך אשר הוצאתיך מארץ מצרים\"<sup data-n=\"531\">29</sup>, דהיינו שלאחרי מ\"ת נפעל בכאו\"א מישראל גם בגילוי, שאין לו שום שייכות עם ענינים של מצרים וגבולים, להיותו מקושר להקב\"ה.\n<b>י</b>. ושני זמנים אלו ישנם גם בברית-מילה:\nבשעת הברית, נמשכת נתינת כח מלמעלה, שהתינוק יהי' מקושר עם תומ\"צ ויגדל לתורה, לחופה ולמעשים טובים, ולא יידע כלל אודות עניני העולם, ובמילא לא תהי' לו שום שייכות לענינים אחרים.\nולכן אומרים בכל ברית מילה פסוקים הקשורים עם הברית שכרת הקב\"ה עם אברהם אבינו – כי כמו באברהם אבינו כן הוא גם בכאו\"א מישראל, שבשעה שנימול כורת עמו הקב\"ה ברית, שנעשה מקושר עם הקב\"ה בהתקשרות שלמעלה מטעם ודעת, ונחלשת אצלו התאוה וההתקשרות לעניני העולם.\nוזהו שמצינו בגמרא<sup data-n=\"532\">30</sup> בענין ברית מילה, שעלי' אמר דוד \"שש אנכי על אמרתך כמוצא שלל רב\"<sup data-n=\"533\">31</sup>, ואיתא בספרים<sup data-n=\"534\">32</sup> ש\"כמוצא שלל רב\" ראשי-תיבות \"כשר\" – כי עי\"ז שאדם מחליש את התאוה (ע\"י ברית מילה), הרי הוא פודה את כל ניצוצות הקדושה שבדברים הגשמיים שעוסק בהם (שהם עצמם בבחי' \"כשר\", להיותם קדושה, אלא שנמצאים בהגשמי בבחי' גלות), שהו\"ע השלל.\nאמנם, ענין זה שנפעל בשעת הברית אינו אלא נתינת כח מלמעלה, דהיינו שהענין נפעל בפנימיות נפשו;\nולאח\"ז בא הזמן הב' – במשך עבודתו כל ימי חייו, שאז מנצל את הכח בפועל, כדי לקשר עצמו עם מה שלמעלה הימנו.\nוכאשר האדם מקושר למעלה, אזי – כהסיפור הידוע שסיפר כ\"ק מו\"ח אדמו\"ר<sup data-n=\"535\">33</sup> אודות הרה\"צ ר' מאיר מפּרעמישלאַן, שסיומו הוא, שבשעה שמקושרים למעלה אין נופלים למטה.\n*<b>יא</b>. על הפסוק<sup data-n=\"536\">34</sup> \"ויהי שם עם ה' ארבעים יום וארבעים לילה\" (ועד\"ז בפרשתנו<sup data-n=\"537\">35</sup> \"ויבא משה גו' ויהי משה בהר ארבעים יום וארבעים לילה\"), מקשה בילקוט<sup data-n=\"538\">36</sup>: \"והלא כתיב ונהורא עמה שרא<sup data-n=\"539\">37</sup>, ונגה כאור תהי'<sup data-n=\"540\">38</sup>, גם חשך לא יחשיך ממך<sup data-n=\"541\">39</sup>, מנין הי' משה יודע אימתי יום ואימתי לילה\"? ומתרץ: \"אלא בשעה שהי' הקב\"ה מלמדו מקרא הי' יודע שהוא יום, ובשעה שהי' מלמדו משנה הי' יודע שהוא לילה\".\nולכאורה נשאלת השאלה: מה נוגע לנו לדעת את כל סיפור המאורע ד\"ויהי משה בהר ארבעים יום וארבעים לילה\", עם כל הפרטים שבזה – הרי \"מאי דהוה הוה\"<sup data-n=\"542\">40</sup> [וכדאיתא בחסידות<sup data-n=\"543\">41</sup> שמ\"ת הי' רק פעם אחת בלבד, ולא יהי' מ\"ת עוד הפעם, כי אפילו פנימיות התורה שתתגלה לעתיד, ניתנה כבר במ\"ת], ומה נוגע לנו לדעת את פרטי האופנים דמ\"ת?\nועכצ\"ל, שענין זה הוא הוראה גם לזמננו.\nוהענין בזה – שיש לדעת, שכל מציאות הזמן דיום ולילה נמשכת מהמציאות דמקרא ומשנה.\nיש מקום – \"הר סיני\" – שבו אין להזמן מציאות אחרת כלל מלבד מקרא ומשנה; אבל גם כאן למטה, כשנעשית מציאות של יום ולילה בגשמיות – יש לדעת שמציאות זו נמשכת ממקרא ומשנה, דהיינו שאמיתית המציאות דיום ולילה היא – מקרא ומשנה, שזהו זמן רוחני.\n<b>יב</b>. וביאור הענין:\n\"מקרא\" – ענינו יום וגילוי. וכמבואר בתניא<sup data-n=\"544\">42</sup> בפירוש הלשון<sup data-n=\"545\">43</sup> \"קורא בתורה\", שהוא \"כבן קטן הקורא לאביו\", וכך ע\"י לימוד התורה נמשך הקב\"ה להאדם. וענין זה הוא בתושב\"כ שנקראת בשם \"מקרא\", ולכן הרי זה ענין של אור וגילוי.\nמשא\"כ \"משנה\" (תושבע\"פ) – ענינה לילה והעלם, כיון שענינה הוא לברר הענינים הגשמיים ולדחות את היצר הרע. וכמבואר לעיל בהמאמר<sup data-n=\"546\">44</sup> בענין \"אם פגע בך מנוול זה משכהו לבית המדרש\"<sup data-n=\"547\">45</sup>, שביהמ\"דענינו תושבע\"פ, שעל-ידה דוחים את הקליפות. וכמשנ\"ת הטעם לזה, לפי שהתורה כולה פנים בכל הששה קצוות, ואין בה בחי' אחוריים כלל, ולכן בכחה לדחות את הקליפות וסט\"א.\nוממציאות זו דתושב\"כ ותושבע\"פ, יום ולילה שלמעלה – נשתלשלה המציאות דיום ולילה שלמטה. ובאותיות הקבלה – שמתחילת המשכת האור באופן ד\"מטי ולא מטי\", נמשכה למטה מציאות הזמן<sup data-n=\"548\">46</sup>.\n<b>יג</b>. וזוהי ההוראה מסיפור המדרש אודות משה רבינו – שיש לדעת, שכל מציאות הזמן אינה אלא מציאות של תורה שממנה נשתלשל הזמן.\nואף שאין רואים זאת בעיני בשר, הרי זה שהדבר הוא בהעלם או בגילוי אינו משנה כלל את הדבר עצמו. השינוי הוא רק שכאשר הדבר הוא בגילוי, אזי הוא נראה לכל, וכשהוא בהעלם, אזי שייך שיהי' מה שלא רואים; אבל הדבר עצמו אינו משתנה.\nהסיבה לכך שאנו רואים בעיני בשר את מציאות הזמן כמציאות בפני עצמו – הרי זה משום שאנו מסתכלים בעיני בשר, אבל האמת אינה כן. ומי שהוא מזוכך, רואה את האמת גם בעיני בשר.\nומה שטוענים: איך שייך שנשמה בגוף, בעולם הזה, יהי' לה ההרגש שכל המציאות דיום ולילה אינה אלא תושב\"כ ותושבע\"פ? – אזי המענה הוא: כבר הי' לעולמים! משה רבינו הי' נשמה בגוף גשמי, ואעפ\"כ, \"ויבא משה בתוך הענן גו' ויהי משה בהר ארבעים יום וארבעים לילה\", דהיינו <b>שבגופו הגשמי</b> היו אצלו \"ארבעים יום וארבעים לילה\" בבחי' יום ולילה הרוחניים!\nוענין זה הוא הוראה ונתינת כח לכאו\"א מישראל, שהרי \"כל אחד ואחד מישראל חייב לומר מתי יגיעו מעשי למעשה אבותי אברהם יצחק ויעקב\"<sup data-n=\"549\">47</sup>, וגם למדריגת משה<sup data-n=\"550\">48</sup>. והיינו, שענין זה צריך להיות בכאו\"א מישראל, אם לא בעיני בשר – עכ\"פ בהשגת השכל והרגש הלב.\n<b>יד</b>. וביאור הענין בפרטיות יותר:\nהאמור לעיל, שאצל משה רבינו היתה כל מציאות הזמן רק המציאותדמקרא ומשנה – הרי זה בשעה שהי' משה בהר; אבל בשעה שהי' למטה – היתה גם אצלו מציאות הזמן כמו שנשתלשל למטה.\n[וע\"ד שמצינו בענין האכילה דמשה – שבהיותו למטה, הי' אצלו ענין האכילה (דהן אמת שהיתה זו אכילת המן, שלא היתה בו פסולת<sup data-n=\"551\">49</sup>, ובזה גופא היתה זו אכילת <b>משה</b>, לפי מדריגתו, אבל סוכ\"ס הי' זה ענין של אכילה). משא\"כ כשהי' בהר – אזי \"לחם לא אכל ומים לא שתה\"&lt;34&gt;. וכן הוא בענין הזמן].\nוכן הוא בנוגע לכאו\"א מישראל (שעליו לומר \"מתי יגיעו מעשי למעשה אבותי\", וכן כמעשה משה, כנ\"ל) – שישנו חילוק אם הוא נמצא \"על ההר\" או לא:\nענינו של \"הר\" – שהוא באופן של עלי' והגבהה (דאף שגם הר הוא דומם, אבל בדומם גופא הרי הוא למעלה מכללות הדומם, להיותו בעלי'<sup data-n=\"552\">50</sup>). וב\"הר\" גופא – המדובר הוא בנוגע ל\"הר <b>סיני</b>\", שעליו היתה קבלת התורה, ונקרא בשם \"הר סיני, שירדה שנאה לאומות העולם עליו\"<sup data-n=\"553\">51</sup>.\nוהענין בעבודה – ש\"הר\" קאי על יושבי אוהל, דאף שנמצאים בעולם, מ\"מ, בעולם גופא הרי הם בעלי'. וב\"הר\" גופא – הרי הם בבחי' \"הר סיני\", להיותם קשורים עם התורה, ובמילא מנותקים הם מעניני העולם (\"שירדה שנאה לאומות העולם\").\nוזוהי ההוראה ממשה רבינו: כאשר נמצאים \"על הר סיני\", דהיינו במעמד ומצב ד\"יושבי אוהל\" – אזי כל מציאות הזמן צריכה להיות מקרא ומשנה, ושלא יהי' שום מציאות אחרת של זמן.\nכלומר: נוסף על זה שאצל כאו\"א מישראל צ\"ל הזמן שקול ומדוד, שהרי \"ימים יוצרו ולו אחד בהם\"<sup data-n=\"554\">52</sup>, דהיינו שכל יום, כל שעה וכל רגע שקולים ומדודים, ועליו לנצל כל רגע להעבודה, שהיא לגלות בחי' אחד שבו<sup data-n=\"555\">53</sup>, וכפי שמצינו באברהם אבינו, שנאמר בו<sup data-n=\"556\">54</sup> \"בא בימים\", \"יומין שלמין\"<sup data-n=\"557\">55</sup> – הנה נוסף לזה ביושבי אוהל בפרט, שמצד היותם קשורים עם התורה, הרי זה כל מציאות הזמן שלהם.והיינו, שאם הולך אצלם לאיבוד רגע שאינו מנוצל ללימוד התורה, הרי לא זו בלבד שלא מילאו את תפקידם שהי' עליהם למלא באותו זמן, אלא יתירה מזו – שכל מציאות הזמן (של אותו רגע שלא נוצל כדבעי) <b>אינו במציאות כלל</b>, כי כל מציאות הזמן אצל יושבי אוהל הוא – תורה.\nוזהו החילוק בין יושבי אוהל לבעלי עסק:\nבעלי עסק – עיקר עבודתם הוא <b>בקיום המצוות</b>, ומכיון שהיחוד בקיום המצוות אינו \"יחוד גמור\", אלא בבחי' מרכבה בלבד<sup data-n=\"558\">56</sup>, הרי ישנה המצוה בפני עצמה ומקיים המצוה בפני עצמו, ולכן שייך שיהי' גם מציאות הזמן בפני עצמו, מלבד העבודה שצריכה להיות באותו זמן; אלא, שאם לא עבד עבודתו באותו זמן, לא נוצל הזמן כדבעי.\nמשא\"כ יושבי אוהל – עבודתם היא <b>בלימוד התורה</b>, שהוא באופן של \"יחוד גמור ברצון העליון ולא מרכבה לבד\"<sup data-n=\"558\">56</sup>, דהיינו שהזמן והתורה הם דבר אחד, ולכן, אם ישנו משך זמן שבו אינו לומד – הרי זמן זה אינו במציאות כלל.\n<b>טו</b>. ואם הדברים אמורים ביושבי אוהל בכלל, דהיינו גם אלו שהי' להם בעבר שייכות לעניני העולם (ובמילא גם עתה רישומו ניכר), אלא שעתה נדבה לבם לעסוק בלימוד התורה, ואעפ\"כ אומרים להם שמכיון שעתה אין עסקם במשא ומתן [כולל גם \"משא ומתן\" המבואר בדא\"ח דרושי פרשת וישב<sup data-n=\"559\">57</sup>, דהיינו שלוקחים כסף וזהב ועושים מהם אהבה ויראה], הרי כל מציאות הזמן שלהם אינה אלא תורה – הרי מכ\"ש בנוגע לאלו שמעולם לא היתה להם שייכות לעניני העולם, דהיינו תלמידי הישיבה, שאצלם בודאי כן הוא.\nובפרטיות יותר: אם כן הוא בנוגע לתלמידי ישיבה סתם, אפילו תלמידי הישיבות שבהם לומדים רק גליא דתורה, שענינה בירורים, והיא קשורה עם עניני העולם, וגם היחוד שבה אינו בגלוי כל-כך, ואעפ\"כ אומרים שכל מציאות הזמן שלהם היא תורה – הרי מכ\"ש בנוגע לתלמידי הישיבות שבהם לומדים גם חסידות (וגם בשעה שלומד נגלה דתורה, צ\"ל ניכר עליו שזהו בחור השייך ללימוד החסידות), שבפנימיות התורה היחוד הוא בגלוי, הרי ודאי שכן הוא, שכל מציאות הזמן שלהם אינה אלא תורה<sup data-n=\"560\">58</sup>.<b>טז</b>. ובנוגע לפועל:\nצריכה להיות שמירת הזמן. כל רגע צריך להיות מנוצל בלימוד התורה, כי כל רגע שאינו מנצל ללימוד התורה, אינו קיים במציאות כלל.\nבנוגע לשמירת סדרי הישיבה – הרי זה דבר הפשוט, והמדובר הוא גם בנוגע לזמנים שהם, לכאורה, אינם תחת בעלות הישיבה, הנה גם זמנים אלו יש לנצל ללימוד התורה.\nומה שזמנים אלו נמסרו לרשותו, ויש לו בעלות עליהם – הרי בעלות זו מתבטאת בכך שבזמנים הפנויים מסדרי הישיבה יכול הוא לבחור בעצמו ללמוד מה שלבו חפץ: חלק זה בתורה או חלק זה בתורה, אבל בנוגע לעצם ענין הלימוד, הרי גם אז עליו ללמוד.\nואפילו באותם זמנים שצריך לאכול, לישון, לטייל וכדומה – הרי גם כשעוסק בדברים המוכרחים, צריך להיות ניכר עליו עול התורה, ובאופן שאינו שייך לענינים אחרים.\nוכמדובר לעיל בהמאמר&lt;21&gt;, שבשעה שעבד משועבד לאדון אחד, לא שייך שיעבוד אדון אחר. וכן הוא בנוגע לתלמידי הישיבה, שצריכים להיות משועבדים לגמרי לתורה, ובמילא לא שייך כלל שיתעסקו בענינים אחרים. וכאשר עוסקים בדברים המוכרחים, הרי זה צריך להיות באופן המבואר בחסידות<sup data-n=\"561\">59</sup>, שעבד, גם בשעה שישן, ניכר עליו שהוא עבד, ואימת רבו עליו.\nוכאשר ההנהגה היא באופן זה – אזי נרגש אצלו שכל המציאות דיום ולילה היא מקרא ומשנה, דהיינו שכל מציאות הזמן שלמטה היא מציאות הרוחנית שלמעלה.\nאלא, שעתה הרי זה רק בהשגת השכל ובהרגש הלב, אבל עי\"ז זוכים שלעתיד לבוא יראו זאת גם בעיני בשר, \"ונגלה כבוד הוי' וראו כל בשר יחדיו\" – דהיינו שיראו גם בעיני בשר – \"כי פי הוי' דיבר\"<sup data-n=\"562\">60</sup>.\n**********",[["503","1","אסתר ט, א."],["504","2","תענית כט, סע\"א."],["505","3","ראה גם שיחת ש\"פ משפטים, מבה\"ח אדר דאשתקד בתחלתה (תו\"מ חט\"ז ע' 97). וש\"נ."],["506","4","ר\"ן שבת כג, א (בשם קצת מן המפרשים). וראה אנציק' תלמודית ערך ברכות (כרך ד ע' שד ואילך). וש\"נ."],["507","5","רמב\"ם הל' ברכות פ\"ח הי\"ב. טושו\"ע או\"ח סר\"ט ס\"ג."],["508","6","שבת שם."],["509","7","שו\"ע סוף או\"ח. השלמה לשו\"ע אדה\"ז שם סקל\"א ס\"ח. סידור אדה\"ז לפני \"למנצח גו' יענך\"."],["510","8","לקו\"ד ח\"א קג, רע\"א. סה\"ש תש\"ד ע' 95."],["511","9","ירמי' לד, ח ואילך."],["512","10","שם, ט."],["513","11","שם, יח."],["514","12","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380896\" data-slug=\"likkutei-torah\" data-id=\"4001380896\">לקו\"ת נצבים מד, ב</a>."],["515","13","ירושלמי ר\"ה פ\"ג ה\"ה. וראה גם ספרי פ' ראה טו, טו (נת' ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241087\" data-slug=\"likkutei-sichot\" data-id=\"1300241087\">לקו\"ש חכ\"ד ע' 87</a> ואילך. וש\"נ)."],["516","14","וארא ו, יג."],["517","15","ראה פדר\"א פכ\"ט. מכילתא ופרש\"י בא יב, ו."],["518","16","ברכה לג, ח."],["519","17","שמו\"ר פי\"ט, ה."],["520","18","בהר כה, נה."],["521","19","קידושין כב, ב. וש\"נ. הובא בפרש\"י פרשתנו כא, ו."],["522","20","פרשתנו שם."],["523","21","פ\"ג (לעיל ס\"ע 74)."],["524","22","פרה פ\"ח מ\"ט."],["525","23","מו\"נ ח\"ג פל\"ה ופמ\"ט."],["526","24","תקו\"ז בהקדמה (יז, א)."],["527","25","ראה יומא כח, ב. קידושין פב, א."],["528","26","ראה לקו\"ש חל\"ה ס\"ע 183 ואילך. וש\"נ."],["529","27","ראה סה\"מ מלוקט ח\"ב ס\"ע רג ואילך. וש\"נ."],["530","28","פרשתנו כא, ב."],["531","29","יתרו כ, ב."],["532","30","שבת קל, א. מגילה טז, ב. וראה מנחות מג, ב."],["533","31","תהלים קיט, קסב."],["534","32","לקוטי לוי\"צ אג\"ק ע' קצח."],["535","33","ראה \"רשימות\" חוברת יד ע' 21. סה\"ש תרפ\"ה ע' 89. תרצ\"ו ע' 95 ואילך. וראה גם תו\"מ ח\"ג ע' 105."],["536","34","תשא לד, כח."],["537","35","בסופה."],["538","36","יל\"ש תשא רמז תו. מדרש תהלים עה\"פ יט, ג."],["539","37","דניאל ב, כב."],["540","38","חבקוק ג, ד."],["541","39","תהלים קלט, יב."],["542","40","לשון חז\"ל – יומא ה, ב. ועוד."],["543","41","ראה סה\"מ תרכ\"ו ע' שכו. תרנ\"ו ע' שנו. המשך תרס\"ו ע' כג. ע' תקמו. תער\"ב ח\"א ע' שסו. סה\"מ עטר\"ת ע' רצא. תרפ\"א ע' קסז. תרפ\"ה ע' קצט. תש\"ט ע' 57. ועוד."],["544","42","ספל\"ז."],["545","43","ברכות רפ\"ב. ועוד."],["546","44","ספ\"ה (לעיל ס\"ע 79)."],["547","45","סוכה נב, ב. וש\"נ."],["548","46","ראה מאמרי אדמו\"ר הזקן תקס\"ו ריש ע' מג. תקס\"ח ס\"ע תקמב. המשך תרס\"ו ע' מא ואילך. תער\"ב ח\"א ע' שלט ואילך. ועוד."],["549","47","תדבא\"ר רפכ\"ה."],["550","48","סה\"מ תער\"ב-ע\"ו ע' קלז."],["551","49","יומא עה, ב."],["552","50","ראה תו\"מ חי\"ד ס\"ע 116. וש\"נ."],["553","51","שבת פט, סע\"א."],["554","52","תהלים קלט, טז. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">תו\"א פרשתנו עה, סע\"ד</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161273\" data-slug=\"likkutei-sichot\" data-id=\"1300161273\">לקו\"ש חט\"ז ע' 273</a>. וש\"נ."],["555","53","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380520\" data-slug=\"likkutei-torah\" data-id=\"4001380520\">לקו\"ת שלח נב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381218\" data-slug=\"likkutei-torah\" data-id=\"4001381218\">שה\"ש כב, ב</a>. ובכ\"מ."],["556","54","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370351\" data-slug=\"torah-or\" data-id=\"3901370351\">חיי שרה כד, א</a>. וראה תו\"א פרשתנו עט, ב."],["557","55","ראה סה\"מ מלוקט ח\"א ע' תנא. וש\"נ."],["558","56","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא פכ\"ג (כח, ב</a>)."],["559","57","תו\"א ותו\"ח ר\"פ וישב. ובכ\"מ."],["560","58","ראה גם שיחת יו\"ד שבט סכ\"א ואילך (לעיל ס\"ע 37 ואילך). וש\"נ."],["561","59","ראה המשך תרס\"ו ע' שיב. וראה גם שיחת יו\"ד שבט סנ\"א (לעיל ע' 68). וש\"נ."],["562","60","ישעי' מ, ה."]]],[1400260008,"(הנחה בלתי מוגה)\n<b>כי</b> תשא את ראש בני ישראל לפקודיהם גו' זה יתנו גו' מחצית השקל וגו'<sup data-n=\"563\">1</sup>. ומבאר כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע במאמר ד\"ה זה משנת תרע\"ט<sup data-n=\"564\">2</sup>, שיש להקדים תחילה הידוע שמשה נקרא רעיא מהימנא<sup data-n=\"565\">3</sup>, שרועה ומפרנס נש\"י לחזק אותם באמונתם בה', ומבאר בארוכה שענין האמונה צריך להיות לא רק בבחי' ממכ\"ע, אלא גם בבחי' סוכ\"ע, וגם בבחי' עצמות אוא\"ס שלמעלה מבחי' סוכ\"ע וממכ\"ע, ועז\"נ<sup data-n=\"566\">4</sup> ורעה אמונה, דהיינו שצריכים לרעות את האמונה, להמשיכה בפנימיות. וכן מבאר כ\"ק מו\"ח אדמו\"ר במאמר ד\"ה וקבל היהודים דפורים קטן שנת תרפ\"ז<sup data-n=\"567\">5</sup>, שהוא מיוסד על ד\"ה כי תשא תרע\"ט הנ\"ל (אלא שבד\"ה וקבל היהודים לא נתבאר הפסוק כי תשא).\n<b>ומבאר</b> בהמאמר<sup data-n=\"568\">6</sup>, שהמשכה זו שע\"י משה שהאמונה תהי' נמשכת בפנימיות, הו\"ע מחצית השקל בשקל הקדש. ובזה יובן מ\"ש כי תשא וגו', שכאשר האמונה נמשכת בפנימיות (תשא את ראש בני ישראל), אזי כללות ההנהגה במחשבה דיבור ומעשה היא כדבעי, ועי\"ז מתבטלים גם כל הענינים הבלתי רצויים, שזהו אומרו לפקודיהם, לשון חסרון, כמו ונפקדת כי יפקד מושבך<sup data-n=\"569\">7</sup>, היינו, שע\"י המשכת האמונה בפנימיות מתבטלים הענינים הבלתי רצויים. וע\"ד מ\"ש<sup data-n=\"570\">8</sup> מצרף לכסף וכור לזהב ואיש לפי מהללו, דכמו המצרף וכור שמנקה הזהב והכסף מכל סיג ופסולת, כן איש לפי מהללו, לפי אופן ההילול שלו בתפלה כן הוא הבירור והזיכוך להסיר מעצמו כל הסיגים, גם הסיגים היותר דקים כו'. וזהו שאומרים בשמו\"ע סלח לנו אבינו כי חטאנו, כי דוקא לאחר עבודת ההכנה לפסוקי דזמרה ופסוד\"ז וברכות ק\"ש וק\"ש וג' ראשונות דשמו\"ע, אזי מרגישים שגם דקות הפסולת הו\"ע בלתי רצוי, ומסירים אותו כו'. ועד\"זיובן בענין כי תשא גו' לפקודיהם, שכאשר ענין האמונה מאיר בפנימיות, אזי נרגשים גם הענינים שבדקות דדקות, ועי\"ז נעשה החסרון (לפקודיהם) דכל הענינים הבלתי רצויים (לא רק ענינים הרעים), גם בדקות דדקות.\nב) <b>וממשיך</b> בהמאמר<sup data-n=\"571\">9</sup> לבאר מ\"ש זה יתנו גו' מחצית השקל בשקל הקודש, דצריך להבין מהו ענין מחצית השקל דוקא, ולמה מודיע כמה הוא השקל השלם מאחר שצריכים לתת רק מחצית השקל, ולמה בשיעור זה שוים העני והעשיר. והענין הוא, דהנה מחצית השקל, עשר גרה, מורה על עשר כחות הנפש, דכל נפש מישראל יש בה עשר בחי', כנגד עשר ספירות עליונות שנשתלשלו מהן<sup data-n=\"572\">10</sup>. ובענין זה כל הנשמות שוות, דכיון שהספירות העליונות הם במספר עשר, עשר ולא תשע עשר ולא אחד עשר<sup data-n=\"573\">11</sup>, הנה גם בכל נשמה מישראל יש עשר בחי', והיינו, שגם נשמה שהיא מבחי' נפש דנפש דעשי'<sup data-n=\"574\">12</sup> יש בה לא פחות מעשר בחי', וגם נשמה דאצילות יש בה לא יותר מעשר בחי'. וההפרש ביניהם הוא, שהעשר בחי' עצמם הם במדריגות שונות, שהרי אינו דומה מדריגת העשר כחות שבנפש דנפש דעשי' למדריגת העשר כחות דנשמה דאצילות, ועד שאין ערוך ביניהם, שלכן נקראים עני ועשיר. ומ\"מ, כל בני ישראל שוים בכך שיש לכל אחד עשר כחות, והעבודה היא שכל אחד צריך ליתן את העשר כחות שלו, והיינו, שאף שיש מי שהעשר כחות שלו הם במדריגה נעלית ויש מי שהעשר כחות שלו הם במדריגה תחתונה, מ\"מ, אין הקב\"ה מבקש אלא לפי כחן<sup data-n=\"575\">13</sup>, ודורש מכל אחד ליתן את העשר כחות <b>שלו</b>. אמנם, מה שכל אחד מישראל נותן את העשר כחות שלו, הרי זה רק <b>מחצית</b> השקל. אך עי\"ז שכל אחד מישראל נותן את המחצית שלו, היינו שמוסר את כל כחותיו לאלקות, אזי נותנים לו מלמעלה את המחצית השני'.\nג) <b>וביאור</b> הענין, דהנה כתיב<sup data-n=\"576\">14</sup> עבדו את הוי' בשמחה, שזהו ציווי לכל אחד מישראל שתהי' עבודתו בשמחה, וענין השמחה הוא יסוד בעבודה, וכמ\"ש הרמב\"ם בסוף הל' לולב<sup data-n=\"577\">15</sup> שהשמחה שישמח אדם בעשיית המצוה ובאהבת הא-ל שצוה בהן עבודה גדולה היא, וכל המונע עצמו משמחה זו ראוי להפרע ממנו, שנאמר<sup data-n=\"578\">16</sup> תחת אשר לא עבדתאת הוי' אלקיך בשמחה ובטוב לבב, והיינו, שאפילו כאשר יש אצלו ענין העבודה, וחסר רק ענין השמחה, מגיע לו עונש חמור ביותר כמו שלא הי' כללות ענין העבודה, שזהו לפי שהשמחה היא יסוד בעבודה. אמנם, עפ\"ז צריך להבין מ\"ש<sup data-n=\"579\">17</sup> שמחו צדיקים בהוי', דמשמע שענין השמחה שייך לצדיקים דוקא.\n<b>אך</b> הענין הוא, דיש ב' בחי' שמחה. דהנה, כללות ענין השמחה היא העבודה שמצד האהבה, ובענין האהבה מצינו ב' בחינות. יש אהבה שהיא ע\"פ טו\"ד, היינו, שכאשר מתבונן בענין שכר מצוה מצוה<sup data-n=\"580\">18</sup>, אזי מרגיש את היוקר והחשיבות דתומ\"צ, ועי\"ז נעשית עבודתו בשמחה. וענין זה שייך לכל ישראל, שצריך להרגיש את היוקר והחשיבות דתומ\"צ, ומצד זה צריכה להיות עבודתו בשמחה, וכאשר חסר בהשמחה, אין זה חסרון בפרט מסויים בלבד, אלא זה מורה שחסר אצלו כל הרגש היוקר והחשיבות דתומ\"צ. אמנם כל זה הו\"ע האהבה שע\"פ טו\"ד. אך יש אהבה שלמעלה מטו\"ד, שאהבה זו אינה כמו האהבה שע\"פ טו\"ד שבהכרח שיש בה מבוקש, אלא אהבה זו היא בלי מבוקש, כי אם כמ\"ש בתניא<sup data-n=\"581\">19</sup> בענין בני עלי'<sup data-n=\"582\">20</sup>, שעבודתם היא לא כדי לדבקה בו בלבד לרוות צמאון נפשו הצמאה לה', אלא כדפירשו בתיקונים<sup data-n=\"583\">21</sup> איזהו חסיד המתחסד עם קונו, עם קן דילי', ליחדא קוב\"ה ושכינתי' בתחתונים. ועז\"נ שמחו צדיקים בהוי', שזוהי השמחה שמצד האהבה שלמעלה מטו\"ד, שאינה שייכת לכל בני ישראל, אלא לצדיקים בלבד, ובאה בבחי' מתנה מלמעלה.\n<b>ויש</b> לומר בדא\"פ, שזהו גם הענין דשויתי ה' לנגדי תמיד<sup data-n=\"584\">22</sup>, כפירוש הבעש\"ט (בצוואת הריב\"ש<sup data-n=\"585\">23</sup>) שויתי לשון השתוות, היינו, שכל הענינים צריכים להיות בהשתוות אצל האדם, כיון שהוי' הוא לנגדי תמיד, שענין זה הוא מצד העבודה שלמעלה מטו\"ד, כי, כאשר העבודה היא ע\"פ טו\"ד, יש לו איזה מבוקש, ובמילא אין אצלו ענין של השתוות, אבל כאשר העבודה היא למעלה מטו\"ד, בלי שום מבוקש, אזי כל הענינים אצלו הם בהשתוות. ומצד זה נעשית העבודה באופן של מסירת נפש, כיון שלא נוגע לו שום דבר (שום מבוקש), מלבד מילוי רצון העליון.<b>ועפ\"ז</b> יובן ענין מחצית השקל השני', שלאחרי שהאדם עובד עבודתו בעשר הכחות (מחצית השקל) שלו בעבודה שע\"פ טעם ודעת, אזי נותנים לו מלמעלה בדרך מתנה את המחצית השני', היינו, שמגיע להעילוי דשמחו צדיקים בהוי', שהו\"ע האהבה והשמחה שבעבודה שלמעלה מטו\"ד. והרי כתיב<sup data-n=\"586\">24</sup> ועמך כולם צדיקים, שיכולים לבוא לזה ע\"י האהבה והשמחה שבעבודה שע\"פ טו\"ד, שעי\"ז נותנים מלמעלה את האהבה והשמחה העליונה. וזהו גם החילוק שבין ב' חצאי השקל, שמחצית השקל הראשונה, שכל אחד נותן את העשר כחות שלו, יש בה חילוקים בין עני לעשיר (כנ\"ל), אבל מחצית השקל השני', שלמעלה מטו\"ד, הרי זה ענין של עשירות.\nד) <b>וזהו</b> כי תשא את ראש בני ישראל לפקודיהם גו' זה יתנו גו' מחצית השקל גו', היינו, שהתחלת כל הענינים היא מהנשיאות ראש שפועל משה, ואתפשטותא דמשה בכל דרא ודרא<sup data-n=\"587\">25</sup>, שממשיך את האמונה בפנימיות, ועי\"ז נעשה לפקודיהם (ביטול הענינים הבלתי רצויים), וכן הענין דזה יתנו גו' מחצית השקל, נתינת מחצית השקל הראשונה (מסירת כל העשר כחות לאלקות), וגם מחצית השקל השני' שבאה בדרך מתנה מלמעלה (עבודה שלמעלה מטו\"ד, ענין ההשתוות והעבודה דמסירת נפש), שלכן, הנה גם ענין זה (מחצית השקל השני') שייך לכאו\"א מישראל שהרי משה הוא הרועה דכאו\"א מישראל, ובפרט בנוגע לחסידים, שלהיותם קשורים בקירוב יותר למשה שבדורנו, כ\"ק מו\"ח אדמו\"ר, הרי זה צריך לעורר אותם עוד יותר שיהי' אצלם ענין ההשתוות וענין העבודה דמסירת נפש.\n<b>ויש</b> לומר שבאמירת המאמר הנ\"ל ע\"י אדמו\"ר נ\"ע בשנת עטר\"ת, נמשך נתינת כח לעבודה שלמעלה מטו\"ד (מחצית השקל השני'), והמשכה זו היתה לא רק על אותו הזמן, אלא גם על כל הזמנים. ולכן, כאשר כ\"ק מו\"ח אדמו\"ר אמר את המאמר ד\"ה וקבל היהודים בשנת תרפ\"ז, המיוסד על המאמר ד\"ה כי תשא הנ\"ל, דובר במאמר זה אודות ענין המסירת נפש כפי שהי' מתאים ונדרש בזמן ההוא. וכמו\"כ צריך מאמר זה לעורר ולפעול על כל הזמנים, אצל כל בני ישראל, ובפרט אצל חסידים, את ענין ההשתוות והמסירת נפש, שלא לחשוב אודות עצמו, אלא להיות מסור ונתון לרצון העליון במסירת נפש. וכאשר כל אחד יפעל ענין זהבעצמו, יהי' די בכך (וועט מען דערמיט אָפּקומען), והיינו, שיוצאים י\"ח במסירת נפש בכח, ולא יהי' צורך במסירת נפש בפועל.\nה) <b>ויש</b> לקשר זה עם הענין דפורים קטן (שבו נאמר המאמר ד\"ה וקבל היהודים הנ\"ל), שבו מודגש הענין דטוב לב משתה תמיד<sup data-n=\"588\">26</sup>, ואיתא בגמרא<sup data-n=\"589\">27</sup> טוב לב משתה תמיד זה שדעתו רחבה. והענין בזה, שכאשר דעתו רחבה, שהו\"ע בחי' עשירות שלמעלה מטעם ודעת, בלי שום מבוקש<sup data-n=\"590\">28</sup>, אזי נעשה ענין ההשתוות, ומצד ענין ההשתוות הרי הוא תמיד בשמחה, שזהו טוב לב משתה תמיד. ועד\"ז בנוגע לענין המסירת נפש, כמשנת\"ל שכאשר עומדים בתנועה של מסירת נפש, אזי מתבטלים כל המניעות ועיכובים, ואין צורך במסירת נפש בפועל, כי אם, טוב לב משתה תמיד, היינו, שתמיד, בכל הזמנים, יהי' טוב לב, כיון שע\"י העבודה דמסירת נפש יסירו את כל המניעות, ויומשכו כל הענינים בטוב הנראה והנגלה.\n**********",[["563","1","ריש פרשתנו (תשא ל, יב-יג)."],["564","2","סה\"מ עטר\"ת ע' רסז."],["565","3","ראה שמו\"ר פ\"ב, ד. וראה זח\"ב כא, א."],["566","4","תהלים לז, ג."],["567","5","ס\"ד ואילך (סה\"מ תרפ\"ז ע' קיג ואילך)."],["568","6","ראה סה\"מ עטר\"ת ע' ערה."],["569","7","שמואל-א כ, יח."],["570","8","משלי כז, כא."],["571","9","סה\"מ עטר\"ת ע' רעז ואילך."],["572","10","<a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא רפ\"ג</a>."],["573","11","ספר יצירה פ\"א מ\"ד."],["574","12","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>."],["575","13","במדב\"ר פי\"ב, ג. תנחומא נשא יא."],["576","14","תהלים ק, ב."],["577","15","פ\"ח הט\"ו."],["578","16","תבוא כח, מז."],["579","17","תהלים צז, יב."],["580","18","אבות פ\"ד מ\"ב. וראה תניא פל\"ז. פל\"ט."],["581","19","פ\"י."],["582","20","סוכה מה, ב."],["583","21","בהקדמה (א, סע\"ב)."],["584","22","תהלים טז, ח."],["585","23","סימן ב' (הוצאת קה\"ת ע' א)."],["586","24","ישעי' ס, כא."],["587","25","תקו\"ז תס\"ט (קיב, א. קיד, א)."],["588","26","משלי טו, טו. וראה רמ\"א סוף חלק או\"ח."],["589","27","ב\"ב קמה, ב."],["590","28","וענין זה הוא למעלה יותר ממשנת\"ל (בהשיחה ס\"ו (לקמן ע' 99)) שדעת רחבה היינו שחושב (לא אודות גשמיות, אלא) אודות רוחניות כו' – שהרי עדיין יש בזה מבוקש, אלא שהמבוקש הוא רוחניות."]]],[1400260009,"בלתי מוגה\n<b>א</b>. בשולחן<sup data-n=\"591\">1</sup> ערוך אורח חיים<sup data-n=\"592\">2</sup> מביא הרמ\"א ב' דעות, אם יש להרבות במשתה ושמחה בפורים קטן, והרמ\"א מכריע, ש\"ירבה קצת בסעודה כדי לצאת ידי המחמירים\", ומסיים: \"וטוב לב משתה תמיד\"<sup data-n=\"593\">3</sup>.\nובזה גופא ישנם ב' דעות: אם קאי על י\"ד באדר ראשון, פורים קטן, דוקא<sup data-n=\"594\">4</sup>, או גם על ט\"ו, שושן פורים קטן<sup data-n=\"595\">5</sup>.\nומלשון הרמ\"א נראה כדעה הב'. דכיון שהרמ\"א מסיים \"וטוב לב משתה תמיד\", הרי מתיבת \"תמיד\"<sup data-n=\"596\">6</sup>, מוכח, שאם רק יש איזו סברא שצריכה להיות שמחה, יש לעשות כן.\nוכאשר ינהגו בהנהגה זו, שכאשר יש איזו דיעה על ענין השמחה, יחמירו בכך, אזי נבוא עי\"ז למש\"נ בפסוק – \"וטוב לב משתה תמיד\".\n<b>ב</b>. על הפסוק \"וטוב לב משתה תמיד\", איתא בגמרא<sup data-n=\"597\">7</sup>: \"זה שדעתו רחבה\". ורש\"י מפרש על הפסוק: \"וטוב לב . . שמח בחלקו\".\nוצריך לומר שישנה שייכות בין שני פירושים אלו, היינו, שעי\"ז שהוא בעל דעת רחבה, הרי הוא שמח.\nלכאורה, קשור הדבר עם אופן ההנהגה שמתנהגים עמו מלמעלה: אם מתנהגים עמו במדת החסד, ונותנים לו כל צרכיו – אינו דואג, ואם מתנהגים עמו בהנהגה אחרת – שייך שיהיו לו דאגות.\nאבל מדברי הגמרא \"וטוב לב משתה תמיד, זה שדעתו רחבה\", מוכח, שכאשר הוא בעל דעת רחבה, הרי הוא שמח בכל האופנים.\n<b>ג</b>. ויובן בהקדים פירוש אדמו\"ר מהר\"ש<sup data-n=\"598\">8</sup> בשם אדמו\"ר הזקן<sup data-n=\"599\">9</sup> עלמאמר הפיוט<sup data-n=\"600\">10</sup> \"מרובים צרכי עמך ודעתם קצרה\": מדוע \"מרובים צרכי עמך\" – לפי ש\"דעתם קצרה\", אבל אילו היתה דעתם רחבה – לא הי' הענין ד\"מרובים צרכי עמך\".\nועפ\"ז יובן גם מאמר הגמרא שכאשר \"דעתו רחבה\" הרי הוא \"טוב לב\" – כיון שלא חסר לו דבר; יש לו כל צרכיו.\n<b>ד</b>. בהסבר הטעם שבגלל ש\"דעתם קצרה\" לכן \"מרובים צרכי עמך\", ישנם שני ענינים:\nא) על-פי רוב משפיעים לאדם מלמעלה את כל הענינים שצריך להם; אלא, שכאשר האדם רודף אחר עניני מותרות, אזי אפשר שלא זו בלבד שלא יקבל את המותרות, אלא שיאבד, חס-ושלום, גם את ההשפעה מלמעלה בהענינים שצריך להם.\nוכידוע המשל מכ\"ק אדמו\"ר הצמח-צדק נ\"ע<sup data-n=\"601\">11</sup>, שהלבושים צריכים להיות מתאימים למדת האדם, ואם הלבושים גדולים ממדתו, הרי לא זו בלבד שאינם מסייעים לההליכה, אלא אדרבה – הם עוד מסתבכים בין הרגליים, ומפריעים לההליכה.\nוכן הוא ברוחניות – \"וגלחה<sup data-n=\"602\">12</sup> את ראשה ועשתה את צפרני'\"<sup data-n=\"603\">13</sup>: כשמחפשים תחבולות בענינים הגשמיים ולהוטים אחר מותרות – הרי לא זו בלבד שאין זה מועיל, אלא זה גם מקלקל.\n<b>ה</b>. מהיכן מתחיל ענין זה – מ\"דעתם קצרה\": הוא אינו משער את מהותו, מעמדו ומצבו הרוחני, ובמילא מדמה הוא שהכל מגיע לו, הוא צריך הכל, ולכן רודף הוא אחרי מותרות.\nאבל בשעה ש\"דעתו רחבה\" – משער הוא נכון את מהותו, ובמילא מרגיש, שמה שאכן נותנים לו מלמעלה, הרי זה רק מצד חסדו יתברך, ובמילא אינו מתלונן ואינו רודף אחרי יותר מזה, בידעו שגם מה שיש לו הוא רק מצד מדת החסד.\n<b>ו</b>. ב) בהיותו בעל דעת רחבה – לא תופס מקום אצלו ענין הגשמיות, שהרי גשמיות היא במיצר ובהגבלה (\"גשמיות איז פאַרקלעמט און באַגרענעצט\"), ובדעת רחבה אין לזה שום תפיסת מקום;הענין שאחריו הוא כן רודף – הרי זה תורה ומצוות: תורה ומצוות אינם מוגבלים בההגבלה דעולם הזה, ואפילו לא בההגבלה דעולמות העליונים. זהו בלי גבול האמיתי ומרחב האמיתי, ומצד דעת רחבה – הרי זה הדבר היחיד שיש לו תפיסת מקום.\nמצד דעת רחבה אינו חושב כלל אודות גשמיות, להיותם ענינים שאינם תופסים מקום כלל אצל מי שהוא בעל דעת רחבה. הוא חושב רק אודות רוחניות, וגשמיות נוגעת לו רק במדה שיש לה שייכות לתורה ומצוות כו'.\nוכמ\"ש הרמב\"ם<sup data-n=\"604\">14</sup>, שלא נתאוו החכמים לימות המשיח בגלל גודל העושר והתענוג הגשמי שיהי' אז – שהרי ענין זה אין לו תפיסת מקום כלל, ומביא ראי' לזה ממ\"ש<sup data-n=\"605\">15</sup> \"ביום ההוא יחי' איש עגלת בקר ושתי צאן\", שיסתפקו במועט, אלא מה שנתאוו לימות המשיח הרי זה בשביל קיום התורה ומצוות והשגת אלקות שיהי' אז.\n– מעשה ביהודי חסידי שהי' ביכלתו, אבל לא רצה, להיות רב, ונעשה סוחר. בהיותו סוחר, השקיע עצמו במסחר יתר על המדה. כתב לו הרבי במכתב<sup data-n=\"606\">16</sup>: \"כי לא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם\"<sup data-n=\"607\">17</sup>, היינו, שהגוף רעב ללחם הגשמי, בגלל שהנשמה רעבה להניצוץ אלקי שבהמאכל, וזה פועל על הגוף שיהי' רעב ללחם הגשמי<sup data-n=\"608\">18</sup>. ונמצא, שהעיקר הוא הענין האלקי שבזה, ולא הגשמי. –\nוזהו \"מרובים צרכי עמך ודעתם קצרה\", שמצד קוצר הדעת, יש תפיסת מקום אצלו להגשמיות, ומצד זה \"מרובים צרכי עמך\". אבל כש\"דעתו רחבה\", הנה מצד הרחבת הדעת, אין הגשמיות תופסת מקום כלל, ובמילא הרי הוא תמיד במצב ד\"וטוב לב משתה תמיד\".\n<b>ז</b>. אמנם, אנו מבקשים על \"מרובים צרכי עמך ודעתם קצרה\" – שהקב\"ה ימלא את כל צרכי עמך המרובים, אף שהם נמשכים מזה ש\"דעתם קצרה\".\nוהביאור בזה:\n\"שבע יפול צדיק וקם\"<sup data-n=\"609\">19</sup>, היינו, שאפילו צדיק אינו תמיד במצבשוה, ומכל-שכן מי שהוא למטה ממדריגת צדיק, שאפשר לפעמים שיפול ממדריגתו, יאבד את הדעת הרחבה ויקבל דעת קצרה: א) שגשמיות תתפוס אצלו מקום, ב) ושלא ישער את מהותו.\nוזוהי הבקשה, שגם בשעה שתהי' לו דעת קצרה, לא יחסר לו דבר.\nוההמשכה היא ע\"י דעת רחבה – שכאשר עומד בכללות בדעת רחבה, אזי ממלאים את כל צרכיו, עד שגם בשעה שנופל ממדריגתו יהיו לו כל צרכיו.\nועפ\"ז יובן מאמר הגמרא \"וטוב לב משתה תמיד – זה שדעתו רחבה\": מי <b>שבכללות דעתו רחבה</b>, פועל הוא את כל ההמשכות מלמעלה, שממלאים לו כל צרכיו, ובמילא \"וטוב לב משתה <b>תמיד</b>\" – שתמיד, אפילו כשנופל ממדריגתו ויש לו קוצר הדעת, גם אז \"וטוב לב\", כיון שיש לו כל צרכיו.\n***\n<b>ח</b>. בפורים קטן לפני שלושים שנה (גם אז היתה שנה מעוברת), הי' כ\"ק מו\"ח אדמו\"ר במוסקבא, ואמר את המאמר ד\"ה וקבל היהודים.\nהמאמר נדפס כבר ב\"התמים\"<sup data-n=\"610\">20</sup>, ושם<sup data-n=\"611\">21</sup> נדפס גם מכתב שבו מבואר מצב היהדות כפי שהי' באותו הזמן ברוסיא, שהביא לאמירת ענינים אלו שכ\"ק מו\"ח אדמו\"ר דיבר אודותם בהמאמר – תשב\"ר, מסירות-נפש וכו'.\nבמאמר זה<sup data-n=\"612\">22</sup> מדובר גם אודות הענין ד\"ורעה אמונה\"<sup data-n=\"613\">23</sup>, שצריכים להמשיך את האמונה בפנימיות. וענין זה מיוסד על מאמר כ\"ק אדמו\"ר (מוהרש\"ב) נ\"ע ד\"ה כי תשא עטר\"ת<sup data-n=\"614\">24</sup>.\nוהיינו, שלמאמר הנ\"ל (ד\"ה וקבל היהודים) היו שני יסודות: א) המעמד ומצב שהי' באותו הזמן, שמצד זה דובר אודות ענין המס\"נ כו'. ב) ד\"ה כי תשא עטר\"ת.\nאך, כיון שכ\"ק מו\"ח אדמו\"ר לא פתח את המאמר הנ\"ל בפסוק \"כי תשא\", הנה ביאור הענין בנוגע לפסוק זה לא נמצא בהמאמר דתרפ\"ז.\n<b>ט</b>. מאמר ד\"ה כי תשא גו'.\n***<b>י</b>. בהפטרת<sup data-n=\"615\">25</sup> פרשתנו<sup data-n=\"616\">26</sup> מסופר אודות אלי' הנביא, מה שעשה כשהיתה עת צרה – שבאה, כמו כל עת צרה, מצד טשטוש הדיעות ובלבול המוחות. אלי' הנביא קיבץ את כל נביאי הבעל, עם כל ישראל, ואמר להם \"עד מתי אתם פוסחים על שתי הסעיפים\"<sup data-n=\"617\">27</sup>.\nלכאורה, מדוע תבע מהם אליהו \"עד מתי אתם פוסחים על שתי הסעיפים\"? הי' לו לתבוע: עד מתי אתם עובדים לבעל, הגיע הזמן שתפסיקו לעבוד את הבעל ותתחילו לומר \"הוי'<sup data-n=\"618\">28</sup> הוא האלקים\"<sup data-n=\"619\">29</sup>.\nויובן בהקדמת ביאור החילוק בין עבודה זרה ל\"פוסחים על שתי הסעיפים\".\n<b>יא</b>. לאמיתו של דבר אינו מובן: איך יתכן שיהודי יעבוד עבודה זרה? הרי ישראל הם \"מאמינים בני מאמינים\"<sup data-n=\"620\">30</sup>, ואינם שייכים לכפירה חס-ושלום כלל<sup data-n=\"621\">31</sup>.\nויובן ע\"פ מ\"ש הרמב\"ם<sup data-n=\"622\">32</sup> שההתחלה דעבודה זרה באה מצד זה שההשפעה שמלמעלה נמשכת ע\"י הכוכבים ומזלות, ולכן השתחוו ונתנו כבוד להכוכבים ומזלות, בכדי שהכוכבים ומזלות ישפיעו להם השפעות.\nהאמת היא, שאע\"פ שההשפעה נמשכת ע\"י הכוכבים והמזלות, אין לתת להם כבוד כלל, כיון שאינם אלא \"כגרזן<sup data-n=\"623\">33</sup> ביד החוצב\"<sup data-n=\"624\">34</sup>.\nוכמבואר בחסידות<sup data-n=\"625\">35</sup> החילוק בין אב ואם, שנצטוינו לחלוק להם כבוד, לכוכבים ומזלות, שלא זו בלבד שלא נצטוינו לחלוק להם כבוד, אלא עוד זאת, שזוהי גם עבירה – כי אב ואם הם בעלי בחירה, משא\"כ כוכבים ומזלות שהם \"כגרזן ביד החוצב\".ובשעה שנותנים כבוד ומשתחוים לכוכבים ומזלות – הרי זו עבודה זרה, שהיא מהעבירות החמורות ביותר, כדאיתא בגמרא<sup data-n=\"626\">36</sup>: \"חמורה עבודה זרה שכל הכופר בה כאילו מודה בתורה כולה\"<sup data-n=\"627\">37</sup>.\nונמצא, שהסיבה שעבדו עבודה זרה היתה כדי שיקבלו מהם – לפי תפיסתם המסולפת – השפעות גשמיות, דהיינו, בשביל פניות אישיות.\nוזוהי הסיבה שיהודים, שהם \"מאמינים בני מאמינים\", עלולים להיכשל, רחמנא לצלן, בחטא ע\"ז – כי אין זה באופן שהם עובדים ע\"ז באמת חס-ושלום, כי אם בשביל פניות.\n(זה שיהודי עובד את הקב\"ה, אין זה רק בכדי שישפיע לו את צרכיו, אלא להיותו מסור ונתון אליו באמת ובלב שלם, \"שלא על מנת לקבל פרס\"<sup data-n=\"628\">38</sup>. משא\"כ עובד עבודה זרה, להבדיל, הרי זה רק בשביל ההשפעות שמשפיעה).\nוזהו ג\"כ הטעם שעבדו את הבעל, כמ\"ש<sup data-n=\"629\">39</sup> \"ומן אז חדלנו גו' חסרנו כל\".\n<b>יב</b>. הגם שכללות הענין דע\"ז הוא בשביל ההשפעות שמקבלים על ידה, הרי בזה גופא ישנם שני אופנים: עבודה זרה, ו\"פוסח על שתי הסעיפים\".\nעבודה זרה פירושה, שהוא אמנם חושב באמת שהע\"ז נותנת לו השפעה. ולכן, אף שענין זה הוא בשביל פני', אעפ\"כ, הרי פני' זו היא אצלו באמת, שהוא אכן סבור שעי\"ז שיעבוד את הכוכבים ומזלות, יתנו לו השפעה.\nמשא\"כ \"פוסח על שתי הסעיפים\" – הרי זה בספק, וישנם כאלו שעומדים תמיד בספק, ומזמן לזמן תופס את עצמו (\"כאַפּט ער זיך\") שהע\"ז אין בה ממש. ועוד אופן ב\"פוסח\" – ענין השיתוף: הוא מאמין בהקב\"ה וגם בהעבודה זרה, להבדיל.\nוהרי האמת היא, שאפילו לעבוד עבודה זרה בשיתוף או משום ספק – אפילו אם אין זה אלא בדיבור בלבד או במעשה בלבד, בלי שום אמונה בלב כלל – גם זה עבירה גדולה ביותר, עד שגם על זה מוסר יהודי את נפשו, כדאיתא בתניא<sup data-n=\"630\">40</sup>.<b>יג</b>. ועפ\"ז יובן שבכו\"כ פרטים גרוע הענין ד\"פוסח על שתי הסעיפים\" יותר מעבודה זרה:\nאף שבכללות עבודה זרה היא גרועה יותר, שהרי הוא מקולקל בקביעות (\"שטענדיק פאַרדאָרבן\"), והוא כופר רחמנא לצלן – מ\"מ, בנוגע לתשובה, ה\"פוסח על שתי הסעיפים\" גרוע יותר, כי קשה יותר שה\"פוסח על שתי הסעיפים\" יעשה תשובה שלימה אמיתית.\nושני פרטים בזה:\nא) מי שהאמין בעבודה זרה, הרי בשעה ש\"תופס את עצמו\" ש\"הוי' הוא האלקים\", ועד עתה הי' בטעות מרה, מרגיש הוא את גודל החטא שעשה, ובמילא עושה הוא תשובה כדבעי, \"ושב ורפא לו\"<sup data-n=\"631\">41</sup>.\nלעומת זאת, ה\"פוסח על שתי הסעיפים\", כיון שמאמין גם בהקב\"ה, הרי אפילו לאח\"ז, אינו מרגיש כל-כך את גודל החטא, בחשבו לעצמו: וכי מה חטאתי כל-כך? הרי מלכתחילה הייתי בספק אפילו בחיצוניות, ובאמת הרי אני כמו כל בנ\"י, תמיד הייתי מאמין וכו' וכו'. ובמילא אין חרטתו באמת ואין תשובתו שלימה<sup data-n=\"632\">42</sup>.\nב) מי שמאמין בעבודה זרה שלא בשיתוף הרי הוא מקולקל בתכלית ר\"ל, הוא טועה וסבור שהבעל הוא – חס-ושלום – האלקים. אבל יתכן, שאע\"פ שהוא נפרד מאלקים אמת, מ\"מ, כללות ענין הרוחניות נוגע לו<sup data-n=\"633\">43</sup>.\nלעומת זאת, ה\"פוסח על שתי הסעיפים\" בשיתוף, הרי זה מורה על השחתה גדולה כל-כך (\"אַזאַ פאַרדאָרבנקייט\"), שלא זו בלבד שאין רצונו בשייכות לאלקים אמת, אלא שאין לו שום שייכות לכללות ענין הרוחניות<sup data-n=\"634\">44</sup>. וראי' על זה, שבידעו את האמת ש\"הוי' הוא האלקים\", נכון בעיניו להמיר – חס-ושלום – את הקב\"ה תמורת גשמיות, להמיר \"מקור מים חיים\" כדי \"לחצוב . . בארות נשברים\"<sup data-n=\"635\">45</sup>.\nעובד עבודה זרה, אם רוחניות נוגעת לו, הרי בשעה ש\"תופס אתעצמו\" בטעותו, יעשה תשובה. לעומת זאת, ה\"פוסח כו'\", כיון שענין הרוחניות אינו נוגע לו, אלא נוגע לו רק הגשמיות שלו, הרי אפילו כשיבוא אל האמת, שגשמיות תלוי' רק בהקב\"ה, גם אז לא ישוב בתשובה להקב\"ה באמת, אלא בשביל הגשמיות.\n<b>יד</b>. כל זה הוא רק בנוגע לעצמו. אבל ישנו עוד ענין שבו \"פוסח על שתי הסעיפים\" הוא גרוע מעבודה זרה, והוא: בנוגע לזולתו.\nמי שעובד עבודה זרה ר\"ל, אף יהודי לא ילמד ממנו. בידעם שהוא כופר, אין לאף אחד עסקים עמו. לעומת זאת, ב\"פוסח על שתי הסעיפים\", כיון שהוא גם מאמין, הרי הוא בכלל \"מחטיא את הרבים\", והמחטיא את הרבים קשה מכולם<sup data-n=\"636\">46</sup>.\n<b>טו</b>. איתא בגמרא<sup data-n=\"637\">47</sup>, שיצר הרע של עבודה זרה – ביטלו את כחו. אבל הענין ד\"פוסח על שתי הסעיפים\", גם היום הוא חזק יותר מיצר הרע דעבודה זרה, אם בדקות דדקות, אם בדקות, או עוד יותר מזה.\nישנם כאלו שבשביל פניות גשמיות – פרנסה, כבוד המדומה, ו\"מה יאמרו הבריות\" – מוותרים לפי שעה על כמה וכמה ענינים של תורה ומצוות. למשך מספר ימים או מספר שבועות, מעמיד הוא את השולחן-ערוך יחד עם הקב\"ה, כביכול, על המדף, בכדי שלא יאמרו עליו שהוא \"בטלן\", שאינו מבין את הזמן ההוה, ובפרט שכאן ב\"אמריקא\" צריכים לוותר על הדברים הישנים, להתנהג במקצת לפי רוח הזמן כו'.\nובשביל זה, כדי שלא יאמרו עליו שהוא \"בטלן\", כדי שיהי' לו כבוד המדומה, או עוד ממון (שלאמיתו של דבר מתבזבז הממון על רופאים וכו', דכיון שהממון בא שלא לפי רצונו של הקב\"ה, הרי הוא מתבזבז על ענינים בלתי-רצויים<sup data-n=\"638\">48</sup>, כיון שחסר הענין ד\"יברכך גו' וישמרך\"<sup data-n=\"639\">49</sup> \"מן המזיקים\"<sup data-n=\"640\">50</sup>) – נכון בעיניו \"למכור\", לפי שעה על-כל-פנים, את הקב\"ה, כביכול, יחד עם הנשמה שלו.\nיש לדעת, שבכו\"כ פרטים הרי זה גרוע עוד יותר מעבודה זרה, מצד הטעמים הנ\"ל:\nא) קשה יותר לעשות תשובה באמת, כיון שאינו מרגיש בתוקףכ\"כ את החטא. הוא ישלה את עצמו שחטאו אינו גדול כ\"כ, שהרי בכלל הוא יהודי ירא-שמים (\"אַן ערליכער איד\"), ומה רעש אם למשך זמן קצר וויתר על ענין מסויים בשביל פרנסה וכדומה.\nב) הוא מושחת. הוא יכול להמיר ענינים רוחניים, שהם ענינים נצחיים, בענינים גשמיים שאינם אלא לפי שעה. הוא מוכר את עולם-הבא הנצחי בשביל ממון וכבוד.\nג) הוא מחטיא את הרבים. אם ייצא, חס-ושלום, בכפירה גלוי', אזי יסלקוהו מד' אמות אלו, אבל כשעוטף ומכסה את הענינים שהם היפך התורה, באמרו שדבר שלפי שעה לא נורא (\"מאַכט ניט אויס\"), ומביא עוד \"ראי'\" מפסוק או מאמר רז\"ל – הרי הוא מחטיא את הרבים.\n<b>טז</b>. על כך היא ההוראה מההפטרה, שעיקר התביעה היא: \"עד מתי אתם פוסחים על שתי הסעיפים\", דבר זה גרוע עוד יותר מעבודה זרה.\nוכפי שהי' אז, שכל ישראל עשו תשובה ואמרו \"הוי' הוא האלקים, הוי' הוא האלקים\", ב' פעמים, עוד יותר מבשעת מתן-תורה, שבו נאמר \"אנכי הוי' אלקיך\"<sup data-n=\"641\">51</sup> פעם אחת<sup data-n=\"642\">52</sup>, כמבואר בכ\"מ שע\"י תשובה מגיעים למעלה יותר מהמצב שקודם החטא, \"כפלים לתושי'\"<sup data-n=\"643\">53</sup>;\nולא רק ב' פעמים ככה בכמות, אלא יתירה מזו, שהפעם הב' היא מדריגה נעלית באין ערוך מהפעם הא'<sup data-n=\"644\">54</sup> –\nכן הוא גם עתה: כל אלו ה\"פוסחים על שתי הסעיפים\" – צריכים לעשות תשובה, ובכפלים לתושי'.\nוכיון שישראל הם ערבים זה בזה<sup data-n=\"645\">55</sup>, מעורבים זה בזה<sup data-n=\"646\">56</sup>, לכן, האור שיקבלו ע\"י תשובתם, יומשך גם על אותם מישראל שהחטיאו, רחמנא לצלן.\nויתן השי\"ת שיהי' זה בחסד וברחמים, והמחטיאים יחד עם אלו שגררו אחריהם יעשו תשובה בכפלים לתושי', ויאמרו כולם יחד \"הוי' הוא האלקים, הוי' הוא האלקים\".\n***<b>יז</b>. לקראת פורים קטן נדפס המאמר ד\"ה ויבא משה בתוך הענן<sup data-n=\"647\">57</sup>.\nבמאמר זה מדובר אודות ענין הלבוש, שה\"ענן\" הי' הלבוש שעל ידו הי' בכחו של משה לקבל הגילוי אור.\nוכן מבואר בכ\"מ, ומהם בתניא<sup data-n=\"648\">58</sup>, שלבוש זה הוא \"כמשל הרואה בשמש דרך עששית זכה ומאירה\" (\"אספקלריא המאירה\"<sup data-n=\"649\">59</sup>), שדוקא על-ידה ביכלתו לראות את השמש, וזהו \"ויבא משה בתוך הענן\".\nאודות ענין הלבוש ישנו גם מאמר מאדמו\"ר הזקן (מהמאמרים הקצרים)<sup data-n=\"650\">60</sup>, ובו מוסיף עוד ענין שאינו מבואר בד\"ה ויבא משה הנ\"ל – שהלבוש צ\"ל בדבר גשמי דוקא.\nוז\"ל המאמר:\n<b>להבין</b> ענין תכלית בריאת האדם בעוה\"ז הוא לדבקה בו וליהנות מזיו השכינה ע\"י הלבושים, שהם בחי' ימים, כמ\"ש בזהר<sup data-n=\"651\">61</sup> ע\"פ<sup data-n=\"652\">62</sup> ואברהם זקן בא בימים וגו', ואם חסר יום א' הוה לבושא חסרה כו'. ולהבין ענין הלבושים הנ\"ל ולמה צריך ללבוש, צריך להבין ענין הנשמה שהיא כלולה מעשר דהיינו חב\"ד כו', אלא שבזה גובר יותר בחי' זו, ולכן יש ס\"ר נשמות שאין דומות זל\"ז, וכל אדם יכול להבחין מן הרע שלו על הטוב איזה מדה גובר בו יותר. אך אמנם עשר בחי' הנשמה הם בחי' נברא. ואיך תוכל לדבקה בו וליהנות מזיו השכינה. ולזה צריך ללבוש תומ\"צ. ואף שהם גשמי', כמו ציצית של צמר ותפילין של עור, מ\"מ, הרי הם מבחי' גבוה יותר, כמ\"ש<sup data-n=\"653\">63</sup> במן שהוא טל אורות ונתגשם עד שדכו במדוכה<sup data-n=\"654\">64</sup>, וכן תפילין, פ' ראשונה קדש הוא חכ\"ע כו', אלא שנתגשם כ\"כ כו' . . וענין התפלה הוא בחי' הנשמה עצמה שהיא בחי' נברא. ולכן התפלה נק' בשם נפש, כמ\"ש<sup data-n=\"655\">65</sup> ואשפוך את נפשי לפני הוי' וגו' . . בלעדה אין עלי' לתומ\"צ . . אלא שהקורא ק\"ש בלא תפילין כו'<sup data-n=\"656\">66</sup>, שבחי' יראה ואהבה צ\"ל דוקא בתפילין, שאםאין מצות אין מה להעלות. ולכן ארז\"ל<sup data-n=\"657\">67</sup> הלואי שיתפלל אדם כל היום כו', ובמ\"א אמרו<sup data-n=\"658\">68</sup> ת\"ת כנגד כולם, ושניהם אמת ע\"פ הנ\"ל. וד\"ל.\n<b>יח</b>. תוכן המאמר הוא שיש צורך בשני הענינים – תומ\"צ ותפלה: מעלת התומ\"צ היא ששרשם נעלה מאד, ולכן הרי הם לבוש שעל ידו אפשר לקבל זיו השכינה; אמנם, כיון שענין זה הוא בהעלם, לפי שהתומ\"צ נתלבשו בגשמיות, יש צורך גם בענין התפלה, כדי להעלות את התומ\"צ ולגלות את האור שבהם.\nועפ\"ז נמצא, שתורה ותפלה אינם שני ענינים נפרדים, אלא הם <b>ענין אחד</b> – \"לדבקה בו וליהנות מזיו השכינה\", שהדרך לזה היא ע\"י התומ\"צ, יחד עם התפלה שמגלה את האור שבתומ\"צ.\nולכן צריכים להיות כל היום ב' הענינים דתומ\"צ ותפלה: תומ\"צ – שבהם ישנו האור, ותפלה – היינו רושם מהתפלה שצ\"ל במשך כל היום, כי דוקא ע\"י רושם זה מעלים את התומ\"צ, ובמילא מתגלה האור.\nאמנם, עתה, קו העבודה (שהו\"ע התפלה) אינו בשלימות. ולא רק עתה בזמן הגלות, אלא גם בזמן הבית לא היתה עבודת הקרבנות בשלימות, כי אם לעתיד לבוא דוקא, שאז תהי' הקרבת הקרבנות \"כמצות רצונך\"<sup data-n=\"659\">69</sup>.\nוכיון שהאור הנמשך ע\"י תומ\"צ צריך לענין התפלה, שדוקא ע\"י התפלה מתגלה האור – לכן, עתה, שקו העבודה אינו בשלימות, גילוי זה אינו נמצא. ורק לעתיד, שאז תהי' העבודה בשלימות, אזי יהי' גם הגילוי בשלימות.\nוזהו מ\"ש<sup data-n=\"660\">70</sup> \"ונגלה כבוד הוי' וראו <b>כל בשר</b>\" – שאפילו הבשר הגשמי יראה – \"כי פי <b>הוי' </b>דיבר\", לא הגילוי דשם אלקים, אלא שם הוי', וכפי שנתבאר בהמאמר דיו\"ד שבט<sup data-n=\"661\">71</sup> בשם אדמו\"ר האמצעי<sup data-n=\"662\">72</sup>, וגילוי זה יהי' לא רק בעיני בשר של בני אדם, אלא אפילו בעיני בשר של בהמות וחיות, כמ\"ש<sup data-n=\"663\">73</sup> \"וישרנה הפרות\", כיון שאז הי' מעין הגילוי דלעתיד, ולכן היתה שירתם \"שירו לה' שיר חדש\"<sup data-n=\"664\">74</sup>, לשון זכר<sup data-n=\"665\">75</sup>.והיינו, שעי\"ז שקו העבודה יהי' לעתיד בשלימות, יתגלה האור שבהתורה ומצוות, וגילוי זה יפעל ש\"ונגלה כבוד הוי' וראו כל בשר יחדיו כי פי הוי' דיבר\".\n***\n<b>יט</b>. יום השבת בזמן המנחה הוא עת רצון, \"רעוא דכל רעוין\"<sup data-n=\"666\">76</sup>, ולכן מתבטלים אז כל הדינים.\n– בכלל, זמן המנחה הוא זמן של דינים. משא\"כ במנחת שבת – לא זו בלבד שאין אז דינים, אלא שמצד זה שהוא עת רצון, \"רעוא דרעוין\", <b>מתבטלים</b> אז הדינים<sup data-n=\"667\">77</sup>.\nוע\"ד המבואר<sup data-n=\"668\">78</sup> בענין \"באור פני מלך חיים\"<sup data-n=\"669\">79</sup>, שאפילו בשעה שאדם נידון למיתה, וכבר מוליכים אותו לאותו מקום, הנה אם ראה בדרכו את המלך – אזי \"באור פני מלך חיים\", ומתבטלים כל הדינים.\nוזהו שאומרים ב\"בני היכלא\": \"דבי' מלכא בגילופין\", ובמילא \"לית זעפין\", ומתבטלים \"הני כלבין דחציפין\".\n<b>כ</b>. במנחת שבת זו קורין \"ויקהל משה גו'\"<sup data-n=\"670\">80</sup>, ואמרו רז\"ל<sup data-n=\"671\">81</sup> על פסוק זה שמשה תיקן להם לישראל \"להקהיל קהילות בכל שבת ושבת . . ולהורות לישראל דברי תורה\".\nואיתא בשם האריז\"ל<sup data-n=\"672\">82</sup>, שעיקר הלימוד דיום השבת הוא <b>בפנימיות התורה</b>. ועתה, לאחרי התגלות תורת הבעש\"ט, ובפרט תורת אדמו\"ר הזקן, שהלביש את פנימיות התורה בהבנה והשגה – הרי עיקר הלימוד דיום השבת הוא <b>בתורת החסידות</b>.\nוהשייכות דיום השבת לתורת החסידות – כי, על יום השבת נאמר<sup data-n=\"673\">83</sup> \"קדש היא\", \"קדש מלה בגרמי'\"<sup data-n=\"674\">84</sup>, דהיינו ששבת ענינה קדושה והבדלה מעניני העולם. ולכן הלימוד השייך ליום השבת הוא לימוד החסידות, כי בחסידות המדובר אינו על עניני העולם, אלא על עניני אלקות – ספירות, נשמות והדומה<sup data-n=\"675\">85</sup>. ואפילו במקום שמדובר בחסידותאודות עניני העולם – גם אז הרי זה העולם כמו שהוא <b>בתורה</b>, והעולם כפי שהוא מצד התורה, אינו \"עולם\", מלשון העלם<sup data-n=\"676\">86</sup>.\nועפ\"ז יובן המשך הכתוב<sup data-n=\"677\">87</sup> – \"לא תבערו אש בכל מושבותיכם ביום השבת\", \"במושבות אי אתה מבעיר, אבל אתה מבעיר בבית המקדש\"<sup data-n=\"678\">88</sup> – ברוחניות הענינים<sup data-n=\"679\">89</sup>:\nענינה של אש הוא – חום ורתיחת הדמים. ועז\"נ ש\"ביום השבת\", שבו היא ההבדלה מעניני העולם (כנ\"ל), אין מקום ל\"אש\", חום ורתיחת הדמים, \"בכל מושבותיכם\", בעניני העולם, אלא רק בבית המקדש, בעניני קדושה.\nוהנה, מצינו שכל ישראל הם בבחינת שבת [דאף שבפרטיות הנה תלמידי חכמים איקרו שבת<sup data-n=\"680\">90</sup>, וכל ישראל הם בבחי' עמי הארץ לגבי תלמידי חכמים; אבל בכללות, כל ישראל הם בבחי' תלמידי חכמים, ואומות העולם הם עמי הארץ, ולכן נאמר<sup data-n=\"681\">91</sup> \"ועמדו זרים ורעו צאנכם\", ע\"ד ההנהגה דעמי הארץ לגבי תלמידי חכמים<sup data-n=\"682\">92</sup>], ולכן צריכה להיות אצלם התלהבות ורתיחת הדמים (\"דער קאָך\") בעניני קדושה בלבד, לא רק ביום השבת, אלא גם במשך כל השבוע, להיותם תמיד בבחי' שבת.\nוכדי לבוא לידי כך שתמיד תהי' ה\"אש\" רק ב\"בית-המקדש\" – הרי זה ע\"י לימוד פנימיות התורה.\n<b>כא</b>. וזהו סדר הפסוקים:\n\"ויקהל משה\" – \"להקהיל קהילות בכל שבת ושבת\" וללמוד חסידות,\nועי\"ז נפעל \"לא תבערו אש בכל מושבותיכם ביום השבת\",\nוכיון ש\"מיני' מתברכין כולהו יומין\"<sup data-n=\"683\">93</sup> – הרי זה פועל שגם במשך השבוע ילמד חסידות, ואפילו בשעה שלומד נגלה, או אפילו בשעה שעוסק בעניניו הגשמיים, יהי' ניכר הרושם של לימוד החסידות שבשבת: בהענינים הגשמיים – שיהיו ללא התלהבות (\"אָן אַ קאָך\"), ובלימוד הנגלה – יהי' ניכר שזהו יהודי שלמד חסידות.והנהגה זו, ש\"מיני' מתברכין כולהו יומין\" בעבודה (כנ\"ל), תפעל ש\"מיני'\" – מיום השבת בכלל, ובפרט ממנחת שבת שהיא עת רצון – \"מתברכין כולהו יומין\" כפשוטו בגשמיות, בבני חיי ומזוני רויחי.\n**********",[["591","1","מכאן עד סוס\"ז – הוגה ע\"י כ\"ק אדמו\"ר שליט\"א (באידית), ונדפס ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011189\" data-slug=\"likkutei-sichot\" data-id=\"1300011189\">לקו\"ש ח\"א ע' 175</a> ואילך. במהדורא זו ניתוספו עוד איזה ציוני מ\"מ, וכמה פרטים מהנחה בלתי מוגה."],["592","2","סתרצ\"ז."],["593","3","משלי טו, טו."],["594","4","ראה עטרת זקנים בשם ב\"י והגמ\"י בשם הסמ\"ק. פמ\"ג א\"א סק\"א."],["595","5","ראה לבוש ס\"א. ספר מנהגים לר\"י טורנא הל' פורים. אלי' רבה סק\"ב."],["596","6","שהכוונה בתיבה זו – לרבות ענין נוסף (מהנחה בלתי מוגה)."],["597","7","ב\"ב קמה, סע\"ב."],["598","8","מים רבים תרל\"ו פ\"א. נתבאר בד\"ה באתי לגני דיו\"ד שבט פ\"ז (לעיל ע' 18 ואילך)."],["599","9","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370123\" data-slug=\"torah-or\" data-id=\"3901370123\">תו\"א וישלח כו, רע\"ג</a>."],["600","10","סליחות לער\"ה ולנעילה – ע\"פ נוסח \"תפלה קצרה\" (ברכות כט, ב)."],["601","11","סהמ\"צ מצות תגלחת מצורע פ\"ג (דרמ\"צ קז, ב). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380867\" data-slug=\"likkutei-torah\" data-id=\"4001380867\">לקו\"ת תצא לז, ג</a>."],["602","12","תצא כא, יב."],["603","13","ראה לקו\"ת תצא שם, ב: וגלחה את ראשה – הוא ענין ההתחכמות היתירה במילי דעלמא. וראה גם סהמ\"צ שם."],["604","14","הל' מלכים פי\"ב ה\"ד."],["605","15","ישעי' ז, כא. וראה סנהדרין צד, ב. מכתב ט\"ו כסלו שנה זו (אג\"ק חי\"ד ע' קפא). וראה גם תו\"מ חט\"ז ס\"ע 282. וש\"נ."],["606","16","ראה גם \"רשימות\" חוברת ט ע' 15. אג\"ק אדמו\"ר מוהריי\"צ חי\"ד ע' תמה."],["607","17","עקב ח, ג."],["608","18","ראה כש\"ט סקצ\"ד."],["609","19","משלי כד, טז. וראה תניא חינוך קטן."],["610","20","חוברת ז ע' לו ואילך (ולאח\"ז – בסה\"מ תרפ\"ז ע' קי ואילך)."],["611","21","ע' עו ואילך (הוספות לסה\"מ שם ע' רפח ואילך)."],["612","22","פ\"ד ואילך (סה\"מ שם ס\"ע קיג ואילך)."],["613","23","תהלים לז, ג."],["614","24","סה\"מ עטר\"ת ע' רסז ואילך."],["615","25","מכאן עד סוסט\"ז – הוגה ע\"י כ\"ק אדמו\"ר שליט\"א (באידית), ונדפס ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011197\" data-slug=\"likkutei-sichot\" data-id=\"1300011197\">לקו\"ש ח\"א ע' 183</a> ואילך. במהדורא זו ניתוספו עוד איזה ציוני מ\"מ, וכמה פרטים מהנחה בלתי מוגה."],["616","26","מלכים-א יח, א ואילך."],["617","27","שם, כא."],["618","28","שם, לט. – וכפי שאכן אירע בסופו של דבר, שהתחילו בעצמם להכריז \"הוי' הוא האלקים\" (מהנחה בלתי מוגה)."],["619","29","ומזה משמע, שהענין ד\"פוסחים על שתי הסעיפים\" גרוע יותר, בפרטים מסויימים, מהענין דעבודה זרה עצמו, ולכן תביעתו של אלי' הנביא היתה (לא כל-כך על הענין דע\"ז עצמו, אלא) על זה ש\"פוסחים על שתי הסעיפים\" (מהנחה בלתי מוגה)."],["620","30","שבת צז, א."],["621","31","כמבואר ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא (פי\"ח</a>-יט) באריכות (מהנחה בלתי מוגה)."],["622","32","הל' עכו\"ם פ\"א ה\"א."],["623","33","זח\"א לו, א (ע\"פ לשון הכתוב – ישעי' יו\"ד, טו)."],["624","34","ואלו שעבדו עבודה זרה החליפו בין ה\"גרזן\" ל\"החוצב בו\" (מהנחה בלתי מוגה)."],["625","35","ראה ד\"ה מים רבים דש\"פ תולדות, מבה\"ח כסלו שנה זו פ\"ד (תו\"מ חי\"ח ע' 199 ואילך). וראה גם סהמ\"צ להצ\"צ מצות מילה פ\"ג (דרמ\"צ ו, א ואילך)."],["626","36","נדרים כה, א. וש\"נ."],["627","37","וכן לאידך גיסא (ראה ספרי ופרש\"י שלח טו, כג. ועוד). – מהנחה בלתי מוגה."],["628","38","אבות פ\"א מ\"ג."],["629","39","ירמי' מד, יח."],["630","40","ספי\"ט."],["631","41","ישעי' ו, יו\"ד."],["632","42","בענין זה ראה גם רבינו יונה ריש ברכות. הובא ברמ\"א ושו\"ע אדה\"ז או\"ח סתר\"ג. קונטרס ומעין מאמר יד פ\"ב. וראה גם מכתב י\"ג תשרי שנה זו (אג\"ק חי\"ד ריש ע' כא)."],["633","43","והיינו, שחסרונו הוא שהוא מקולקל בדיעות ר\"ל, ולא בענין האנושיות (מהנחה בלתי מוגה)."],["634","44","דהיינו ששום דבר אינו נוגע לו, מלבד הפניות האישיות שלו (מהנחה בלתי מוגה)."],["635","45","ירמי' ב, יג."],["636","46","ראה ספרי ופרש\"י תצא כג, א. ועוד."],["637","47","יומא סט, ב ובחדא\"ג שם."],["638","48","ראה גם שיחת יו\"ד שבט סמ\"ד (לעיל ע' 63). וש\"נ."],["639","49","נשא ו, כד."],["640","50","ספרי ופרש\"י עה\"פ. במדב\"ר פי\"א, ה. ועוד."],["641","51","יתרו כ, ב."],["642","52","ראה לקו\"ת דרושים לשבת שובה סה, ג. סהמ\"צ להצ\"צ מצות וידוי ותשובה פ\"ב (דרמ\"צ לח, ב ואילך). ובכ\"מ."],["643","53","איוב יא, ו. וראה שמו\"ר רפמ\"ו."],["644","54","ראה גם תו\"מ חי\"ח ע' 133."],["645","55","סנהדרין כז, סע\"ב. שבועות לט, סע\"א."],["646","56","ראה תו\"מ חי\"ח ע' 261. וש\"נ."],["647","57","נדפס לאח\"ז בסה\"מ תרנ\"ד ע' קמז ואילך."],["648","58","אגה\"ק סכ\"ט (קמט, א)."],["649","59","ראה יבמות מט, סע\"ב."],["650","60","נדפס בספר מאמרי אדה\"ז הקצרים ע' תצו."],["651","61","ח\"א רכד, א."],["652","62","חיי שרה כד, א."],["653","63","ראה זח\"ב סד, ב."],["654","64","בהעלותך יא, ח."],["655","65","שמואל-א א, טו."],["656","66","ברכות יד, סע\"ב."],["657","67","שם כא, א."],["658","68","פאה פ\"א מ\"א."],["659","69","נוסח תפלת מוסף. וראה תו\"ח ר\"פ ויחי. המשך וככה תרל\"ז פי\"ז ואילך. ועוד."],["660","70","ישעי' מ, ה."],["661","71","ד\"ה באתי לגני דיו\"ד שבט פ\"ו (לעיל ס\"ע 14 ואילך)."],["662","72","תו\"ח שמות תפח, א ואילך."],["663","73","שמואל-א ו, יב."],["664","74","תהלים צח, א. וראה ע\"ז כד, ב. זח\"ב קלז, סע\"ב ואילך."],["665","75","ראה מכילתא בשלח טו, א. הובא בתוד\"ה ה\"ג ונאמר – פסחים קטז, ב."],["666","76","זח\"ב פח, סע\"ב."],["667","77","ראה תו\"מ חי\"ז ע' 189. וש\"נ."],["668","78","סה\"מ עת\"ר ע' קח. המשך תער\"ב ח\"ג ע' א'שכא. ועוד."],["669","79","משלי טז, טו."],["670","80","ר\"פ ויקהל."],["671","81","יל\"ש ר\"פ ויקהל. הובא בשו\"ע אדה\"ז או\"ח סר\"צ ס\"ג."],["672","82","ראה טעמי המצוות להרח\"ו פ' ואתחנן. וראה תו\"מ חי\"ז ס\"ע 26. וש\"נ."],["673","83","פרשתנו לא, יד."],["674","84","זח\"ג צד, ב."],["675","85","ראה גם שיחת ש\"פ משפטים סט\"ו (לעיל ע' 90). וש\"נ."],["676","86","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380463\" data-slug=\"likkutei-torah\" data-id=\"4001380463\">לקו\"ת שלח לז, ד</a>. ובכ\"מ."],["677","87","ויקהל לה, ג."],["678","88","מכילתא עה\"פ. וראה שבת כ, א."],["679","89","ראה גם התוועדויות תשמ\"ט ח\"ב ע' 382. וש\"נ."],["680","90","ראה זח\"ג כט, א."],["681","91","ישעי' סא, ה."],["682","92","ראה זח\"ג קכד, סע\"ב ואילך (ברע\"מ)."],["683","93","זח\"ב סג, ב. פח, א."]]]]});
